import React, { useEffect, useState, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { ScrollArea } from "@/components/ui/scroll-area";
import { ChevronDown, ChevronRight, Download, Search, Undo2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { useToast } from "@/hooks/use-toast";

interface Props {
  hospitalId: string | null;
  dateRange: { start: string; end: string };
}

const JournalTab: React.FC<Props> = ({ hospitalId, dateRange }) => {
  const { toast } = useToast();
  const [entries, setEntries] = useState<any[]>([]);
  const [expanded, setExpanded] = useState<string | null>(null);
  const [lineItems, setLineItems] = useState<Record<string, any[]>>({});
  const [accounts, setAccounts] = useState<any[]>([]);
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);
  const [reversingId, setReversingId] = useState<string | null>(null);

  useEffect(() => {
    supabase.auth.getUser().then(({ data: { user } }) => {
      if (!user) return;
      supabase.from("users").select("id").eq("auth_user_id", user.id).maybeSingle()
        .then(({ data }) => setCurrentUserId(data?.id || null));
    });
  }, []);

  // Filters
  const [fromDate, setFromDate] = useState(dateRange.start);
  const [toDate, setToDate] = useState(dateRange.end);
  const [typeFilter, setTypeFilter] = useState("all");
  const [accountFilter, setAccountFilter] = useState("all");
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    setFromDate(dateRange.start);
    setToDate(dateRange.end);
  }, [dateRange]);


  const loadAccounts = useCallback(async () => {
    const { data } = await (supabase as any).from("chart_of_accounts").select("id, code, name")
      .eq("hospital_id", hospitalId!).eq("is_active", true).order("code");
    setAccounts(data || []);
  }, [hospitalId, fromDate, toDate, typeFilter, accountFilter]);

  const loadEntries = useCallback(async () => {
    let query = (supabase as any).from("journal_entries").select("*")
      .eq("hospital_id", hospitalId!)
      .gte("entry_date", fromDate).lte("entry_date", toDate)
      .order("created_at", { ascending: false }).limit(200);

    if (typeFilter === "auto") query = query.like("entry_type", "auto_%");
    else if (typeFilter === "manual") query = query.eq("entry_type", "manual");

    const { data } = await query;
    let results = data || [];

    // If account filter, we need to cross-reference
    if (accountFilter !== "all") {
      const { data: matchingLines } = await supabase.from("journal_line_items").select("journal_id")
        .eq("account_id", accountFilter);
      const journalIds = new Set((matchingLines || []).map(l => l.journal_id));
      results = results.filter(e => journalIds.has(e.id));
    }

    setEntries(results);
  }, [hospitalId, fromDate, toDate, typeFilter, accountFilter]);

  useEffect(() => {
    if (!hospitalId) return;
    loadEntries();
    loadAccounts();
  }, [hospitalId, fromDate, toDate, typeFilter, accountFilter, loadEntries, loadAccounts]);

  const reverseEntry = async (entry: any) => {
    if (!hospitalId || !currentUserId) return;
    if (!confirm(`Reverse journal entry ${entry.entry_number}? This posts a new balanced entry with debits/credits swapped and marks the original as reversed.`)) return;
    setReversingId(entry.id);
    const { data, error } = await (supabase as any).rpc("reverse_journal_entry", {
      p_hospital_id: hospitalId,
      p_journal_id: entry.id,
      p_reversed_by: currentUserId,
    });
    setReversingId(null);
    if (error || data?.status === "error") {
      toast({ title: "Reversal failed", description: error?.message || data?.message, variant: "destructive" });
      return;
    }
    toast({ title: `Reversed as ${data.reversal_entry_number} ✓` });
    loadEntries();
  };

  const toggleExpand = async (id: string) => {
    if (expanded === id) { setExpanded(null); return; }
    setExpanded(id);
    if (!lineItems[id]) {
      const { data } = await supabase.from("journal_line_items").select("*")
        .eq("journal_id", id).order("debit_amount", { ascending: false });
      setLineItems(prev => ({ ...prev, [id]: data || [] }));
    }
  };

  const fmt = (n: number) => `₹${n.toLocaleString("en-IN", { minimumFractionDigits: 2 })}`;

  const filtered = entries.filter(e =>
    !searchTerm || e.entry_number?.toLowerCase().includes(searchTerm.toLowerCase()) || e.description?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const totalDebits = filtered.reduce((s, e) => s + Number(e.total_debit || 0), 0);
  const totalCredits = filtered.reduce((s, e) => s + Number(e.total_credit || 0), 0);

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Filter Row */}
      <div className="flex-shrink-0 px-5 py-3 border-b border-border flex items-center gap-3 flex-wrap">
        <div className="flex items-center gap-1.5">
          <Input type="date" value={fromDate} onChange={(e) => setFromDate(e.target.value)} className="h-8 w-36 text-xs" />
          <span className="text-xs text-muted-foreground">to</span>
          <Input type="date" value={toDate} onChange={(e) => setToDate(e.target.value)} className="h-8 w-36 text-xs" />
        </div>

        <div className="flex gap-1.5">
          {(["all", "auto", "manual"] as const).map((t) => (
            <button key={t} onClick={() => setTypeFilter(t)}
              className={cn("text-[10px] px-3 py-1 rounded-full border transition-colors",
                typeFilter === t ? "bg-primary text-primary-foreground border-primary" : "bg-card border-border text-muted-foreground"
              )}>
              {t === "all" ? "All" : t === "auto" ? "Auto" : "Manual"}
            </button>
          ))}
        </div>

        <Select value={accountFilter} onValueChange={setAccountFilter}>
          <SelectTrigger className="h-8 w-48 text-xs"><SelectValue placeholder="Filter by account" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all" className="text-xs">All Accounts</SelectItem>
            {accounts.map(a => <SelectItem key={a.id} value={a.id} className="text-xs">{a.code} — {a.name}</SelectItem>)}
          </SelectContent>
        </Select>

        <div className="relative flex-1 min-w-[150px]">
          <Search size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input placeholder="Search entry# or description" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="pl-8 h-8 text-xs" />
        </div>

        <Button size="sm" variant="outline" className="h-8 text-[10px]"><Download size={12} className="mr-1" /> Export</Button>
      </div>

      {/* Table */}
      <ScrollArea className="flex-1">
        <div className="px-5 py-3">
          <div className="border border-border rounded-lg overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="text-xs w-8"></TableHead>
                  <TableHead className="text-xs">Entry #</TableHead>
                  <TableHead className="text-xs">Date</TableHead>
                  <TableHead className="text-xs">Description</TableHead>
                  <TableHead className="text-xs">Type</TableHead>
                  <TableHead className="text-xs text-right">Debit ₹</TableHead>
                  <TableHead className="text-xs text-right">Credit ₹</TableHead>
                  <TableHead className="text-xs">Source</TableHead>
                  <TableHead className="text-xs w-24"></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.length === 0 ? (
                  <TableRow><TableCell colSpan={9} className="text-center text-muted-foreground py-8">No journal entries</TableCell></TableRow>
                ) : (
                  filtered.map((e) => {
                    // The RPC is the authority on whether an auto-posted entry is safe to
                    // reverse (bill-anchored only) — attempt is allowed here for any
                    // non-reversed, non-reversal entry; a subledger-touching entry (fixed
                    // assets, depreciation, inventory, ...) gets a clear rejection toast.
                    const canReverse = (e.entry_type === "manual" || e.entry_type?.startsWith("auto_")) && !e.reversed_at && !e.reversal_of;
                    return (
                    <React.Fragment key={e.id}>
                      <TableRow className="cursor-pointer hover:bg-muted/50" onClick={() => toggleExpand(e.id)}>
                        <TableCell className="w-8 px-2">
                          {expanded === e.id ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                        </TableCell>
                        <TableCell className="text-xs font-mono font-semibold">{e.entry_number}</TableCell>
                        <TableCell className="text-xs">{e.entry_date}</TableCell>
                        <TableCell className="text-xs max-w-[220px] truncate">{e.description}</TableCell>
                        <TableCell>
                          <div className="flex items-center gap-1 flex-wrap">
                            <Badge variant="outline" className={cn("text-[9px] px-2 py-0",
                              e.entry_type?.startsWith("auto")
                                ? "bg-primary/10 text-primary border-primary/30"
                                : e.entry_type === "reversal"
                                ? "bg-amber-50 text-amber-700 border-amber-300"
                                : "bg-muted text-muted-foreground border-border"
                            )}>
                              {e.entry_type?.startsWith("auto") ? "AUTO" : e.entry_type === "reversal" ? "REVERSAL" : "MANUAL"}
                            </Badge>
                            {e.reversed_at && (
                              <Badge variant="outline" className="text-[9px] px-2 py-0 bg-destructive/10 text-destructive border-destructive/30">REVERSED</Badge>
                            )}
                          </div>
                        </TableCell>
                        <TableCell className="text-xs text-right font-medium">{fmt(e.total_debit)}</TableCell>
                        <TableCell className="text-xs text-right font-medium">{fmt(e.total_credit)}</TableCell>
                        <TableCell className="text-[10px] text-muted-foreground">{e.source_module || "—"}</TableCell>
                        <TableCell onClick={(ev) => ev.stopPropagation()}>
                          {canReverse && (
                            <Button
                              size="sm" variant="ghost"
                              className="h-6 px-2 text-[10px] gap-1 text-muted-foreground hover:text-destructive"
                              disabled={reversingId === e.id}
                              onClick={() => reverseEntry(e)}
                            >
                              <Undo2 size={11} /> {reversingId === e.id ? "…" : "Reverse"}
                            </Button>
                          )}
                        </TableCell>
                      </TableRow>
                      {expanded === e.id && (lineItems[e.id] || []).map((li) => (
                        <TableRow key={li.id} className="bg-muted/20">
                          <TableCell></TableCell>
                          <TableCell className="text-[10px] font-mono text-muted-foreground">{li.account_code}</TableCell>
                          <TableCell colSpan={2} className="text-[10px] font-medium">{li.account_name}</TableCell>
                          <TableCell className="text-[10px] text-muted-foreground">{li.cost_centre_id ? "•" : ""}</TableCell>
                          <TableCell className="text-[10px] text-right">{Number(li.debit_amount) > 0 ? fmt(li.debit_amount) : ""}</TableCell>
                          <TableCell className="text-[10px] text-right">{Number(li.credit_amount) > 0 ? fmt(li.credit_amount) : ""}</TableCell>
                          <TableCell></TableCell>
                          <TableCell></TableCell>
                        </TableRow>
                      ))}
                    </React.Fragment>
                    );
                  })
                )}
              </TableBody>
            </Table>
          </div>
        </div>
      </ScrollArea>

      {/* Totals Bar */}
      <div className="flex-shrink-0 h-10 bg-card border-t border-border flex items-center justify-end gap-6 px-5">
        <span className="text-xs text-muted-foreground">Total Debits: <span className="font-bold text-foreground">{fmt(totalDebits)}</span></span>
        <span className="text-xs text-muted-foreground">Total Credits: <span className="font-bold text-foreground">{fmt(totalCredits)}</span></span>
        {Math.abs(totalDebits - totalCredits) < 0.01 ? (
          <Badge variant="outline" className="text-[9px] bg-emerald-50 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400">✓ Balanced</Badge>
        ) : (
          <Badge variant="outline" className="text-[9px] bg-destructive/10 text-destructive">✗ Unbalanced</Badge>
        )}
      </div>
    </div>
  );
};

export default JournalTab;

import React, { useState, useRef, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { resolvePostAuthRoute } from "@/lib/postAuthRoute";
import { useToast } from "@/hooks/use-toast";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Mail, Smartphone, Lock, Eye, EyeOff } from "lucide-react";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

const LoginModal: React.FC<Props> = ({ open, onOpenChange }) => {
  const navigate = useNavigate();
  const { toast } = useToast();

  // Password state
  const [passEmail, setPassEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [passLoading, setPassLoading] = useState(false);

  // Email OTP state
  const [email, setEmail] = useState("");
  const [emailOtpSent, setEmailOtpSent] = useState(false);
  const [emailOtp, setEmailOtp] = useState(["", "", "", "", "", ""]);
  const [emailLoading, setEmailLoading] = useState(false);
  const emailRefs = useRef<(HTMLInputElement | null)[]>([]);

  // Phone OTP state
  const [phone, setPhone] = useState("");
  const [phoneOtpSent, setPhoneOtpSent] = useState(false);
  const [phoneOtp, setPhoneOtp] = useState(["", "", "", "", "", ""]);
  const [phoneLoading, setPhoneLoading] = useState(false);
  const phoneRefs = useRef<(HTMLInputElement | null)[]>([]);

  // Reset state when modal closes
  useEffect(() => {
    if (!open) {
      setPassEmail("");
      setPassword("");
      setEmail("");
      setEmailOtpSent(false);
      setEmailOtp(["", "", "", "", "", ""]);
      setPhone("");
      setPhoneOtpSent(false);
      setPhoneOtp(["", "", "", "", "", ""]);
    }
  }, [open]);

  // Password sign-in
  const handlePasswordSignIn = async () => {
    if (!passEmail || !password) return;
    setPassLoading(true);
    try {
      const { error } = await supabase.auth.signInWithPassword({ email: passEmail, password });
      if (error) throw error;
      toast({ title: "Welcome back! 🎉" });
      onOpenChange(false);
      navigate(await resolvePostAuthRoute(), { replace: true });
    } catch (err: any) {
      toast({ title: "Sign in failed", description: err.message, variant: "destructive" });
    } finally {
      setPassLoading(false);
    }
  };

  const handleForgotPassword = async () => {
    if (!passEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(passEmail)) {
      toast({ title: "Enter your email first", description: "We need your email to send a reset link.", variant: "destructive" });
      return;
    }
    try {
      const { error } = await supabase.auth.resetPasswordForEmail(passEmail, {
        redirectTo: `${window.location.origin}/reset-password`,
      });
      if (error) throw error;
      toast({ title: "Reset link sent!", description: `Check your inbox at ${passEmail}` });
    } catch (err: any) {
      toast({ title: "Failed to send reset link", description: err.message, variant: "destructive" });
    }
  };

  // Email OTP
  const handleSendEmailOtp = async () => {
    if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      toast({ title: "Invalid email", description: "Please enter a valid email address.", variant: "destructive" });
      return;
    }
    setEmailLoading(true);
    try {
      const { error } = await supabase.auth.signInWithOtp({ email });
      if (error) throw error;
      setEmailOtpSent(true);
      toast({ title: "OTP sent!", description: `Check your inbox at ${email}` });
      setTimeout(() => emailRefs.current[0]?.focus(), 100);
    } catch (err: any) {
      toast({ title: "Failed to send OTP", description: err.message, variant: "destructive" });
    } finally {
      setEmailLoading(false);
    }
  };

  // Phone OTP
  const handleSendPhoneOtp = async () => {
    const cleaned = phone.replace(/\s/g, "");
    if (!cleaned || cleaned.length < 10) {
      toast({ title: "Invalid phone", description: "Please enter a valid mobile number.", variant: "destructive" });
      return;
    }
    const formatted = cleaned.startsWith("+") ? cleaned : `+91${cleaned}`;
    setPhoneLoading(true);
    try {
      const { error } = await supabase.auth.signInWithOtp({ phone: formatted });
      if (error) throw error;
      setPhoneOtpSent(true);
      toast({ title: "OTP sent!", description: `Check SMS on ${formatted}` });
      setTimeout(() => phoneRefs.current[0]?.focus(), 100);
    } catch (err: any) {
      toast({ title: "Failed to send OTP", description: err.message || "Phone OTP requires SMS provider (Twilio) to be configured.", variant: "destructive" });
    } finally {
      setPhoneLoading(false);
    }
  };

  const handleOtpInput = (
    otp: string[],
    setOtp: React.Dispatch<React.SetStateAction<string[]>>,
    refs: React.MutableRefObject<(HTMLInputElement | null)[]>,
    index: number,
    value: string
  ) => {
    if (!/^\d?$/.test(value)) return;
    const newOtp = [...otp];
    newOtp[index] = value;
    setOtp(newOtp);
    if (value && index < 5) refs.current[index + 1]?.focus();
  };

  const handleOtpKeyDown = (
    otp: string[],
    refs: React.MutableRefObject<(HTMLInputElement | null)[]>,
    index: number,
    e: React.KeyboardEvent
  ) => {
    if (e.key === "Backspace" && !otp[index] && index > 0) {
      refs.current[index - 1]?.focus();
    }
  };

  const verifyEmailOtp = async () => {
    const token = emailOtp.join("");
    if (token.length !== 6) return;
    setEmailLoading(true);
    try {
      const { error } = await supabase.auth.verifyOtp({ email, token, type: "email" });
      if (error) throw error;
      toast({ title: "Welcome back! 🎉" });
      onOpenChange(false);
      navigate(await resolvePostAuthRoute(), { replace: true });
    } catch (err: any) {
      toast({ title: "Invalid OTP", description: err.message, variant: "destructive" });
    } finally {
      setEmailLoading(false);
    }
  };

  const verifyPhoneOtp = async () => {
    const token = phoneOtp.join("");
    if (token.length !== 6) return;
    const cleaned = phone.replace(/\s/g, "");
    const formatted = cleaned.startsWith("+") ? cleaned : `+91${cleaned}`;
    setPhoneLoading(true);
    try {
      const { error } = await supabase.auth.verifyOtp({ phone: formatted, token, type: "sms" });
      if (error) throw error;
      toast({ title: "Welcome back! 🎉" });
      onOpenChange(false);
      navigate(await resolvePostAuthRoute(), { replace: true });
    } catch (err: any) {
      toast({ title: "Invalid OTP", description: err.message, variant: "destructive" });
    } finally {
      setPhoneLoading(false);
    }
  };

  // Auto-verify when all 6 digits entered
  useEffect(() => {
    if (emailOtp.every((d) => d !== "") && emailOtpSent) verifyEmailOtp();
  }, [emailOtp]);

  useEffect(() => {
    if (phoneOtp.every((d) => d !== "") && phoneOtpSent) verifyPhoneOtp();
  }, [phoneOtp]);

  const renderOtpBoxes = (
    otp: string[],
    setOtp: React.Dispatch<React.SetStateAction<string[]>>,
    refs: React.MutableRefObject<(HTMLInputElement | null)[]>
  ) => (
    <div className="flex gap-2 justify-center mt-4">
      {otp.map((digit, i) => (
        <input
          key={i}
          ref={(el) => { refs.current[i] = el; }}
          type="text"
          inputMode="numeric"
          maxLength={1}
          value={digit}
          onChange={(e) => handleOtpInput(otp, setOtp, refs, i, e.target.value)}
          onKeyDown={(e) => handleOtpKeyDown(otp, refs, i, e)}
          className="w-11 h-12 text-center text-lg font-semibold border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary bg-card text-foreground"
        />
      ))}
    </div>
  );

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="text-xl">Sign in to Aumrti</DialogTitle>
          <DialogDescription>Choose your preferred sign-in method</DialogDescription>
        </DialogHeader>

        <Tabs defaultValue="password" className="mt-2">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="password" className="gap-2">
              <Lock size={16} /> Password
            </TabsTrigger>
            <TabsTrigger value="email" className="gap-2">
              <Mail size={16} /> Email OTP
            </TabsTrigger>
            <TabsTrigger value="phone" className="gap-2">
              <Smartphone size={16} /> Mobile OTP
            </TabsTrigger>
          </TabsList>

          {/* Password Tab */}
          <TabsContent value="password" className="mt-4 space-y-4">
            <div>
              <Label>Email Address</Label>
              <Input
                type="email"
                value={passEmail}
                onChange={(e) => setPassEmail(e.target.value)}
                placeholder="admin@yourhospital.com"
                className="mt-1.5"
                onKeyDown={(e) => e.key === "Enter" && handlePasswordSignIn()}
              />
            </div>
            <div>
              <Label>Password</Label>
              <div className="relative mt-1.5">
                <Input
                  type={showPassword ? "text" : "password"}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Enter your password"
                  className="pr-10"
                  onKeyDown={(e) => e.key === "Enter" && handlePasswordSignIn()}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                  tabIndex={-1}
                >
                  {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
              <button
                onClick={handleForgotPassword}
                className="text-xs text-primary hover:underline mt-1.5 block"
              >
                Forgot password?
              </button>
            </div>
            <button
              onClick={handlePasswordSignIn}
              disabled={passLoading || !passEmail || !password}
              className="w-full bg-primary text-primary-foreground py-2.5 rounded-lg text-sm font-semibold hover:bg-[hsl(220,54%,16%)] transition-colors disabled:opacity-40 disabled:pointer-events-none active:scale-[0.97]"
            >
              {passLoading ? "Signing in..." : "Sign In"}
            </button>
          </TabsContent>

          {/* Email OTP Tab */}
          <TabsContent value="email" className="mt-4 space-y-4">
            {!emailOtpSent ? (
              <>
                <div>
                  <Label>Email Address</Label>
                  <Input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="admin@yourhospital.com"
                    className="mt-1.5"
                    onKeyDown={(e) => e.key === "Enter" && handleSendEmailOtp()}
                  />
                </div>
                <button
                  onClick={handleSendEmailOtp}
                  disabled={emailLoading || !email}
                  className="w-full bg-primary text-primary-foreground py-2.5 rounded-lg text-sm font-semibold hover:bg-[hsl(220,54%,16%)] transition-colors disabled:opacity-40 disabled:pointer-events-none active:scale-[0.97]"
                >
                  {emailLoading ? "Sending..." : "Send OTP to Email"}
                </button>
              </>
            ) : (
              <div className="text-center space-y-3">
                <p className="text-sm text-muted-foreground">
                  Enter the 6-digit code sent to <strong className="text-foreground">{email}</strong>
                </p>
                {renderOtpBoxes(emailOtp, setEmailOtp, emailRefs)}
                {emailLoading && <p className="text-xs text-muted-foreground animate-pulse">Verifying...</p>}
                <button
                  onClick={() => { setEmailOtpSent(false); setEmailOtp(["", "", "", "", "", ""]); }}
                  className="text-xs text-secondary hover:underline mt-2"
                >
                  Change email
                </button>
              </div>
            )}
          </TabsContent>

          {/* Phone OTP Tab */}
          <TabsContent value="phone" className="mt-4 space-y-4">
            {!phoneOtpSent ? (
              <>
                <div>
                  <Label>Mobile Number</Label>
                  <Input
                    type="tel"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                    placeholder="+91 98765 43210"
                    className="mt-1.5"
                    onKeyDown={(e) => e.key === "Enter" && handleSendPhoneOtp()}
                  />
                  <p className="text-[11px] text-muted-foreground mt-1">
                    Requires SMS provider to be configured
                  </p>
                </div>
                <button
                  onClick={handleSendPhoneOtp}
                  disabled={phoneLoading || !phone}
                  className="w-full bg-primary text-primary-foreground py-2.5 rounded-lg text-sm font-semibold hover:bg-[hsl(220,54%,16%)] transition-colors disabled:opacity-40 disabled:pointer-events-none active:scale-[0.97]"
                >
                  {phoneLoading ? "Sending..." : "Send OTP to Mobile"}
                </button>
              </>
            ) : (
              <div className="text-center space-y-3">
                <p className="text-sm text-muted-foreground">
                  Enter the 6-digit code sent to <strong className="text-foreground">{phone}</strong>
                </p>
                {renderOtpBoxes(phoneOtp, setPhoneOtp, phoneRefs)}
                {phoneLoading && <p className="text-xs text-muted-foreground animate-pulse">Verifying...</p>}
                <button
                  onClick={() => { setPhoneOtpSent(false); setPhoneOtp(["", "", "", "", "", ""]); }}
                  className="text-xs text-secondary hover:underline mt-2"
                >
                  Change number
                </button>
              </div>
            )}
          </TabsContent>
        </Tabs>

        <div className="text-center mt-2 pt-3 border-t border-border">
          <p className="text-[13px] text-muted-foreground">
            New hospital?{" "}
            <button
              onClick={() => { onOpenChange(false); navigate("/register"); }}
              className="text-primary font-medium hover:underline"
            >
              Register here →
            </button>
          </p>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default LoginModal;

import { useState, useEffect, useCallback } from "react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Search, Plus, Save, X, RefreshCw } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

interface Props {
  system: string;
  showNew: boolean;
  onShowNewDone: () => void;
}

interface DrugItem {
  drug_name: string;
  formulation_type: string;
  dose: string;
  anupana: string;
  frequency: string;
  duration: string;
}

interface AyushToken {
  id: string;
  token_number: string;
  token_prefix: string;
  status: string;
  created_at: string;
  patient_id: string;
  doctor_id: string | null;
  patient?: { id: string; full_name: string; uhid: string; gender: string | null; dob: string | null; phone: string | null };
  doctor?: { full_name: string } | null;
}

// Map AYUSH system to department name search patterns
const SYSTEM_DEPT_MAP: Record<string, string[]> = {
  ayurveda: ["%ayurveda%", "%ayurved%"],
  homeopathy: ["%homeopathy%", "%homoeopathy%", "%homeo%"],
  unani: ["%unani%"],
  siddha: ["%siddha%"],
  yoga: ["%yoga%", "%naturopathy%", "%naturo%"],
};

const statusStyles: Record<string, string> = {
  waiting: "border-l-amber-400",
  called: "border-l-orange-400",
  in_consultation: "border-l-blue-400",
  completed: "border-l-green-400 opacity-60",
};

const statusLabel: Record<string, string> = {
  waiting: "Waiting",
  called: "Called",
  in_consultation: "With Doctor",
  completed: "Done",
};

const NADI_TEMPLATES = ["Vata dominant, irregular, thready", "Pitta dominant, sharp, bounding", "Kapha dominant, slow, steady", "Mixed Vata-Pitta"];
const TONGUE_TEMPLATES = ["Coated white", "Red/dry", "Pale", "Normal", "Yellow coating"];

export default function ConsultationTab({ system, showNew, onShowNewDone }: Props) {
  const [tokens, setTokens] = useState<AyushToken[]>([]);
  const [selectedToken, setSelectedToken] = useState<AyushToken | null>(null);
  const [search, setSearch] = useState("");
  const [recentEncounters, setRecentEncounters] = useState<any[]>([]);
  const [drugs, setDrugs] = useState<any[]>([]);
  const [hospitalId, setHospitalId] = useState<string | null>(null);
  const [userId, setUserId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  // Form state
  const [complaint, setComplaint] = useState("");
  const [nadi, setNadi] = useState("");
  const [mala, setMala] = useState("");
  const [mutra, setMutra] = useState("");
  const [jivha, setJivha] = useState("");
  const [shabda, setShabda] = useState("");
  const [sparsha, setSparsha] = useState("");
  const [drik, setDrik] = useState("");
  const [akriti, setAkriti] = useState("");
  const [diagnosis, setDiagnosis] = useState("");
  const [icdCode, setIcdCode] = useState("");
  const [prescription, setPrescription] = useState<DrugItem[]>([]);
  const [dietAdvice, setDietAdvice] = useState("");
  const [lifestyleAdvice, setLifestyleAdvice] = useState("");
  const [followUpDays, setFollowUpDays] = useState("");
  const [saving, setSaving] = useState(false);

  // Homeopathy specific
  const [modalities, setModalities] = useState("");
  const [mentalGenerals, setMentalGenerals] = useState("");
  const [physicalGenerals, setPhysicalGenerals] = useState("");
  const [miasm, setMiasm] = useState("");
  const [remedy, setRemedy] = useState("");
  const [potency, setPotency] = useState("30c");
  const [homDose, setHomDose] = useState("1 dose");

  const fetchTokens = useCallback(async () => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) { setLoading(false); return; }

    const { data: userData } = await supabase.from("users").select("id, hospital_id").eq("auth_user_id", user.id).maybeSingle();
    if (!userData) { setLoading(false); return; }
    setHospitalId(userData.hospital_id);
    setUserId(userData.id);

    // Find departments matching the selected AYUSH system
    const patterns = SYSTEM_DEPT_MAP[system] || [`%${system}%`];
    let deptIds: string[] = [];
    for (const pattern of patterns) {
      const { data: depts } = await supabase
        .from("departments")
        .select("id")
        .eq("hospital_id", userData.hospital_id)
        .ilike("name", pattern);
      if (depts) deptIds.push(...depts.map(d => d.id));
    }
    // Deduplicate
    deptIds = [...new Set(deptIds)];

    if (deptIds.length === 0) {
      setTokens([]);
      setLoading(false);
      return;
    }

    const today = new Date().toISOString().split("T")[0];
    const { data, error } = await supabase
      .from("opd_tokens")
      .select("id, token_number, token_prefix, status, created_at, patient_id, doctor_id, patient:patients(id, full_name, uhid, gender, dob, phone), doctor:users!opd_tokens_doctor_id_fkey(full_name)")
      .eq("hospital_id", userData.hospital_id)
      .in("department_id", deptIds)
      .eq("visit_date", today)
      .order("created_at", { ascending: true });

    if (error) {
      console.error("Error fetching AYUSH tokens:", error);
      toast.error("Failed to load queue");
      setLoading(false);
      return;
    }
    setTokens((data as unknown as AyushToken[]) || []);
    setLoading(false);
  }, [system]);

  useEffect(() => { setSelectedToken(null); setLoading(true); fetchTokens(); }, [fetchTokens]);

  // Realtime
  useEffect(() => {
    if (!hospitalId) return;
    const channel = supabase
      .channel(`ayush-tokens-${system}`)
      .on("postgres_changes", { event: "*", schema: "public", table: "opd_tokens", filter: `hospital_id=eq.${hospitalId}` }, () => fetchTokens())
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [hospitalId, system, fetchTokens]);

  useEffect(() => { loadDrugs(); }, []);

  const selectedPatient = selectedToken?.patient || null;


  const loadDrugs = async () => {
    const { data } = await supabase.from("ayush_drug_master").select("*").eq("is_active", true).order("drug_name");
    if (data) setDrugs(data);
  };

  const loadRecentEncounters = useCallback(async () => {
    if (!selectedPatient) return;
    const { data } = await supabase.from("ayush_encounters").select("*")
      .eq("patient_id", selectedPatient.id).order("encounter_date", { ascending: false }).limit(10);
    if (data) setRecentEncounters(data);
  }, [selectedPatient]);

  useEffect(() => {
    if (selectedPatient) loadRecentEncounters();
  }, [loadRecentEncounters]);

  const addDrug = () => {
    setPrescription([...prescription, { drug_name: "", formulation_type: "", dose: "", anupana: "", frequency: "Twice daily", duration: "15 days" }]);
  };

  const updateDrug = (idx: number, field: keyof DrugItem, value: string) => {
    const updated = [...prescription];
    updated[idx] = { ...updated[idx], [field]: value };
    setPrescription(updated);
  };

  const selectDrugFromMaster = (idx: number, drugId: string) => {
    const drug = drugs.find((d: any) => d.id === drugId);
    if (!drug) return;
    const updated = [...prescription];
    updated[idx] = {
      ...updated[idx],
      drug_name: drug.drug_name,
      formulation_type: drug.formulation_type,
      dose: drug.dose_adult || "",
      anupana: drug.anupana || "",
    };
    setPrescription(updated);
  };

  const removeDrug = (idx: number) => {
    setPrescription(prescription.filter((_, i) => i !== idx));
  };

  const resetForm = () => {
    setComplaint(""); setNadi(""); setMala(""); setMutra(""); setJivha("");
    setShabda(""); setSparsha(""); setDrik(""); setAkriti("");
    setDiagnosis(""); setIcdCode(""); setPrescription([]);
    setDietAdvice(""); setLifestyleAdvice(""); setFollowUpDays("");
    setModalities(""); setMentalGenerals(""); setPhysicalGenerals("");
    setMiasm(""); setRemedy(""); setPotency("30c"); setHomDose("1 dose");
  };

  const saveConsultation = async () => {
    if (!selectedPatient) { toast.error("Select a patient"); return; }
    if (!complaint.trim()) { toast.error("Enter chief complaint"); return; }
    setSaving(true);
    try {
      const { data: userData } = await supabase.auth.getUser();
      const userId = userData?.user?.id;
      const { data: userRow } = await supabase.from("users").select("id, hospital_id").eq("auth_user_id", userId).maybeSingle();
      if (!userRow) { toast.error("User not found"); return; }

      const record: any = {
        hospital_id: userRow.hospital_id,
        patient_id: selectedPatient.id,
        system,
        practitioner_id: userRow.id,
        chief_complaint: complaint,
        ayurvedic_diagnosis: diagnosis || null,
        icd_code: icdCode || null,
        prescription: prescription.length > 0 ? prescription : [],
        diet_advice: dietAdvice || null,
        lifestyle_advice: lifestyleAdvice || null,
        follow_up_days: followUpDays ? parseInt(followUpDays) : null,
      };

      if (system === "ayurveda") {
        record.nadi_pariksha = nadi || null;
        record.mala_pariksha = mala || null;
        record.mutra_pariksha = mutra || null;
        record.jivha_pariksha = jivha || null;
        record.shabda_pariksha = shabda || null;
        record.sparsha_pariksha = sparsha || null;
        record.drik_pariksha = drik || null;
        record.akriti_pariksha = akriti || null;
      }

      const { error } = await supabase.from("ayush_encounters").insert(record);
      if (error) throw error;
      toast.success("Consultation saved");
      resetForm();
      loadRecentEncounters();
    } catch (e: any) {
      toast.error(e.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const calcAge = (dob: string | null) => {
    if (!dob) return "–";
    return Math.floor((Date.now() - new Date(dob).getTime()) / 31557600000) + "y";
  };

  const filteredTokens = tokens.filter((t) => {
    if (!search) return true;
    const s = search.toLowerCase();
    return (t.patient?.full_name?.toLowerCase().includes(s) || t.patient?.uhid?.toLowerCase().includes(s) || t.token_number.includes(s));
  });

  return (
    <div className="flex h-full overflow-hidden">
      {/* Left - OPD Token Queue */}
      <div className="w-[280px] border-r flex flex-col bg-muted/20">
        <div className="p-3 border-b flex items-center gap-2">
          <div className="relative flex-1">
            <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input placeholder="Filter queue..." value={search} onChange={(e) => setSearch(e.target.value)} className="pl-8 h-9 text-sm" />
          </div>
          <Button size="icon" variant="ghost" className="h-9 w-9 shrink-0" onClick={() => { setLoading(true); fetchTokens(); }}>
            <RefreshCw className="h-4 w-4" />
          </Button>
        </div>
        <div className="flex-1 overflow-y-auto">
          {loading ? (
            <p className="text-xs text-muted-foreground text-center py-8">Loading queue...</p>
          ) : filteredTokens.length === 0 ? (
            <div className="text-center py-8 px-3">
              <p className="text-xs text-muted-foreground">No OPD tokens for this department today</p>
              <p className="text-xs text-muted-foreground mt-1">Register patients via OPD with the {system} department</p>
            </div>
          ) : (
            filteredTokens.map((t) => (
              <button
                key={t.id}
                className={`w-full text-left px-3 py-2 border-b border-l-4 text-sm hover:bg-accent/50 transition ${statusStyles[t.status] || ""} ${selectedToken?.id === t.id ? "bg-accent" : ""}`}
                onClick={() => setSelectedToken(t)}
              >
                <div className="flex items-center justify-between">
                  <p className="font-medium truncate">{t.patient?.full_name || "—"}</p>
                  <Badge variant="outline" className="text-[10px] h-5">{t.token_prefix}-{t.token_number}</Badge>
                </div>
                <p className="text-xs text-muted-foreground">{t.patient?.uhid} · {calcAge(t.patient?.dob || null)} · {statusLabel[t.status] || t.status}</p>
              </button>
            ))
          )}
        </div>
      </div>

      {/* Right - Consultation Workspace */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {!selectedPatient ? (
          <div className="flex items-center justify-center h-full text-muted-foreground">
            <p>Search and select a patient to start consultation</p>
          </div>
        ) : (
          <>
            {/* Patient Info */}
            <Card className="shadow-none">
              <CardContent className="p-3 flex items-center gap-4">
                <div>
                  <p className="font-semibold">{selectedPatient.full_name}</p>
                  <p className="text-xs text-muted-foreground">{selectedPatient.uhid} · {calcAge(selectedPatient.dob)} · {selectedPatient.gender}</p>
                </div>
                {recentEncounters.length > 0 && (
                  <Badge variant="outline" className="ml-auto">
                    Last visit: {new Date(recentEncounters[0].encounter_date).toLocaleDateString("en-IN")}
                  </Badge>
                )}
              </CardContent>
            </Card>

            {/* Chief Complaint */}
            <div>
              <Label className="text-sm font-medium">Chief Complaint *</Label>
              <Textarea value={complaint} onChange={(e) => setComplaint(e.target.value)} placeholder="Describe the main complaint..." rows={2} className="mt-1" />
            </div>

            {/* System-specific form */}
            {system === "ayurveda" && (
              <>
                <Card>
                  <CardHeader className="pb-2 pt-3 px-4">
                    <CardTitle className="text-sm">Ashtavidha Pariksha (8-fold Examination)</CardTitle>
                  </CardHeader>
                  <CardContent className="px-4 pb-3">
                    <Accordion type="multiple" className="space-y-0">
                      <AccordionItem value="nadi">
                        <AccordionTrigger className="text-sm py-2">🖐️ Nadi (Pulse)</AccordionTrigger>
                        <AccordionContent className="space-y-2">
                          <div className="flex gap-1 flex-wrap">
                            {NADI_TEMPLATES.map((t) => (
                              <Button key={t} size="sm" variant="outline" className="text-xs h-7" onClick={() => setNadi(t)}>{t.split(",")[0]}</Button>
                            ))}
                          </div>
                          <Input value={nadi} onChange={(e) => setNadi(e.target.value)} placeholder="Pulse examination findings" />
                        </AccordionContent>
                      </AccordionItem>
                      <AccordionItem value="mala">
                        <AccordionTrigger className="text-sm py-2">💩 Mala (Stool)</AccordionTrigger>
                        <AccordionContent>
                          <Input value={mala} onChange={(e) => setMala(e.target.value)} placeholder="Stool examination findings" />
                        </AccordionContent>
                      </AccordionItem>
                      <AccordionItem value="mutra">
                        <AccordionTrigger className="text-sm py-2">💧 Mutra (Urine)</AccordionTrigger>
                        <AccordionContent>
                          <Input value={mutra} onChange={(e) => setMutra(e.target.value)} placeholder="Urine examination findings" />
                        </AccordionContent>
                      </AccordionItem>
                      <AccordionItem value="jivha">
                        <AccordionTrigger className="text-sm py-2">👅 Jivha (Tongue)</AccordionTrigger>
                        <AccordionContent className="space-y-2">
                          <div className="flex gap-1 flex-wrap">
                            {TONGUE_TEMPLATES.map((t) => (
                              <Button key={t} size="sm" variant="outline" className="text-xs h-7" onClick={() => setJivha(t)}>{t}</Button>
                            ))}
                          </div>
                          <Input value={jivha} onChange={(e) => setJivha(e.target.value)} placeholder="Tongue examination findings" />
                        </AccordionContent>
                      </AccordionItem>
                      <AccordionItem value="shabda">
                        <AccordionTrigger className="text-sm py-2">🗣️ Shabda (Voice)</AccordionTrigger>
                        <AccordionContent>
                          <Input value={shabda} onChange={(e) => setShabda(e.target.value)} placeholder="Voice/sound findings" />
                        </AccordionContent>
                      </AccordionItem>
                      <AccordionItem value="sparsha">
                        <AccordionTrigger className="text-sm py-2">✋ Sparsha (Touch)</AccordionTrigger>
                        <AccordionContent>
                          <Input value={sparsha} onChange={(e) => setSparsha(e.target.value)} placeholder="Skin/touch findings" />
                        </AccordionContent>
                      </AccordionItem>
                      <AccordionItem value="drik">
                        <AccordionTrigger className="text-sm py-2">👁️ Drik (Eyes)</AccordionTrigger>
                        <AccordionContent>
                          <Input value={drik} onChange={(e) => setDrik(e.target.value)} placeholder="Eye examination findings" />
                        </AccordionContent>
                      </AccordionItem>
                      <AccordionItem value="akriti">
                        <AccordionTrigger className="text-sm py-2">🧍 Akriti (Appearance)</AccordionTrigger>
                        <AccordionContent>
                          <Input value={akriti} onChange={(e) => setAkriti(e.target.value)} placeholder="Build/appearance findings" />
                        </AccordionContent>
                      </AccordionItem>
                    </Accordion>
                  </CardContent>
                </Card>
              </>
            )}

            {system === "homeopathy" && (
              <Card>
                <CardHeader className="pb-2 pt-3 px-4">
                  <CardTitle className="text-sm">Homeopathic Case Taking</CardTitle>
                </CardHeader>
                <CardContent className="px-4 pb-3 space-y-3">
                  <div>
                    <Label className="text-xs">Modalities (better/worse)</Label>
                    <Textarea value={modalities} onChange={(e) => setModalities(e.target.value)} rows={2} placeholder="Better by warmth, worse in morning..." />
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <Label className="text-xs">Mental Generals</Label>
                      <Textarea value={mentalGenerals} onChange={(e) => setMentalGenerals(e.target.value)} rows={2} />
                    </div>
                    <div>
                      <Label className="text-xs">Physical Generals</Label>
                      <Textarea value={physicalGenerals} onChange={(e) => setPhysicalGenerals(e.target.value)} rows={2} />
                    </div>
                  </div>
                  <div>
                    <Label className="text-xs">Miasmatic Tendency</Label>
                    <Select value={miasm} onValueChange={setMiasm}>
                      <SelectTrigger><SelectValue placeholder="Select miasm" /></SelectTrigger>
                      <SelectContent>
                        <SelectItem value="psora">Psora</SelectItem>
                        <SelectItem value="sycosis">Sycosis</SelectItem>
                        <SelectItem value="syphilis">Syphilis</SelectItem>
                        <SelectItem value="tubercular">Tubercular</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="grid grid-cols-3 gap-3">
                    <div>
                      <Label className="text-xs">Remedy</Label>
                      <Input value={remedy} onChange={(e) => setRemedy(e.target.value)} placeholder="e.g. Nux Vomica" />
                    </div>
                    <div>
                      <Label className="text-xs">Potency</Label>
                      <Select value={potency} onValueChange={setPotency}>
                        <SelectTrigger><SelectValue /></SelectTrigger>
                        <SelectContent>
                          {["6c", "12c", "30c", "200c", "1M", "10M"].map((p) => (
                            <SelectItem key={p} value={p}>{p}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div>
                      <Label className="text-xs">Dose</Label>
                      <Select value={homDose} onValueChange={setHomDose}>
                        <SelectTrigger><SelectValue /></SelectTrigger>
                        <SelectContent>
                          <SelectItem value="1 dose">1 dose</SelectItem>
                          <SelectItem value="3 doses daily">3 doses daily</SelectItem>
                          <SelectItem value="Morning and night">Morning & night</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                  </div>
                </CardContent>
              </Card>
            )}

            {/* Diagnosis */}
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="text-sm">Ayurvedic Diagnosis</Label>
                <Input value={diagnosis} onChange={(e) => setDiagnosis(e.target.value)} placeholder="e.g. Vataja Jwara, Pitta prakopa" className="mt-1" />
              </div>
              <div>
                <Label className="text-sm">ICD Code (optional)</Label>
                <Input value={icdCode} onChange={(e) => setIcdCode(e.target.value)} placeholder="e.g. R50.9" className="mt-1" />
              </div>
            </div>

            {/* Prescription */}
            {system !== "homeopathy" && (
              <Card>
                <CardHeader className="pb-2 pt-3 px-4 flex flex-row items-center justify-between">
                  <CardTitle className="text-sm">Prescription</CardTitle>
                  <Button size="sm" variant="outline" onClick={addDrug}><Plus className="h-3 w-3 mr-1" /> Add Medicine</Button>
                </CardHeader>
                <CardContent className="px-4 pb-3 space-y-2">
                  {prescription.map((rx, idx) => (
                    <div key={idx} className="grid grid-cols-7 gap-2 items-end">
                      <div className="col-span-2">
                        <Label className="text-xs">Drug</Label>
                        <Select onValueChange={(v) => selectDrugFromMaster(idx, v)}>
                          <SelectTrigger className="h-8 text-xs">
                            <SelectValue placeholder={rx.drug_name || "Select drug"} />
                          </SelectTrigger>
                          <SelectContent>
                            {drugs.map((d: any) => (
                              <SelectItem key={d.id} value={d.id} className="text-xs">{d.drug_name} ({d.formulation_type})</SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                      <div>
                        <Label className="text-xs">Dose</Label>
                        <Input className="h-8 text-xs" value={rx.dose} onChange={(e) => updateDrug(idx, "dose", e.target.value)} />
                      </div>
                      <div>
                        <Label className="text-xs">Anupana</Label>
                        <Input className="h-8 text-xs" value={rx.anupana} onChange={(e) => updateDrug(idx, "anupana", e.target.value)} />
                      </div>
                      <div>
                        <Label className="text-xs">Frequency</Label>
                        <Input className="h-8 text-xs" value={rx.frequency} onChange={(e) => updateDrug(idx, "frequency", e.target.value)} />
                      </div>
                      <div>
                        <Label className="text-xs">Duration</Label>
                        <Input className="h-8 text-xs" value={rx.duration} onChange={(e) => updateDrug(idx, "duration", e.target.value)} />
                      </div>
                      <Button size="sm" variant="ghost" className="h-8 w-8 p-0" onClick={() => removeDrug(idx)}>
                        <X className="h-3 w-3" />
                      </Button>
                    </div>
                  ))}
                  {prescription.length === 0 && (
                    <p className="text-xs text-muted-foreground text-center py-2">No medicines added</p>
                  )}
                </CardContent>
              </Card>
            )}

            {/* Diet & Lifestyle */}
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="text-sm">Diet Advice</Label>
                <Textarea value={dietAdvice} onChange={(e) => setDietAdvice(e.target.value)} rows={3} placeholder="Dietary recommendations..." className="mt-1" />
              </div>
              <div>
                <Label className="text-sm">Lifestyle Advice</Label>
                <Textarea value={lifestyleAdvice} onChange={(e) => setLifestyleAdvice(e.target.value)} rows={3} placeholder="Lifestyle recommendations..." className="mt-1" />
              </div>
            </div>

            {/* Follow-up */}
            <div className="flex items-center gap-2">
              <Label className="text-sm">Follow-up after</Label>
              <Input type="number" value={followUpDays} onChange={(e) => setFollowUpDays(e.target.value)} className="w-20 h-8" />
              <span className="text-sm text-muted-foreground">days</span>
            </div>

            {/* Save */}
            <div className="flex justify-end pb-4">
              <Button onClick={saveConsultation} disabled={saving}>
                <Save className="h-4 w-4 mr-1" /> {saving ? "Saving..." : "Save Consultation"}
              </Button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Search, Save, Sparkles } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { callAI } from "@/lib/aiProvider";

const QUESTIONS = [
  { q: "Body frame", v: "Thin / lean", p: "Medium / muscular", k: "Heavy / stout" },
  { q: "Body weight", v: "Low, hard to gain", p: "Moderate, manageable", k: "Heavy, hard to lose" },
