  { q: "Hair quality", v: "Dry / frizzy / thin", p: "Fine / early greying", k: "Thick / oily / lustrous" },
  { q: "Face shape", v: "Long / angular", p: "Heart-shaped / pointed chin", k: "Round / full" },
  { q: "Eyes", v: "Small / dry / restless", p: "Sharp / penetrating", k: "Large / calm / moist" },
  { q: "Appetite", v: "Variable / irregular", p: "Strong / frequent hunger", k: "Slow / steady" },
  { q: "Digestion", v: "Irregular / bloating", p: "Quick / acidic tendency", k: "Slow but steady" },
  { q: "Thirst", v: "Variable", p: "Excessive", k: "Scanty" },
  { q: "Bowel habits", v: "Dry / constipated", p: "Loose / frequent", k: "Regular / heavy" },
  { q: "Sweat", v: "Scanty", p: "Profuse / strong odour", k: "Moderate / cool" },
  { q: "Sleep quality", v: "Light / interrupted", p: "Moderate / sound", k: "Heavy / prolonged" },
  { q: "Dreams", v: "Flying / running / fearful", p: "Fire / anger / vivid", k: "Water / romantic / calm" },
  { q: "Stamina", v: "Low endurance, tires fast", p: "Good, overheats quickly", k: "Excellent, slow to start" },
  { q: "Walking pace", v: "Fast / restless", p: "Purposeful / determined", k: "Slow / steady" },
  { q: "Voice quality", v: "Weak / hoarse", p: "Sharp / clear", k: "Deep / melodious" },
  { q: "Speech pattern", v: "Fast / talkative / tangential", p: "Sharp / argumentative", k: "Slow / measured / few words" },
  { q: "Mental activity", v: "Restless / many ideas", p: "Focused / logical", k: "Calm / steady / contemplative" },
  { q: "Memory", v: "Quick to learn, forget fast", p: "Sharp and precise", k: "Slow to learn, never forgets" },
  { q: "Emotional nature", v: "Anxious / fearful", p: "Irritable / ambitious", k: "Calm / attached" },
  { q: "Under stress", v: "Worry / anxiety", p: "Anger / frustration", k: "Withdrawal / depression" },
  { q: "Spending habit", v: "Impulsive / poor saving", p: "Planned / moderate", k: "Thrifty / saves well" },
  { q: "Creativity", v: "Very creative / artistic", p: "Inventive / technical", k: "Steady / methodical" },
  { q: "Tolerance to cold", v: "Dislikes cold, prefers warmth", p: "Prefers cold, dislikes heat", k: "Tolerates cold well" },
  { q: "Pulse character", v: "Irregular, snake-like", p: "Bounding, frog-like", k: "Steady, swan-like" },
  { q: "Joint health", v: "Cracking / dry joints", p: "Loose / flexible", k: "Large / well-lubricated" },
  { q: "Nail quality", v: "Brittle / ridged", p: "Soft / pink", k: "Thick / white / strong" },
  { q: "Social nature", v: "Makes friends fast, changes often", p: "Selective / competitive", k: "Loyal / long-lasting bonds" },
  { q: "Faith / belief", v: "Changeable", p: "Fanatic / determined", k: "Steady / devotional" },
];

export default function PrakritiTab() {
  const [search, setSearch] = useState("");
  const [patients, setPatients] = useState<any[]>([]);
  const [selectedPatient, setSelectedPatient] = useState<any>(null);
  const [existingAssessment, setExistingAssessment] = useState<any>(null);
  const [responses, setResponses] = useState<Record<number, "v" | "p" | "k">>({});
  const [saving, setSaving] = useState(false);
  const [aiSummary, setAiSummary] = useState("");
  const [loadingAI, setLoadingAI] = useState(false);
  const [hospitalId, setHospitalId] = useState<string | null>(null);
  const [loadingPatients, setLoadingPatients] = useState(false);

  useEffect(() => {
    const loadHospitalContext = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data, error } = await supabase
        .from("users")
        .select("hospital_id")
        .eq("auth_user_id", user.id)
        .maybeSingle();

      if (error) {
        console.error("Hospital context error:", error.message);
        return;
      }

      setHospitalId(data?.hospital_id ?? null);
    };

    loadHospitalContext();
  }, []);

  useEffect(() => {
    const searchPatients = async () => {
      if (search.length < 2 || !hospitalId) {
        setPatients([]);
        return;
      }

      setLoadingPatients(true);
      const { data, error } = await supabase
        .from("patients")
        .select("id, full_name, uhid, phone, dob, gender")
        .eq("hospital_id", hospitalId)
        .eq("is_active", true)
        .or(`full_name.ilike.%${search}%,uhid.ilike.%${search}%,phone.ilike.%${search}%`)
        .limit(20);

      if (error) {
        console.error("Patient search error:", error.message);
        setPatients([]);
        setLoadingPatients(false);
        return;
      }

      setPatients(data ?? []);
      setLoadingPatients(false);
    };

    if (!hospitalId && search.length >= 2) {
      setPatients([]);
      return;
    }

    searchPatients();
  }, [search, hospitalId]);


  const loadExisting = useCallback(async () => {
    if (!selectedPatient || !hospitalId) return;

    const { data, error } = await supabase.from("prakriti_assessments").select("*")
      .eq("hospital_id", hospitalId)
      .eq("patient_id", selectedPatient.id)
      .order("assessed_at", { ascending: false }).limit(1);

    if (error) {
      console.error("Assessment load error:", error.message);
      setExistingAssessment(null);
      setAiSummary("");
      setResponses({});
      return;
    }

    if (data && data.length > 0) {
      setExistingAssessment(data[0]);
      setAiSummary(data[0].prakriti_summary || "");
    } else {
      setExistingAssessment(null);
      setAiSummary("");
    }
    setResponses({});
  }, [selectedPatient, hospitalId]);

  useEffect(() => {
    if (selectedPatient) loadExisting();
  }, [loadExisting]);

  const vataScore = Object.values(responses).filter((r) => r === "v").length;
  const pittaScore = Object.values(responses).filter((r) => r === "p").length;
  const kaphaScore = Object.values(responses).filter((r) => r === "k").length;
  const totalAnswered = Object.keys(responses).length;

  const getDominantDosha = () => {
    const scores = [
      { dosha: "vata", score: vataScore },
      { dosha: "pitta", score: pittaScore },
      { dosha: "kapha", score: kaphaScore },
    ].sort((a, b) => b.score - a.score);

    if (Math.abs(scores[0].score - scores[1].score) <= 3 && Math.abs(scores[1].score - scores[2].score) <= 3) return "tridosha";
    if (Math.abs(scores[0].score - scores[1].score) <= 3) return `${scores[0].dosha}_${scores[1].dosha}`;
    return scores[0].dosha;
  };

  const generateAISummary = async () => {
    if (totalAnswered < 20) { toast.error("Answer at least 20 questions"); return; }
    setLoadingAI(true);
    try {
      const { data: userData } = await supabase.auth.getUser();
      const { data: userRow, error: userError } = await supabase.from("users").select("hospital_id").eq("auth_user_id", userData?.user?.id || "").maybeSingle();
      if (userError || !userRow?.hospital_id) throw new Error("Hospital not found");
      const dominant = getDominantDosha();
      const prompt = `Patient Prakriti Assessment: Vata=${vataScore}/30, Pitta=${pittaScore}/30, Kapha=${kaphaScore}/30. Dominant dosha: ${dominant}. Generate a concise Prakriti summary (3-4 sentences) covering: personality traits, health tendencies, and dietary/lifestyle recommendations based on Ayurvedic principles.`;
      const result = await callAI({ featureKey: "prakriti_analysis", hospitalId: userRow.hospital_id, prompt, maxTokens: 300 });
      if (result.error || !result.text) throw new Error(result.error || "AI returned empty response");
      setAiSummary(result.text);
    } catch {
      setAiSummary(`Patient is predominantly ${getDominantDosha().replace("_", "-")} constitution. Vata: ${vataScore}, Pitta: ${pittaScore}, Kapha: ${kaphaScore}.`);
    } finally {
      setLoadingAI(false);
    }
  };

  const saveAssessment = async () => {
    if (!selectedPatient) { toast.error("Select a patient"); return; }
    if (totalAnswered < 20) { toast.error("Answer at least 20 questions"); return; }
    setSaving(true);
    try {
      const { data: userData } = await supabase.auth.getUser();
      const { data: userRow, error: userError } = await supabase.from("users").select("id, hospital_id").eq("auth_user_id", userData?.user?.id || "").maybeSingle();
      if (userError || !userRow) { toast.error("User not found"); return; }

      const { error } = await supabase.from("prakriti_assessments").insert({
        hospital_id: userRow.hospital_id,
        patient_id: selectedPatient.id,
        assessed_by: userRow.id,
        responses,
        vata_score: vataScore,
        pitta_score: pittaScore,
        kapha_score: kaphaScore,
        dominant_dosha: getDominantDosha(),
        prakriti_summary: aiSummary || null,
      });
      if (error) throw error;
      toast.success("Prakriti assessment saved");
      loadExisting();
    } catch (e: any) {
      toast.error(e.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const DOSHA_COLORS: Record<string, string> = { vata: "text-blue-600", pitta: "text-red-600", kapha: "text-green-600" };

  return (
    <div className="flex h-full overflow-hidden">
      {/* Left panel */}
      <div className="w-[280px] border-r flex flex-col bg-muted/20">
        <div className="p-3 border-b">
          <div className="relative">
            <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input placeholder="Search patient..." value={search} onChange={(e) => setSearch(e.target.value)} className="pl-8 h-9 text-sm" />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto">
          {loadingPatients && <p className="px-3 py-2 text-xs text-muted-foreground">Searching patients...</p>}
          {!loadingPatients && search.length >= 2 && patients.length === 0 && (
            <p className="px-3 py-2 text-xs text-muted-foreground">No patients found</p>
          )}
          {patients.map((p) => (
            <button
              key={p.id}
              className={`w-full text-left px-3 py-2 border-b text-sm hover:bg-accent/50 ${selectedPatient?.id === p.id ? "bg-accent" : ""}`}
              onClick={() => setSelectedPatient(p)}
            >
              <p className="font-medium truncate">{p.full_name}</p>
              <p className="text-xs text-muted-foreground">{p.uhid}</p>
            </button>
          ))}
        </div>
      </div>

      {/* Right panel */}
      <div className="flex-1 overflow-y-auto p-4">
        {!selectedPatient ? (
          <div className="flex items-center justify-center h-full text-muted-foreground">Select a patient</div>
        ) : existingAssessment && totalAnswered === 0 ? (
          <div className="space-y-4">
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-base">Existing Prakriti Assessment</CardTitle>
                <p className="text-xs text-muted-foreground">Assessed on {new Date(existingAssessment.assessed_at).toLocaleDateString("en-IN")}</p>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="text-center">
                  <Badge className="text-lg px-4 py-1">{existingAssessment.dominant_dosha.replace("_", "-").toUpperCase()}</Badge>
                </div>
                <div className="grid grid-cols-3 gap-3">
                  {[
                    { label: "Vata", score: existingAssessment.vata_score, color: "bg-blue-500" },
                    { label: "Pitta", score: existingAssessment.pitta_score, color: "bg-red-500" },
                    { label: "Kapha", score: existingAssessment.kapha_score, color: "bg-green-500" },
                  ].map(({ label, score, color }) => (
                    <div key={label} className="text-center">
                      <p className="text-sm font-medium">{label}</p>
                      <p className="text-2xl font-bold font-mono">{score}/30</p>
                      <Progress value={(score / 30) * 100} className={`h-2 mt-1 [&>div]:${color}`} />
                    </div>
                  ))}
                </div>
                {existingAssessment.prakriti_summary && (
                  <p className="text-sm bg-muted/50 p-3 rounded">{existingAssessment.prakriti_summary}</p>
                )}
                <Button variant="outline" onClick={() => { setExistingAssessment(null); setResponses({}); }}>Re-assess Prakriti</Button>
              </CardContent>
            </Card>
          </div>
        ) : (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-sm font-bold">Prakriti Questionnaire ({totalAnswered}/30)</h2>
              <div className="flex gap-2 text-xs">
                <Badge variant="outline" className="text-blue-600">V: {vataScore}</Badge>
                <Badge variant="outline" className="text-red-600">P: {pittaScore}</Badge>
                <Badge variant="outline" className="text-green-600">K: {kaphaScore}</Badge>
              </div>
            </div>

            <div className="border rounded-md overflow-hidden">
              <div className="grid grid-cols-4 bg-muted px-3 py-2 text-xs font-medium">
                <div>Question</div>
                <div className="text-center text-blue-600">Vata</div>
                <div className="text-center text-red-600">Pitta</div>
                <div className="text-center text-green-600">Kapha</div>
              </div>
              {QUESTIONS.map((q, idx) => (
                <div key={idx} className={`grid grid-cols-4 px-3 py-1.5 text-xs border-t ${responses[idx] ? "bg-accent/30" : ""}`}>
                  <div className="font-medium self-center">{q.q}</div>
                  {(["v", "p", "k"] as const).map((opt) => (
                    <button
                      key={opt}
                      className={`text-center px-1 py-1 rounded transition ${
                        responses[idx] === opt
                          ? opt === "v" ? "bg-blue-100 text-blue-700 font-medium" : opt === "p" ? "bg-red-100 text-red-700 font-medium" : "bg-green-100 text-green-700 font-medium"
                          : "hover:bg-muted"
                      }`}
                      onClick={() => setResponses({ ...responses, [idx]: opt })}
                    >
                      {opt === "v" ? q.v : opt === "p" ? q.p : q.k}
                    </button>
                  ))}
                </div>
              ))}
            </div>

            {totalAnswered >= 20 && (
              <Card>
                <CardContent className="p-4 space-y-3">
                  <div className="text-center">
                    <p className="text-sm text-muted-foreground">Your Prakriti</p>
                    <Badge className="text-lg px-4 py-1 mt-1">{getDominantDosha().replace("_", "-").toUpperCase()}</Badge>
                  </div>
                  <div className="grid grid-cols-3 gap-3">
                    {[
                      { label: "Vata", score: vataScore, color: "bg-blue-500" },
                      { label: "Pitta", score: pittaScore, color: "bg-red-500" },
                      { label: "Kapha", score: kaphaScore, color: "bg-green-500" },
                    ].map(({ label, score, color }) => (
                      <div key={label} className="text-center">
                        <p className="text-sm font-medium">{label}: {score}/30</p>
                        <Progress value={(score / 30) * 100} className={`h-2 mt-1 [&>div]:${color}`} />
                      </div>
                    ))}
                  </div>
                  <Button variant="outline" size="sm" onClick={generateAISummary} disabled={loadingAI}>
                    <Sparkles className="h-3 w-3 mr-1" /> {loadingAI ? "Generating..." : "Generate AI Summary"}
                  </Button>
                  {aiSummary && <p className="text-sm bg-muted/50 p-3 rounded">{aiSummary}</p>}
                </CardContent>
              </Card>
            )}

            <div className="flex justify-end pb-4">
              <Button onClick={saveAssessment} disabled={saving || totalAnswered < 20}>
                <Save className="h-4 w-4 mr-1" /> {saving ? "Saving..." : "Save Prakriti Assessment"}
              </Button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Clock } from "lucide-react";
import type { BillRecord } from "@/pages/billing/BillingPage";
import type { PaymentRecord } from "@/components/billing/BillEditor";
import RefundModal from "@/components/billing/RefundModal";
import CollectPaymentForm from "@/components/billing/CollectPaymentForm";
import { isAdmissionBill } from "@/lib/admissionBill";
import type { BillMoney } from "@/lib/billMoney";
import { fetchOpenRefund, type OpenRefund } from "@/lib/refundRequests";

interface Props {
  bill: BillRecord;
  hospitalId: string | null;
  payments: PaymentRecord[];
  netAdvanceBalance?: number | null;
  /** Shared money contract from BillEditor — the same figures every other tab shows. */
  money: BillMoney;
  onRefresh: () => void;
}

const PaymentsTab: React.FC<Props> = ({ bill, hospitalId, payments, netAdvanceBalance, money, onRefresh }) => {
  const effectiveBalanceDue = isAdmissionBill(bill.bill_type)
    ? money.balanceDue
    : bill.balance_due;

  // Extracted so the dependency array names a plain identifier the linter can
  // check statically, rather than a cast expression.
  const billAdmissionId = (bill as any).admission_id as string | undefined;

  const [showRefundModal, setShowRefundModal] = useState(false);
  // A refund already awaiting approval for this bill. Without this the same
  // bill could have several identical pending requests raised from here.
  const [openRefund, setOpenRefund] = useState<OpenRefund | null>(null);
  // Latches on first click so a double-click cannot submit twice.
  const [refundLocked, setRefundLocked] = useState(false);

  useEffect(() => {
    let cancelled = false;
    fetchOpenRefund({ billId: bill.id, admissionId: (bill as any).admission_id ?? null })
      .then((r) => {
        if (cancelled) return;
        setOpenRefund(r);
        setRefundLocked(!!r);
      });
    return () => { cancelled = true; };
  }, [bill.id, billAdmissionId, bill.payment_status]);

  return (
    <div className="space-y-6">
      {/* Advance-settled notice for IPD bills */}
      {isAdmissionBill(bill.bill_type) && netAdvanceBalance != null && effectiveBalanceDue === 0 && bill.balance_due > 0 && (
        <div className="bg-emerald-50 border border-emerald-200 rounded-lg p-4">
          <p className="text-[13px] font-semibold text-emerald-800">Bill settled via advance</p>
          <p className="text-[12px] text-emerald-600 mt-0.5">
            Net Advance Balance (₹{netAdvanceBalance.toLocaleString("en-IN")}) covers the full bill. No cash collection needed.
          </p>
        </div>
      )}

      {/* Collect payment form (shared with the header "Pay Bill" modal) */}
      <CollectPaymentForm
        bill={bill}
        hospitalId={hospitalId}
        payments={payments}
        netAdvanceBalance={netAdvanceBalance}
        money={money}
        onRefresh={onRefresh}
      />

      {/* Payment history */}
      <div>
        <h3 className="text-sm font-bold mb-2">Payment History</h3>
        {payments.length === 0 ? (
          <p className="text-sm text-muted-foreground">No payments recorded yet.</p>
        ) : (
          <table className="w-full text-sm">
            <thead className="bg-muted/50">
              <tr className="text-[11px] font-bold uppercase text-muted-foreground">
                <th className="px-3 py-2 text-left">Date</th>
                <th className="px-3 py-2 text-left">Mode</th>
                <th className="px-3 py-2 text-right">Amount</th>
                <th className="px-3 py-2 text-left">Reference</th>
              </tr>
            </thead>
            <tbody>
              {payments.map((p) => (
                <tr key={p.id} className="border-b border-border">
                  <td className="px-3 py-2 text-xs">{p.payment_date}</td>
                  <td className="px-3 py-2 text-xs capitalize">{p.payment_mode.replace("_", " ")}</td>
                  <td className="px-3 py-2 text-right font-bold">₹{p.amount.toLocaleString("en-IN")}</td>
                  <td className="px-3 py-2 text-xs text-muted-foreground">{p.transaction_id || "—"}</td>
                </tr>
              ))}
              <tr className="font-bold">
                <td colSpan={2} className="px-3 py-2">Total Paid</td>
                <td className="px-3 py-2 text-right text-success">
                  ₹{payments.reduce((s, p) => s + p.amount, 0).toLocaleString("en-IN")}
                </td>
                <td />
              </tr>
            </tbody>
          </table>
        )}
      </div>

      {/* A refund already awaiting approval — the action is spent. */}
      {openRefund && (
        <div className="flex items-start gap-2 bg-amber-50 border border-amber-200 rounded-lg p-4 text-[12px] text-amber-900">
          <Clock size={14} className="mt-0.5 shrink-0" />
          <div>
            <p className="font-semibold text-[13px]">
              Refund of ₹{openRefund.amount.toLocaleString("en-IN", { minimumFractionDigits: 2 })} already requested
            </p>
            <p className="mt-0.5 text-amber-700">
              {openRefund.status === "approved"
                ? "Approved — awaiting disbursement."
                : "Awaiting approval in Billing → Refunds. It can be approved or rejected there."}
            </p>
          </div>
        </div>
      )}

      {/* Refund section — shown when patient has overpaid and refund not yet processed */}
      {money.settlement === "refund" && !openRefund && bill.payment_status !== 'refunded' && (
        <>
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 flex items-center justify-between">
            <div>
              <p className="text-[13px] font-semibold text-blue-800">Refund Due to Patient</p>
              <p className="text-[12px] text-blue-600 mt-0.5">
                ₹{money.refundDue.toLocaleString("en-IN", { minimumFractionDigits: 2 })} to be returned
              </p>
            </div>
            <Button
              size="sm"
              className="h-8 text-xs"
              disabled={refundLocked}
              onClick={() => { setRefundLocked(true); setShowRefundModal(true); }}
            >
              Process Refund
            </Button>
          </div>
          {showRefundModal && (
            <RefundModal
              open={showRefundModal}
              onClose={() => { setShowRefundModal(false); setRefundLocked(false); }}
              billId={bill.id}
              patientId={bill.patient_id}
              admissionId={(bill as any).admission_id ?? null}
              hospitalId={hospitalId ?? ""}
              refundAmount={money.refundDue}
              onRefunded={() => { setShowRefundModal(false); onRefresh(); }}
            />
          )}
        </>
      )}
    </div>
  );
};

export default PaymentsTab;

import React, { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useRealtimeRefetch } from "@/hooks/useRealtimeRefetch";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { useToast } from "@/hooks/use-toast";
import { Search } from "lucide-react";

interface Props {
  showRegister: boolean;
  onCloseRegister: () => void;
  onRefresh: () => void;
}

const SEROLOGY_BADGE: Record<string, string> = {
  positive: "bg-red-100 text-red-700",
  negative: "bg-green-100 text-green-700",
  vaccinated: "bg-blue-100 text-blue-700",
  unknown: "bg-amber-100 text-amber-700",
};

const MACHINE_TYPE_LABEL: Record<string, { bg: string; text: string }> = {
  clean: { bg: "bg-green-100", text: "text-green-700" },
  hbv: { bg: "bg-amber-100", text: "text-amber-700" },
  hcv: { bg: "bg-red-100", text: "text-red-700" },
  hiv: { bg: "bg-purple-100", text: "text-purple-700" },
  isolated: { bg: "bg-muted", text: "text-muted-foreground" },
};

const deriveMachineType = (hbv: string, hcv: string, hiv: string): string => {
  if (hbv === "positive") return "hbv";
  if (hcv === "positive") return "hcv";
  if (hiv === "positive") return "hiv";
  if (hbv === "unknown" || hcv === "unknown" || hiv === "unknown") return "isolated";
  return "clean";
};

const DialysisPatientsTab: React.FC<Props> = ({ showRegister, onCloseRegister, onRefresh }) => {
  const { toast } = useToast();
  const [dPatients, setDPatients] = useState<any[]>([]);
  const [allPatients, setAllPatients] = useState<any[]>([]);
  const [search, setSearch] = useState("");
  const [selectedDetail, setSelectedDetail] = useState<any>(null);
  const [sessions, setSessions] = useState<any[]>([]);

  // Registration form
  const [patientId, setPatientId] = useState("");
  const [diagnosis, setDiagnosis] = useState("esrd");
  const [accessType, setAccessType] = useState("av_fistula");
  const [accessSite, setAccessSite] = useState("");
  const [hbv, setHbv] = useState("negative");
  const [hcv, setHcv] = useState("negative");
  const [hiv, setHiv] = useState("negative");
  const [dryWeight, setDryWeight] = useState("");
  const [frequency, setFrequency] = useState("3_per_week");
  const [duration, setDuration] = useState("4");
  const [patientSearch, setPatientSearch] = useState("");

  const fetchData = async () => {
    const res = await (supabase as any).from("dialysis_patients").select("*, patients(full_name, uhid, age, gender)").eq("is_active", true).order("registered_at", { ascending: false });
    if (res.data) setDPatients(res.data);
  };

  useEffect(() => { fetchData(); }, []);

  // Live: new/updated dialysis patients and their sessions reflect without a refresh.
  // No hospital filter here — RLS scopes rows to the current hospital.
  useRealtimeRefetch({
    tables: [{ table: "dialysis_patients", filter: null }, { table: "dialysis_sessions", filter: null }],
    hospitalId: null,
    onChange: fetchData,
    channelName: "dialysis-patients",
  });

  useEffect(() => {
    if (showRegister && allPatients.length === 0) {
      supabase.from("patients").select("id, full_name, uhid").order("full_name").then(({ data }) => {
        if (data) setAllPatients(data);
      });
    }
  }, [showRegister]);

  const register = async () => {
    if (!patientId) { toast({ title: "Select a patient", variant: "destructive" }); return; }
    const { data: user } = await supabase.from("users").select("id, hospital_id").limit(1).maybeSingle();
    if (!user) return;
    const machineType = deriveMachineType(hbv, hcv, hiv);

    const { error } = await (supabase as any).from("dialysis_patients").insert({
      hospital_id: user.hospital_id,
      patient_id: patientId,
      diagnosis,
      access_type: accessType,
      access_site: accessSite || null,
      hbv_status: hbv,
      hcv_status: hcv,
      hiv_status: hiv,
      machine_type_required: machineType,
      dry_weight_kg: parseFloat(dryWeight) || null,
      dialysis_frequency: frequency,
      session_duration_hrs: parseFloat(duration) || 4,
      treating_doctor: user.id,
    });

    if (error) {
      toast({ title: error.message.includes("unique") ? "Patient already registered in dialysis" : error.message, variant: "destructive" });
      return;
    }

    toast({ title: `Patient registered — assigned to ${machineType.toUpperCase()} machines` });
    onCloseRegister();
    fetchData();
    onRefresh();
  };

  const viewDetail = async (dp: any) => {
    setSelectedDetail(dp);
    const { data } = await (supabase as any).from("dialysis_sessions").select("*").eq("dialysis_patient_id", dp.id).order("session_date", { ascending: false }).limit(20);
    if (data) setSessions(data);
  };

  const machineType = deriveMachineType(hbv, hcv, hiv);
  const mtStyle = MACHINE_TYPE_LABEL[machineType];
  const filtered = dPatients.filter(p =>
    p.patients?.full_name?.toLowerCase().includes(search.toLowerCase()) ||
    p.patients?.uhid?.toLowerCase().includes(search.toLowerCase())
  );

  const filteredAllPatients = allPatients.filter(p =>
    p.full_name?.toLowerCase().includes(patientSearch.toLowerCase()) ||
    p.uhid?.toLowerCase().includes(patientSearch.toLowerCase())
  );

  return (
    <div className="flex h-full overflow-hidden">
      {/* Patient List */}
      <div className="w-[340px] border-r border-border overflow-y-auto p-3 space-y-2 shrink-0">
        <div className="relative">
          <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search patients..." className="h-8 pl-8 text-xs" />
        </div>

        {filtered.map(p => {
          const mt = MACHINE_TYPE_LABEL[p.machine_type_required] || MACHINE_TYPE_LABEL.clean;
          return (
            <button key={p.id} onClick={() => viewDetail(p)}
              className={`w-full text-left p-3 rounded-lg border transition-colors ${selectedDetail?.id === p.id ? "border-primary bg-primary/5" : "border-border hover:bg-muted/50"}`}>
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium">{p.patients?.full_name}</span>
                <Badge className={`text-[9px] ${mt.bg} ${mt.text}`}>{p.machine_type_required.toUpperCase()}</Badge>
              </div>
              <p className="text-[10px] text-muted-foreground">{p.patients?.uhid} · {p.diagnosis.toUpperCase()} · {p.access_type.replace(/_/g, " ")}</p>
              <div className="flex gap-1 mt-1">
                <Badge className={`text-[8px] ${SEROLOGY_BADGE[p.hbv_status]}`}>HBV:{p.hbv_status}</Badge>
                <Badge className={`text-[8px] ${SEROLOGY_BADGE[p.hcv_status]}`}>HCV:{p.hcv_status}</Badge>
                <Badge className={`text-[8px] ${SEROLOGY_BADGE[p.hiv_status]}`}>HIV:{p.hiv_status}</Badge>
              </div>
            </button>
          );
        })}
        {filtered.length === 0 && <p className="text-xs text-muted-foreground text-center py-6">No dialysis patients registered</p>}
      </div>

      {/* Detail */}
      <div className="flex-1 overflow-y-auto p-4">
        {selectedDetail ? (
          <div className="space-y-4">
            <div>
              <h3 className="text-base font-bold">{selectedDetail.patients?.full_name}</h3>
              <p className="text-xs text-muted-foreground">{selectedDetail.patients?.uhid} · {selectedDetail.diagnosis.toUpperCase()} · {selectedDetail.access_type.replace(/_/g, " ")} ({selectedDetail.access_site || "—"})</p>
            </div>

            <div className="grid grid-cols-4 gap-3">
              <div className="border border-border rounded-lg p-3 text-center">
                <p className="text-xl font-bold">{sessions.length}</p>
                <p className="text-[10px] text-muted-foreground">Total Sessions</p>
              </div>
              <div className="border border-border rounded-lg p-3 text-center">
                <p className="text-xl font-bold">{sessions.filter(s => s.status === "completed").length}</p>
                <p className="text-[10px] text-muted-foreground">Completed</p>
              </div>
              <div className="border border-border rounded-lg p-3 text-center">
                <p className="text-xl font-bold">
                  {sessions.filter(s => s.kt_v).length > 0
                    ? (sessions.filter(s => s.kt_v).reduce((a, s) => a + Number(s.kt_v), 0) / sessions.filter(s => s.kt_v).length).toFixed(2)
                    : "—"}
                </p>
                <p className="text-[10px] text-muted-foreground">Avg Kt/V</p>
              </div>
              <div className="border border-border rounded-lg p-3 text-center">
                <p className="text-xl font-bold">
                  {sessions.length > 0
                    ? Math.round((sessions.filter(s => s.status === "completed").length / sessions.length) * 100)
                    : 0}%
                </p>
                <p className="text-[10px] text-muted-foreground">Compliance</p>
              </div>
            </div>

            <h4 className="text-sm font-semibold">Recent Sessions</h4>
            <div className="space-y-1">
              {sessions.map(s => (
                <div key={s.id} className="flex items-center justify-between text-xs border-b border-border py-1.5">
                  <span>{s.session_date}</span>
                  <span>Pre: {s.pre_weight_kg || "—"}kg → Post: {s.post_weight_kg || "—"}kg</span>
                  <span>Kt/V: {s.kt_v ? <span className={Number(s.kt_v) < 1.2 ? "text-red-600 font-bold" : "text-green-600"}>{s.kt_v}</span> : "—"}</span>
                  <Badge variant="outline" className="text-[9px]">{s.status}</Badge>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <p className="text-sm text-muted-foreground text-center py-12">Select a patient to view details</p>
        )}
      </div>

      {/* Registration Modal */}
      <Dialog open={showRegister} onOpenChange={onCloseRegister}>
        <DialogContent className="max-w-md max-h-[85vh] overflow-y-auto">
          <DialogHeader><DialogTitle>Register Dialysis Patient</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div>
              <Label className="text-xs">Link Patient *</Label>
              <Input value={patientSearch} onChange={e => setPatientSearch(e.target.value)} placeholder="Search by name or UHID..." className="h-9" />
              {patientSearch && (
                <div className="border border-border rounded max-h-32 overflow-y-auto mt-1">
                  {filteredAllPatients.slice(0, 10).map(p => (
                    <button key={p.id} onClick={() => { setPatientId(p.id); setPatientSearch(p.full_name); }}
                      className={`w-full text-left px-3 py-1.5 text-xs hover:bg-muted ${patientId === p.id ? "bg-primary/10" : ""}`}>
                      {p.full_name} ({p.uhid})
                    </button>
                  ))}
                </div>
              )}
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div>
                <Label className="text-xs">Diagnosis *</Label>
                <Select value={diagnosis} onValueChange={setDiagnosis}>
                  <SelectTrigger className="h-9"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {["esrd","aki","ckd_stage4","ckd_stage5","other"].map(d => <SelectItem key={d} value={d} className="uppercase text-xs">{d.replace(/_/g," ")}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label className="text-xs">Access Type *</Label>
                <Select value={accessType} onValueChange={setAccessType}>
                  <SelectTrigger className="h-9"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {["av_fistula","av_graft","tunneled_catheter","non_tunneled_catheter","peritoneal"].map(a => <SelectItem key={a} value={a} className="text-xs capitalize">{a.replace(/_/g," ")}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div><Label className="text-xs">Access Site</Label><Input value={accessSite} onChange={e => setAccessSite(e.target.value)} className="h-9" placeholder="e.g. Left arm AVF" /></div>

            <div className="border border-border rounded-lg p-3 space-y-2">
              <Label className="text-xs font-bold text-red-700">⚠️ Serology (determines machine assignment)</Label>
              <div className="grid grid-cols-3 gap-2">
                <div>
                  <Label className="text-[10px]">HBsAg</Label>
                  <Select value={hbv} onValueChange={setHbv}>
                    <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {["positive","negative","vaccinated","unknown"].map(s => <SelectItem key={s} value={s} className="text-xs capitalize">{s}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label className="text-[10px]">HCV</Label>
                  <Select value={hcv} onValueChange={setHcv}>
                    <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {["positive","negative","unknown"].map(s => <SelectItem key={s} value={s} className="text-xs capitalize">{s}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label className="text-[10px]">HIV</Label>
                  <Select value={hiv} onValueChange={setHiv}>
                    <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {["positive","negative","unknown"].map(s => <SelectItem key={s} value={s} className="text-xs capitalize">{s}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div className={`text-xs font-semibold px-3 py-1.5 rounded ${mtStyle.bg} ${mtStyle.text}`}>
                Machine Assignment: {machineType.toUpperCase()} machines
              </div>
            </div>

            <div className="grid grid-cols-3 gap-2">
              <div><Label className="text-xs">Dry Weight (kg)</Label><Input value={dryWeight} onChange={e => setDryWeight(e.target.value)} className="h-9" type="number" /></div>
              <div>
                <Label className="text-xs">Frequency</Label>
                <Select value={frequency} onValueChange={setFrequency}>
                  <SelectTrigger className="h-9 text-xs"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="2_per_week">2×/week</SelectItem>
                    <SelectItem value="3_per_week">3×/week</SelectItem>
                    <SelectItem value="daily">Daily</SelectItem>
                    <SelectItem value="alternate_day">Alternate day</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div><Label className="text-xs">Duration (hrs)</Label><Input value={duration} onChange={e => setDuration(e.target.value)} className="h-9" type="number" /></div>
            </div>

            <Button className="w-full" onClick={register} disabled={!patientId}>Register Dialysis Patient</Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

