            aiTriageResult.red_flags_detected?.length ? `Red flags: ${aiTriageResult.red_flags_detected.join(", ")}` : "",
            aiTriageResult.differentials?.[0] ? `Top Dx: ${aiTriageResult.differentials[0].diagnosis}` : "",
          ].filter(Boolean).join("\n")}
