                        {b.ward_name} — {b.bed_number}
                        {b.bed_category && b.bed_category !== "general" ? ` [${b.bed_category.toUpperCase()}]` : ""}
                        {b.oxygen_equipped ? " O₂" : ""}
                        {b.has_monitor ? " Mon" : ""}
                      </option>
                    ))}
