              {packages.length > 0 && (
                <div>
                  <label className="text-xs font-bold text-slate-600 block mb-1">Package (optional)</label>
                  <select value={packageId} onChange={(e) => {
                    setPackageId(e.target.value);
                    const pkg = packages.find(p => p.id === e.target.value);
                    if (pkg && !estimatedAmount) setEstimatedAmount(String(pkg.price));
                  }} className="w-full h-9 text-sm border rounded-md px-2 bg-white">
                    <option value="">No package</option>
                    {packages.map((p) => (
                      <option key={p.id} value={p.id}>{p.package_name} — ₹{Number(p.price).toLocaleString("en-IN")}</option>
                    ))}
                  </select>
                  {packageId && (
                    <p className="text-[10px] text-slate-500 mt-0.5">Selecting a package pre-fills the estimated amount.</p>
                  )}
                </div>
              )}

              <div>
                <label className="text-xs font-bold text-slate-600 block mb-1">Remarks (optional)</label>
                <Textarea value={estimateRemarks} onChange={(e) => setEstimateRemarks(e.target.value)}
                  placeholder="e.g. Estimate includes surgery, anaesthesia, and 3-day stay..." className="text-sm min-h-[80px]" />
              </div>

              {Number(depositRequired) > 0 && (
                <div className="flex items-start gap-2 p-2 bg-emerald-50 border border-emerald-200 rounded-lg">
                  <Info className="h-3.5 w-3.5 text-emerald-600 mt-0.5 shrink-0" />
                  <p className="text-[11px] text-emerald-700">
                    After saving, the Advance Receipt form will open pre-filled with <strong>₹{Number(depositRequired).toLocaleString("en-IN")}</strong> to collect deposit.
                  </p>
                </div>
              )}

              {/* MUST Nutritional Screening — NABH AAC requirement */}
              {!estimateOnlyMode && (
                <div className="border rounded-lg p-3 bg-muted/30 space-y-2">
                  <div className="flex items-center gap-2">
                    <span className="text-xs font-semibold text-foreground">Nutritional Screening (MUST)</span>
                    <span className="text-[10px] bg-blue-100 text-blue-700 border border-blue-200 rounded px-1.5 py-px font-medium">NABH AAC</span>
                    {(mustBmi || mustWeightLoss || mustAcuteDisease) && (
                      <span className={`text-[11px] font-bold ml-auto ${mustRiskColor}`}>
                        Score: {mustScore} — {mustRisk} Risk
                      </span>
                    )}
                  </div>
                  <div className="grid grid-cols-3 gap-2">
                    <div>
                      <label className="text-[11px] text-muted-foreground block mb-1">BMI (kg/m²)</label>
                      <input type="number" step="0.1" min="10" max="60" value={mustBmi}
                        onChange={e => setMustBmi(e.target.value)}
                        placeholder="e.g. 21.5"
                        className="w-full h-7 text-xs border border-input rounded px-2 bg-background" />
                      <p className="text-[9px] text-muted-foreground mt-0.5">0pts ≥20, 1pt 18.5–20, 2pts &lt;18.5</p>
                    </div>
                    <div>
                      <label className="text-[11px] text-muted-foreground block mb-1">Recent Weight Loss (%)</label>
                      <input type="number" step="0.1" min="0" max="50" value={mustWeightLoss}
                        onChange={e => setMustWeightLoss(e.target.value)}
                        placeholder="e.g. 7"
                        className="w-full h-7 text-xs border border-input rounded px-2 bg-background" />
                      <p className="text-[9px] text-muted-foreground mt-0.5">0pts &lt;5%, 1pt 5–10%, 2pts &gt;10%</p>
                    </div>
                    <div className="flex items-center gap-2 pt-4">
                      <input type="checkbox" id="must_acute" checked={mustAcuteDisease}
                        onChange={e => setMustAcuteDisease(e.target.checked)} className="h-4 w-4" />
                      <label htmlFor="must_acute" className="text-xs">Acute illness / nil by mouth ≥5 days (+2 pts)</label>
                    </div>
                  </div>
                </div>
              )}

              <div className="flex justify-between pt-2">
                {estimateOnlyMode ? (
                  <>
                    <Button variant="outline" onClick={onClose}>Cancel</Button>
                    <Button onClick={handleEstimateOnlySubmit} disabled={submitting || (!estimatedAmount && !depositRequired)}
                      className="bg-[#1A2F5A] hover:bg-[#152647]">
                      {submitting ? "Saving..." : "Save Estimate"}
                    </Button>
                  </>
                ) : (
                  <>
                    <Button variant="outline" onClick={() => setStep(2)}>← Back</Button>
                    <Button onClick={() => setStep(4)} className="bg-[#1A2F5A] hover:bg-[#152647]">Next →</Button>
                  </>
                )}
              </div>
            </div>
          )}

          {/* STEP 4 — Confirm */}
          {!admittedId && !estimateSaved && step === 4 && (
            <div className="space-y-3 mt-2">
              <div className="bg-slate-50 border border-slate-200 rounded-lg p-4 space-y-2">
                <p className="text-sm font-bold text-slate-900">{selectedPatient?.full_name}</p>
                <p className="text-xs text-slate-500">{selectedPatient?.uhid}</p>
                <div className="h-px bg-slate-200 my-2" />
                <Row label="Type" value={admissionType} />
                <Row label="Bed" value={bedLabel} />
                <Row label="Doctor" value={doctors.find((d) => d.id === doctorId)?.full_name || "—"} />
                <Row label="Diagnosis" value={diagnosis || "—"} />
                <Row label="Insurance" value={insuranceType.replace("_", " ")} />
                <Row label="Diet" value={dietaryInstruction.replace(/_/g, " ")} />
                {expectedDischarge && <Row label="Expected Discharge" value={expectedDischarge} />}
                {estimatedAmount && <Row label="Estimated Amount" value={`${formatINRExact(Number(estimatedAmount))}`} />}
                {depositRequired && <Row label="Deposit Required" value={`${formatINRExact(Number(depositRequired))}`} />}
                {(mustBmi || mustWeightLoss || mustAcuteDisease) && (
                  <Row label="MUST Nutritional Risk"
                    value={`Score ${mustScore} — ${mustRisk} Risk`} />
                )}
              </div>

              <FormError message={formError} className="mt-2" />

              <div className="flex justify-between pt-2">
                <Button variant="outline" onClick={() => setStep(3)}>← Back</Button>
                <Button onClick={handleAdmit} disabled={submitting} className="bg-[#1A2F5A] hover:bg-[#152647] w-40">
                  {submitting ? "Admitting..." : "✓ Confirm Admission"}
                </Button>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* Auto-open Advance Receipt after admission/estimate if deposit required */}
      {showAdvanceModal && hospitalId && activePatient && (
        <AdvanceReceiptModal
          hospitalId={hospitalId}
          prefilledPatient={{ id: activePatient.id, full_name: activePatient.full_name, uhid: activePatient.uhid }}
          prefilledAmount={Number(depositRequired) || undefined}
          admissionId={admittedId || existingAdmissionId || null}
          onClose={() => {
            setShowAdvanceModal(false);
            if (estimateOnlyMode && estimateSaved) { onAdmitted(); onClose(); }
          }}
          onCreated={() => {
            setShowAdvanceModal(false);
            toast({ title: "Deposit collected", description: `${formatINRExact(Number(depositRequired))} advance receipt created` });
            if (estimateOnlyMode && estimateSaved) { onAdmitted(); onClose(); }
          }}
        />
      )}

      {/* Consent signature modal — triggered from admission success state */}
      {showConsentModal && admittedId && selectedPatient && hospitalId && (
        <ConsentSignatureModal
          open={showConsentModal}
          onClose={() => setShowConsentModal(false)}
          admissionId={admittedId}
          patientId={selectedPatient.id}
          patientName={selectedPatient.full_name}
          hospitalId={hospitalId}
          onAllSigned={() => {
            setShowConsentModal(false);
            setConsentSigned(true);
          }}
        />
      )}
    </>
  );
};

const Row = ({ label, value }: { label: string; value: string }) => (
  <div className="flex justify-between text-xs">
    <span className="text-slate-500">{label}</span>
    <span className="text-slate-800 font-medium capitalize">{value}</span>
  </div>
);

export default AdmitPatientModal;

import React, { useState, useEffect, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { callAI } from "@/lib/aiProvider";
import { useAIFeature } from "@/hooks/useAIFeature";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Sparkles, Loader2, AlertTriangle, TrendingUp, TrendingDown } from "lucide-react";
import { cn } from "@/lib/utils";

interface Anomaly {
  test: string;
  finding: string;
  clinical_significance: string;
  action: string;
  severity: "critical" | "high" | "moderate" | "informational";
}

interface Props {
  patientId: string;
  hospitalId: string;
  currentResults: Array<{
    test_name: string;
    result_value: string | null;
    result_numeric: number | null;
    result_flag: string | null;
    unit: string | null;
    normal_min: number | null;
    normal_max: number | null;
    reference_range: string | null;
  }>;
  orderId: string;
  autoRun?: boolean;
}

const SEVERITY_STYLE: Record<string, string> = {
  critical: "bg-red-50 border-red-200 text-red-800 dark:bg-red-950/20 dark:border-red-800",
  high: "bg-orange-50 border-orange-200 text-orange-800 dark:bg-orange-950/20 dark:border-orange-800",
  moderate: "bg-amber-50 border-amber-200 text-amber-800 dark:bg-amber-950/20 dark:border-amber-800",
  informational: "bg-blue-50 border-blue-200 text-blue-800 dark:bg-blue-950/20 dark:border-blue-800",
};

const LabAnomalyDetector: React.FC<Props> = ({ patientId, hospitalId, currentResults, orderId, autoRun = false }) => {
  const __aiOn = useAIFeature("lab_anomaly");
  const [loading, setLoading] = useState(false);
  const [anomalies, setAnomalies] = useState<Anomaly[] | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const hasAutoRun = useRef(false);

  const runDetection = async () => {
    setLoading(true);
    setErrorMsg(null);
    try {
      // Fetch last 6 months of results for trend analysis
      const { data: history } = await (supabase as any)
        .from("lab_order_items")
        .select("test_name: lab_test_master(test_name), result_numeric, result_value, result_flag, lab_orders!inner(order_date, patient_id)")
        .eq("lab_orders.patient_id", patientId)
        .eq("lab_orders.hospital_id", hospitalId)
        .in("status", ["reported", "validated"])
        .order("lab_orders.order_date", { ascending: false })
        .limit(50);

      const trendMap: Record<string, number[]> = {};
      (history || []).forEach((row: any) => {
        const name = row.test_name?.test_name || row.test_name;
        if (!name || row.result_numeric == null) return;
        if (!trendMap[name]) trendMap[name] = [];
        trendMap[name].push(row.result_numeric);
      });

      const resultsText = currentResults
        .filter((r) => r.result_value)
        .map((r) => {
          const trend = trendMap[r.test_name];
          const trendStr = trend && trend.length >= 2
            ? ` [Trend: ${trend.slice(0, 3).join(" → ")}]`
            : "";
          return `${r.test_name}: ${r.result_value} ${r.unit || ""} (Range: ${r.reference_range || `${r.normal_min ?? "?"}-${r.normal_max ?? "?"}`}) Flag: ${r.result_flag || "normal"}${trendStr}`;
        }).join("\n") || "No results entered";

      const response = await callAI({
        featureKey: "lab_anomaly",
        hospitalId,
        prompt: `You are a clinical pathologist AI for an Indian hospital. Analyse these lab results for anomalies, concerning patterns, and trajectory trends.

Lab Results:
${resultsText}

Identify:
1. Critical/panic values requiring immediate action
2. Values approaching critical range or showing worsening trend
3. Patterns suggesting a specific diagnosis (e.g., anaemia panel pattern, renal failure pattern, liver disease pattern)
4. Unexpected combinations (e.g., low Hb with high WBC suggests malignancy)

Return ONLY JSON array (empty array if all normal):
[{"test":"Haemoglobin","finding":"Severe anaemia 6.2 g/dL with downward trend","clinical_significance":"Risk of cardiac decompensation. Trend suggests ongoing blood loss or haemolysis.","action":"Transfuse if symptomatic. Peripheral smear, reticulocyte count, Coombs test.","severity":"critical"}]

Provide max 4 anomalies, most critical first. Focus on actionable clinical insights.`,
        maxTokens: 500,
      });

      if (response.error) {
        setErrorMsg(response.error);
        setLoading(false);
        return;
      }

      if (!response.text) {
        setErrorMsg("AI returned an empty response. Please try again.");
        setLoading(false);
        return;
      }

      try {
        const clean = response.text.replace(/```json\n?/g, "").replace(/```\n?/g, "").trim();
        const parsed = JSON.parse(clean);
        const result = Array.isArray(parsed) ? parsed : [];
        setAnomalies(result);

        await (supabase as any).from("ai_feature_logs").insert({
          hospital_id: hospitalId,
          module: "lab",
          feature_key: "lab_anomaly",
          patient_id: patientId,
          input_summary: `${currentResults.filter(r => r.result_value).length} results, ${Object.keys(trendMap).length} with history`,
          output_summary: `${result.length} anomalies`,
          success: true,
        });
      } catch {
        setErrorMsg("AI response could not be parsed. Please try again.");
      }
    } catch (e) {
      console.error("Lab anomaly detection error:", e);
      setErrorMsg(e instanceof Error ? e.message : "Unexpected error during analysis.");
    }
    setLoading(false);
  };

  // Auto-trigger once when autoRun=true and results are present
  useEffect(() => {
    if (autoRun && !hasAutoRun.current && currentResults.some(r => r.result_value) && !loading && anomalies === null) {
      hasAutoRun.current = true;
      runDetection();
    }
  }, [autoRun, currentResults]);

  const validResults = currentResults.filter((r) => r.result_value);
  if (validResults.length === 0) return null;

  if (errorMsg) {
    return (
      <div className="flex items-center justify-between bg-red-50 border border-red-200 rounded-lg px-3 py-2.5">
        <div className="flex items-center gap-2 min-w-0">
          <AlertTriangle size={13} className="text-red-500 shrink-0" />
          <span className="text-xs text-red-700 truncate">{errorMsg}</span>
        </div>
        <Button size="sm" variant="outline" className="h-7 text-xs gap-1 ml-2 shrink-0" onClick={runDetection} disabled={loading}>
          {loading ? <Loader2 size={11} className="animate-spin" /> : <Sparkles size={11} />}
          Retry
        </Button>
      </div>
    );
  }

  if (anomalies === null) {
    return (
      <div className="flex items-center justify-between bg-primary/5 border border-primary/20 rounded-lg px-3 py-2.5">
        <div className="flex items-center gap-2">
          <Sparkles size={14} className="text-primary" />
          <span className="text-xs font-semibold text-foreground">AI Anomaly Detection</span>
          <span className="text-[10px] text-muted-foreground">Trend + pattern analysis</span>
        </div>
        <Button size="sm" className="h-7 text-xs gap-1" onClick={runDetection} disabled={loading}>
          {loading ? <Loader2 size={11} className="animate-spin" /> : <Sparkles size={11} />}
          {loading ? "Analysing..." : "Run Analysis"}
        </Button>
      </div>
    );
  }

  if (anomalies.length === 0) {
    return (
      <div className="flex items-center justify-between bg-emerald-50 dark:bg-emerald-950/20 border border-emerald-200 rounded-lg px-3 py-2 text-xs text-emerald-700 dark:text-emerald-400">
        <div className="flex items-center gap-2">
          <Sparkles size={12} /> AI analysis complete — no significant anomalies detected
        </div>
        <button onClick={() => setAnomalies(null)} className="text-[10px] opacity-60 hover:opacity-100">Re-run</button>
      </div>
    );
  }

  if (!__aiOn) return null;
  return (
    <div className="space-y-2">
      <div className="flex items-center gap-1.5 text-xs font-semibold text-foreground">
        <Sparkles size={12} className="text-primary" />
        AI Anomaly Analysis — {anomalies.length} finding{anomalies.length > 1 ? "s" : ""}
      </div>
      {anomalies.map((a, i) => (
        <div key={i} className={cn("rounded-lg border p-2.5 text-xs space-y-1", SEVERITY_STYLE[a.severity])}>
          <div className="flex items-start justify-between gap-2">
            <div className="flex items-start gap-1.5 font-bold">
              <AlertTriangle size={12} className="shrink-0 mt-0.5" />
              {a.test}: {a.finding}
            </div>
            <Badge variant="outline" className={cn("text-[9px] capitalize flex-shrink-0", SEVERITY_STYLE[a.severity])}>
              {a.severity}
            </Badge>
          </div>
          <p className="opacity-80 pl-4">{a.clinical_significance}</p>
          <p className="font-medium pl-4">Action: {a.action}</p>
        </div>
      ))}
      <button onClick={() => setAnomalies(null)} className="text-[10px] text-muted-foreground hover:text-foreground">
        Re-run analysis
      </button>
    </div>
  );
};

