];

// This platform page only manages GLOBAL AI + voice provider keys. Per-hospital
// integration keys (razorpay, wati, abdm, nic_irp, pmjay) stay in hospital Settings.
const AI_VOICE_SERVICE_KEYS = ["anthropic", "openai", "azure_openai", "gemini", "perplexity", "openrouter", "sarvam", "bhashini"];

// Azure Foundry model-surface picker options + auto-resolution (Claude → Anthropic surface).
const AZURE_SURFACES = [
  { value: "auto",           label: "Auto (detect from deployment)" },
  { value: "openai",         label: "OpenAI-compatible (GPT, Llama, DeepSeek, Mistral, Grok, Cohere)" },
  { value: "anthropic",      label: "Anthropic Messages (Claude)" },
  { value: "foundry_models", label: "Foundry Models (/models serverless)" },
];
const resolveAzureSurfaceUI = (surface: string | undefined, model: string): "openai" | "anthropic" | "foundry_models" => {
  if (surface === "openai" || surface === "anthropic" || surface === "foundry_models") return surface;
  return /^claude/i.test(model || "") ? "anthropic" : "openai";
};
// GPT-5 / o-series are reasoning models — on Azure Foundry they're served ONLY via the
// Responses API (chat completions 404s). Detect by deployment name to auto-pick the style.
const isAzureReasoningModel = (deployment: string): boolean => /^(o[0-9]|gpt-5)/i.test(deployment || "");

// supabase.functions.invoke() wraps a non-2xx response as FunctionsHttpError whose
// message is the opaque "…non-2xx status code" — the REAL error JSON lives in
// error.context (a Response). Unwrap it so we surface the actual provider/edge error.
// Only a genuine network failure (FunctionsFetchError) means "not reachable / not deployed".
async function unwrapInvokeError(error: unknown): Promise<string> {
  const err = error as { message?: string; context?: Response };
  const rawMsg = err?.message || "Edge function error";
  if (/failed to send|fetch failed|networkerror|failed to fetch/i.test(rawMsg)) {
    return "ai-proxy not reachable — is it deployed and are you signed in? (supabase functions deploy ai-proxy)";
  }
  const ctx = err?.context;
  if (ctx && typeof ctx.text === "function") {
    try {
      const raw = await ctx.text();
      if (raw) {
        try { const j = JSON.parse(raw); return j.error || j.message || raw; }
        catch { return raw; }
      }
    } catch { /* fall through */ }
  }
  return rawMsg;
}

interface AIConfig {
  id: string;
  feature_key: string;
  provider: string;
  model_name: string;
  api_key_ref: string | null;
  temperature: number;
  max_tokens: number;
  is_active: boolean;
}

interface APIKeyConfig {
  id: string;
  service_name: string;
  service_key: string;
  config: Record<string, string>;
  is_active: boolean;
  last_tested_at: string | null;
  test_status: string | null;
  test_message: string | null;
}

const PlatformAIConfigPage: React.FC = () => {
  const { toast } = useToast();
  const [aiConfigs, setAiConfigs] = useState<AIConfig[]>([]);
  const [apiKeys, setApiKeys] = useState<APIKeyConfig[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState<string | null>(null);
  const [bulkSaving, setBulkSaving] = useState(false);
  const [testing, setTesting] = useState<string | null>(null);
  const [voiceEngine, setVoiceEngine] = useState<string>("sarvam");
  const [preTranslateEnabled, setPreTranslateEnabled] = useState(false);
  const [preTranslateProvider, setPreTranslateProvider] = useState<string>("auto");
  const [usageLogs, setUsageLogs] = useState<{ feature_key: string; calls: number; tokens: number; errors: number; last_used: string }[]>([]);

  // API Key drawer
  const [editingKey, setEditingKey] = useState<typeof KNOWN_SERVICES[0] | null>(null);
  const [keyForm, setKeyForm] = useState({ api_key: "", endpoint: "", mode: "production", deployment: "", api_version: "", api_style: "chat_completions", azure_surface: "auto" });
  const [showSecret, setShowSecret] = useState(false);
  const [customModelInput, setCustomModelInput] = useState("");
  const [modelRefreshKey, setModelRefreshKey] = useState(0);
  const [azureModels, setAzureModels] = useState<string[]>([]);
  const [fetchingAzureModels, setFetchingAzureModels] = useState(false);
  const [azureModelsError, setAzureModelsError] = useState<string | null>(null);

  // Playground
  const [playFeature, setPlayFeature] = useState("voice_scribe");
  const [playPrompt, setPlayPrompt] = useState("Hello, summarize the following: Patient complains of headache for 2 days.");
  const [playResult, setPlayResult] = useState<{ text: string; provider: string; model: string; tokens?: number; ms?: number } | null>(null);
  const [playRunning, setPlayRunning] = useState(false);

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    if (pendingAutoRun.current && !playRunning) {
      pendingAutoRun.current = false;
      setTimeout(() => runPlayground(), 200);
    }
  }, [playFeature]);

  // Load the global voice engine preference + pre-translate setting
  useEffect(() => {
    supabase
      .from("platform_ai_keys")
      .select("config, service_key")
      .in("service_key", ["voice_asr_engine", "voice_pre_translate"])
      .then(({ data }) => {
        for (const row of data || []) {
          const cfg = row.config as Record<string, unknown>;
          if (row.service_key === "voice_asr_engine") {
            setVoiceEngine((cfg?.engine as string) || "sarvam");
          }
          if (row.service_key === "voice_pre_translate") {
            setPreTranslateEnabled(!!cfg?.enabled);
            setPreTranslateProvider((cfg?.provider as string) || "auto");
          }
        }
      });
  }, []);

  const saveVoiceEngine = async (engine: string) => {
    setVoiceEngine(engine);
    const existing = apiKeys.find(k => k.service_key === "voice_asr_engine");
    const payload = {
      service_name: "Voice ASR Engine",
      service_key: "voice_asr_engine",
      config: { engine },
      is_active: true,
    };
    if (existing) {
      await supabase.from("platform_ai_keys").update(payload).eq("id", existing.id);
    } else {
      await supabase.from("platform_ai_keys").insert(payload);
    }
    const engineLabel = engine === "sarvam" ? "Sarvam Saaras" : engine === "bhashini" ? "Bhashini (MeitY)" : "Web Speech API";
    toast({ title: `✓ Voice engine set to ${engineLabel}` });
    await loadData();
  };

  const loadData = async () => {
    setLoading(true);
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
    // Global AI config + keys; usage aggregated across ALL hospitals (admin RLS).
    const [aiRes, apiRes, logsRes] = await Promise.all([
      supabase.from("platform_ai_provider_config").select("*"),
      supabase.from("platform_ai_keys").select("*"),
      supabase.from("ai_usage_logs").select("feature_key, tokens_input, tokens_output, success, created_at").gte("created_at", sevenDaysAgo.toISOString()),
    ]);
    if (aiRes.data) setAiConfigs(aiRes.data as unknown as AIConfig[]);
    if (apiRes.data) setApiKeys(apiRes.data as unknown as APIKeyConfig[]);

    const agg = new Map<string, { calls: number; tokens: number; errors: number; last_used: string }>();
    for (const log of (logsRes.data || []) as Record<string, unknown>[]) {
      const fk = (log.feature_key as string) || "global_default";
      if (!agg.has(fk)) agg.set(fk, { calls: 0, tokens: 0, errors: 0, last_used: (log.created_at as string) || "" });
      const entry = agg.get(fk)!;
      entry.calls++;
      entry.tokens += ((log.tokens_input as number) || 0) + ((log.tokens_output as number) || 0);
      if (!log.success) entry.errors++;
      if (log.created_at && (log.created_at as string) > entry.last_used) entry.last_used = log.created_at as string;
    }
    setUsageLogs(Array.from(agg.entries()).map(([feature_key, v]) => ({ feature_key, ...v })).sort((a, b) => b.calls - a.calls));
    setLoading(false);
  };

  const globalConfig = useMemo(() => aiConfigs.find(c => c.feature_key === "global_default"), [aiConfigs]);
  const featureConfigs = useMemo(() => aiConfigs.filter(c => c.feature_key !== "global_default"), [aiConfigs]);

  const updateAIConfig = async (featureKey: string, updates: Partial<AIConfig>) => {
    setSaving(featureKey);
    const existing = aiConfigs.find(c => c.feature_key === featureKey);
    if (existing) {
      const { error } = await supabase
        .from("platform_ai_provider_config")
        .update(updates)
        .eq("id", existing.id);
      if (error) {
        toast({ title: "Failed to save AI config", description: error.message, variant: "destructive" });
      } else {
        toast({ title: `✓ ${FEATURE_LABELS[featureKey] || featureKey} config saved` });
        setAiConfigs(prev => prev.map(c => c.id === existing.id ? { ...c, ...updates } as AIConfig : c));
      }
    } else {
      const insertPayload = {
          feature_key: featureKey,
          provider: (updates as AIConfig).provider || "claude",
          model_name: (updates as AIConfig).model_name || "claude-sonnet-4-6",
          ...updates,
        };
      const { data, error } = await supabase
        .from("platform_ai_provider_config")
        .insert(insertPayload)
        .select()
        .maybeSingle();
      if (error) {
        toast({ title: "Failed to create AI config", description: error.message, variant: "destructive" });
      } else if (data) {
        setAiConfigs(prev => [...prev, data as unknown as AIConfig]);
        toast({ title: `✓ ${FEATURE_LABELS[featureKey] || featureKey} config created` });
      }
    }
    setSaving(null);
  };

  /** Feature keys shown in the override table (everything except the global default row). */
  const overridableFeatureKeys = useMemo(
    () => Object.keys(FEATURE_LABELS).filter(k => k !== "global_default"),
    []
  );

  /**
   * Flip a feature between "Default" (inherit global_default) and "Custom".
   * `is_active` is what the edge-function resolver keys off, so that is the switch —
   * turning it off makes the resolver fall through to global_default.
   */
  const setOverride = async (featureKey: string, custom: boolean) => {
    if (!custom) {
      await updateAIConfig(featureKey, { is_active: false } as Partial<AIConfig>);
      return;
    }
    const existing = aiConfigs.find(c => c.feature_key === featureKey);
    await updateAIConfig(featureKey, {
      is_active: true,
      provider: existing?.provider || globalConfig?.provider || "claude",
      model_name: existing?.model_name || globalConfig?.model_name || "",
      api_key_ref:
        existing?.api_key_ref ||
        PROVIDER_TO_SERVICE_KEY[existing?.provider || globalConfig?.provider || "claude"] ||
        null,
    } as Partial<AIConfig>);
  };

  /** Bulk "all Default" / "all Custom" for every feature in the table. */
  const bulkSetOverride = async (custom: boolean) => {
    setBulkSaving(true);
    try {
      if (!custom) {
        const ids = featureConfigs.filter(c => c.is_active).map(c => c.id);
        if (ids.length) {
          const { error } = await supabase
            .from("platform_ai_provider_config")
            .update({ is_active: false })
            .in("id", ids);
          if (error) {
            toast({ title: "Bulk update failed", description: error.message, variant: "destructive" });
            return;
          }
          setAiConfigs(prev => prev.map(c => (ids.includes(c.id) ? { ...c, is_active: false } : c)));
        }
        toast({ title: `✓ All ${overridableFeatureKeys.length} features set to Default` });
        return;
      }

      const provider = globalConfig?.provider || "claude";
      const modelName = globalConfig?.model_name || "";
      const apiKeyRef = PROVIDER_TO_SERVICE_KEY[provider] || null;

      const existingIds = featureConfigs.filter(c => !c.is_active).map(c => c.id);
      if (existingIds.length) {
        const { error } = await supabase
          .from("platform_ai_provider_config")
          .update({ is_active: true })
          .in("id", existingIds);
        if (error) {
          toast({ title: "Bulk update failed", description: error.message, variant: "destructive" });
          return;
        }
        setAiConfigs(prev => prev.map(c => (existingIds.includes(c.id) ? { ...c, is_active: true } : c)));
      }

      // Features that have never been configured need a row created first.
      const missing = overridableFeatureKeys.filter(k => !aiConfigs.some(c => c.feature_key === k));
      if (missing.length) {
        const { data, error } = await supabase
          .from("platform_ai_provider_config")
          .insert(
            missing.map(feature_key => ({
              feature_key,
              provider,
              model_name: modelName,
              api_key_ref: apiKeyRef,
              is_active: true,
            }))
          )
          .select();
        if (error) {
          toast({ title: "Bulk create failed", description: error.message, variant: "destructive" });
          return;
        }
        if (data) setAiConfigs(prev => [...prev, ...(data as unknown as AIConfig[])]);
      }
      toast({ title: `✓ All ${overridableFeatureKeys.length} features set to Custom` });
    } finally {
      setBulkSaving(false);
    }
  };

  const getApiKeyForService = (serviceKey: string) => apiKeys.find(k => k.service_key === serviceKey);

  const saveApiKey = async () => {
    if (!editingKey) return;
    setSaving(editingKey.service_key);
    const existing = getApiKeyForService(editingKey.service_key);
    const config: Record<string, string> = {
      api_key: keyForm.api_key,
      endpoint: keyForm.endpoint || editingKey.endpoint,
      mode: keyForm.mode,
    };
    if (editingKey.service_key === "azure_openai") {
      // Store the resource ROOT — a pasted Foundry project endpoint
      // (…/api/projects/<name>) would break every inference URL.
      config.endpoint = normalizeAzureEndpoint(keyForm.endpoint || editingKey.endpoint);
      config.deployment = keyForm.deployment;
      config.api_version = keyForm.api_version; // optional — blank uses the newer /openai/v1 surface
      config.api_style = keyForm.api_style; // "chat_completions" (default, works for any model) or "responses"
      config.azure_surface = keyForm.azure_surface; // "auto"|"openai"|"anthropic"|"foundry_models"
    }
    const payload = {
      service_name: editingKey.service_name,
      service_key: editingKey.service_key,
      config,
      is_active: true,
    };

    if (existing) {
      const { error } = await supabase.from("platform_ai_keys").update(payload).eq("id", existing.id);
      if (error) {
        toast({ title: "Failed to save", description: error.message, variant: "destructive" });
      } else {
        toast({ title: `✓ ${editingKey.service_name} key saved` });
      }
    } else {
      const { error } = await supabase.from("platform_ai_keys").insert(payload);
      if (error) {
        toast({ title: "Failed to save", description: error.message, variant: "destructive" });
      } else {
        toast({ title: `✓ ${editingKey.service_name} key added` });
      }
    }
    await loadData();
    setEditingKey(null);
    setSaving(null);
  };

  const playgroundRef = React.useRef<HTMLDivElement>(null);
  const pendingAutoRun = React.useRef(false);

  const testApiKey = async (serviceKey: string, overrideConfig?: Record<string, string>) => {
    setTesting(serviceKey);
    const existing = getApiKeyForService(serviceKey);
    // Prefer the live (possibly unsaved) drawer form values over the stale DB-saved config.
    const cfg = overrideConfig || (existing?.config as Record<string, string> | undefined);
    if (!cfg) { setTesting(null); return; }
    const apiKey = cfg.api_key;
    if (!apiKey) { setTesting(null); return; }

    let success = false;
    let message = "";
    const start = Date.now();

    try {
      if (serviceKey === "gemini") {
        // Use v1 (stable) endpoint with gemini-2.0-flash for connection testing.
        // gemini-1.5-flash was moved out of v1beta; preview models still use v1beta.
        const res = await fetch(`https://generativelanguage.googleapis.com/v1/models/gemini-2.0-flash:generateContent?key=${apiKey}`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ contents: [{ parts: [{ text: "Hi" }] }], generationConfig: { maxOutputTokens: 1 } }),
        });
        success = res.ok;
        if (!success) { const d = await res.json(); message = d.error?.message || `HTTP ${res.status}`; }
      } else if (serviceKey === "openai") {
        const res = await fetch("https://api.openai.com/v1/models", {
          headers: { Authorization: `Bearer ${apiKey}` },
        });
        success = res.ok;
        if (!success) { const d = await res.json(); message = d.error?.message || `HTTP ${res.status}`; }
      } else if (serviceKey === "anthropic") {
        const res = await fetch("https://api.anthropic.com/v1/messages", {
          method: "POST",
          headers: { "Content-Type": "application/json", "x-api-key": apiKey, "anthropic-version": "2023-06-01", "anthropic-dangerous-direct-browser-access": "true" },
          body: JSON.stringify({ model: "claude-3-5-haiku-20241022", max_tokens: 1, messages: [{ role: "user", content: "Hi" }] }),
        });
        success = res.ok;
        if (!success) { const d = await res.json(); message = d.error?.message || `HTTP ${res.status}`; }
      } else if (serviceKey === "azure_openai") {
        // Azure Foundry blocks direct browser calls (no CORS), so route the test through the
        // ai-proxy edge function. Different Foundry model families live on DIFFERENT surfaces —
        // GPT → chat completions, GPT-5/o-series → responses, Claude → anthropic, and serverless
        // partner models (grok/llama/deepseek/mistral) → /models. Rather than guess per model,
        // PROBE the plausible surfaces in order and lock onto whichever Azure accepts, then
        // persist it to the drawer so Save keeps the working surface for real feature calls.
        const endpoint = normalizeAzureEndpoint(cfg.endpoint);
        const deployment = cfg.deployment;
        if (!endpoint || !deployment) {
          success = false;
          message = !endpoint ? "Endpoint URL is required" : "Deployment Name is required";
        } else {
          const hasVersion = !!(cfg.api_version && cfg.api_version.trim());
          type Cand = { surface: string; apiStyle: string };
          let candidates: Cand[];
          if (/^claude/i.test(deployment)) {
            candidates = [{ surface: "anthropic", apiStyle: "" }];
          } else if (hasVersion) {
            // Explicit classic GA deployment → only the versioned chat path is valid.
            candidates = [{ surface: "openai", apiStyle: "chat_completions" }];
          } else {
            const reasoning = isAzureReasoningModel(deployment);
            candidates = [
              { surface: "openai", apiStyle: reasoning ? "responses" : "chat_completions" },
              { surface: "openai", apiStyle: reasoning ? "chat_completions" : "responses" },
              { surface: "foundry_models", apiStyle: "" },
            ];
          }
          let lastMsg = "";
          let winner: Cand | null = null;
          for (const c of candidates) {
            const { data, error } = await supabase.functions.invoke("ai-proxy", {
              body: {
                provider: "azure_openai",
                prompt: "Reply with exactly: OK",
                maxTokens: 256, // GPT-5 / reasoning enforce >=16 and spend tokens on reasoning
                probe: true,
                azureConfig: { endpoint, apiKey, deployment, apiVersion: cfg.api_version || "", apiStyle: c.apiStyle, surface: c.surface },
              },
            });
            if (!error && !data?.error) { winner = c; break; }
            lastMsg = error ? await unwrapInvokeError(error) : (typeof data.error === "string" ? data.error : JSON.stringify(data.error));
            // 404 = "wrong surface for this deployment" → keep probing. Any other error
            // (auth / quota / bad key / not-deployed) is terminal — stop and report it.
            if (!/resource not found|not found|404/i.test(lastMsg)) break;
          }
          if (winner) {
            success = true;
            // Persist the surface/style that worked so Save + real feature calls use it.
            setKeyForm(p => ({ ...p, azure_surface: winner!.surface, api_style: winner!.apiStyle || p.api_style }));
          } else {
            success = false;
            message = /resource not found|not found|404/i.test(lastMsg)
              ? `${lastMsg} — tried chat, responses${/^claude/i.test(deployment) ? "" : " and /models"} surfaces; none matched this deployment. Verify the deployment name exists and is running in Foundry (Models + endpoints), and that the latest ai-proxy is deployed (supabase functions deploy ai-proxy).`
              : lastMsg;
          }
        }
      } else if (serviceKey === "perplexity") {
        const res = await fetch("https://api.perplexity.ai/chat/completions", {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
          body: JSON.stringify({ model: "llama-3.1-sonar-small-128k-online", max_tokens: 1, messages: [{ role: "user", content: "Hi" }] }),
        });
        success = res.ok;
        if (!success) { const d = await res.json(); message = d.error?.message || `HTTP ${res.status}`; }
      } else if (serviceKey === "openrouter") {
        // OpenRouter is OpenAI-compatible; listing models is a cheap auth check.
        const res = await fetch("https://openrouter.ai/api/v1/models", {
          headers: { Authorization: `Bearer ${apiKey}` },
        });
        success = res.ok;
        if (!success) { const d = await res.json().catch(() => ({})); message = d.error?.message || `HTTP ${res.status}`; }
      } else {
        // Non-AI services: just mark configured
        success = !!apiKey;
        message = success ? "Key is set" : "No key";
      }
    } catch (err) {
      success = false;
      message = err instanceof Error ? err.message : "Connection failed";
    }

    const ms = Date.now() - start;
    const now = new Date().toISOString();
    if (existing) {
      await supabase.from("platform_ai_keys").update({
        last_tested_at: now,
        test_status: success ? "success" : "failed",
        test_message: success ? `Connected — response in ${ms}ms` : message,
      }).eq("id", existing.id);
      await loadData();
    }

    setTesting(null);
    toast({
      title: success ? "✓ Connection successful" : "✗ Connection failed",
      description: success ? `Verified in ${ms}ms` : message,
      variant: success ? "default" : "destructive",
    });
  };

  const fetchAzureModels = async () => {
    const endpoint = normalizeAzureEndpoint(keyForm.endpoint);
    const apiKey = keyForm.api_key;
    if (!endpoint || !apiKey) {
      toast({ title: "Enter API Key and Endpoint first", variant: "destructive" });
      return;
    }
    setFetchingAzureModels(true);
    setAzureModelsError(null);
    try {
      // Azure blocks direct browser calls (no CORS), so list deployments server-side via ai-proxy.
      const { data, error } = await supabase.functions.invoke("ai-proxy", {
        body: { azureAction: "list-deployments", azureConfig: { endpoint, apiKey } },
      });
      if (error) {
        setAzureModels([]);
        setAzureModelsError(await unwrapInvokeError(error));
        return;
      }
      if (data?.error) {
        setAzureModels([]);
        setAzureModelsError(typeof data.error === "string" ? data.error : JSON.stringify(data.error));
        return;
      }
      const ids: string[] = Array.isArray(data?.deployments) ? data.deployments : [];
      setAzureModels(ids);
      if (ids.length === 0) {
        setAzureModelsError("No deployments found at this endpoint — deploy a model in Azure Foundry first, or type the name manually.");
      }
    } catch (e) {
      setAzureModels([]);
      setAzureModelsError(e instanceof Error ? e.message : "Couldn't list deployments — type the name manually.");
    } finally {
      setFetchingAzureModels(false);
    }
  };

  const runPlayground = async () => {
    setPlayRunning(true);
    setPlayResult(null);
    const start = Date.now();

    try {
      // Resolve global AI config: feature-specific first, then global_default
      let config: any = null;
      const { data: fc } = await supabase
        .from("platform_ai_provider_config").select("*")
        .eq("feature_key", playFeature).eq("is_active", true).maybeSingle();
      config = fc;
      if (!config) {
        const { data: dc } = await supabase
          .from("platform_ai_provider_config").select("*")
          .eq("feature_key", "global_default").eq("is_active", true).maybeSingle();
        config = dc;
      }

      if (!config) {
        setPlayResult({ text: "No AI provider configured. Set a Global Default above.", provider: "none", model: "none", ms: Date.now() - start });
        return;
      }

      const { provider, model_name, temperature, max_tokens } = config;
      const serviceKey = PROVIDER_TO_SERVICE_KEY[provider] || provider;

      // Fetch API key from the global platform_ai_keys (admin-only — OK here for the admin playground)
      const { data: apiCfg } = await supabase
        .from("platform_ai_keys").select("config")
        .eq("service_key", serviceKey).eq("is_active", true).maybeSingle();
      const apiKey = (apiCfg?.config as Record<string, string>)?.api_key;

      if (!apiKey) {
        setPlayResult({ text: `No API key for ${provider}. Add it in External API Keys below.`, provider, model: model_name, ms: Date.now() - start });
        return;
      }

      const maxTok = Number(max_tokens) || 600;
      const temp = Number(temperature) || 0.3;
      let text = "";
      let tokens_used: number | undefined;

      if (provider === "gemini") {
        // v1beta + thinkingBudget:0 keeps Gemini 2.5/3 fast (no hidden "thinking" / MAX_TOKENS truncation).
        const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model_name}:generateContent?key=${apiKey}`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ contents: [{ parts: [{ text: playPrompt }] }], generationConfig: { maxOutputTokens: maxTok, temperature: temp, thinkingConfig: { thinkingBudget: 0 } } }),
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));
        text = data.candidates?.[0]?.content?.parts?.[0]?.text || "";
        tokens_used = data.usageMetadata?.totalTokenCount;

      } else if (provider === "openai") {
        const res = await fetch("https://api.openai.com/v1/chat/completions", {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
          body: JSON.stringify({ model: model_name, max_tokens: maxTok, temperature: temp, messages: [{ role: "user", content: playPrompt }] }),
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));
        text = data.choices?.[0]?.message?.content || "";
        tokens_used = data.usage?.total_tokens;

      } else if (provider === "claude") {
        const res = await fetch("https://api.anthropic.com/v1/messages", {
          method: "POST",
          headers: { "Content-Type": "application/json", "x-api-key": apiKey, "anthropic-version": "2023-06-01", "anthropic-dangerous-direct-browser-access": "true" },
          body: JSON.stringify({ model: model_name, max_tokens: maxTok, temperature: temp, messages: [{ role: "user", content: playPrompt }] }),
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));
        text = data.content?.[0]?.text || "";
        tokens_used = (data.usage?.input_tokens || 0) + (data.usage?.output_tokens || 0);

      } else if (provider === "perplexity") {
        const res = await fetch("https://api.perplexity.ai/chat/completions", {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
          body: JSON.stringify({ model: model_name, max_tokens: maxTok, messages: [{ role: "user", content: playPrompt }] }),
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));
        text = data.choices?.[0]?.message?.content || "";

      } else if (provider === "openrouter") {
        const res = await fetch("https://openrouter.ai/api/v1/chat/completions", {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}`, "X-Title": "Aumrti HMS" },
          body: JSON.stringify({ model: model_name, max_tokens: maxTok, temperature: temp, messages: [{ role: "user", content: playPrompt }] }),
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));
        text = data.choices?.[0]?.message?.content || "";
        tokens_used = data.usage?.total_tokens;

      } else if (provider === "azure_openai") {
        // Azure Foundry blocks direct browser calls (no CORS) — route through the ai-proxy
        // edge function (server-side), reading the SAVED Azure config. Requires ai-proxy deployed.
        const azureCfg = (await supabase
          .from("platform_ai_keys").select("config")
          .eq("service_key", "azure_openai").eq("is_active", true).maybeSingle()).data;
        const ac = azureCfg?.config as Record<string, string> | undefined;
        if (!ac?.endpoint || !ac?.deployment) {
          text = "Azure OpenAI: set Endpoint URL and Deployment Name in API Hub first, then Save.";
        } else {
          const { data, error } = await supabase.functions.invoke("ai-proxy", {
            body: { provider: "azure_openai", prompt: playPrompt, maxTokens: maxTok, temperature: temp, probe: true },
          });
          if (error) throw new Error(await unwrapInvokeError(error));
          if (data?.error) throw new Error(typeof data.error === "string" ? data.error : JSON.stringify(data.error));
          text = data?.text || "";
          tokens_used = data?.tokens_used;
        }
      } else {
        text = `Direct browser calls not supported for provider: ${provider}. Deploy the ai-proxy edge function.`;
      }

      setPlayResult({ text, provider, model: model_name, tokens: tokens_used, ms: Date.now() - start });
    } catch (err: any) {
      setPlayResult({ text: err?.message || "Unknown error", provider: "unknown", model: "unknown", ms: Date.now() - start });
    } finally {
      setPlayRunning(false);
    }

  };

  const getStatusBadge = (svc: typeof KNOWN_SERVICES[0]) => {
    const existing = getApiKeyForService(svc.service_key);
    if (!existing) return <Badge variant="outline" className="text-muted-foreground gap-1"><span className="w-2 h-2 rounded-full bg-muted-foreground/40 inline-block" /> Not set</Badge>;
    const mode = (existing.config as Record<string, string>)?.mode;
    if (existing.test_status === "success") {
      return <Badge className="bg-emerald-100 text-emerald-700 gap-1"><span className="w-2 h-2 rounded-full bg-emerald-500 inline-block" /> Live</Badge>;
    }
    if (mode === "sandbox" || mode === "test") {
      return <Badge className="bg-amber-100 text-amber-700 gap-1"><span className="w-2 h-2 rounded-full bg-amber-500 inline-block" /> Test</Badge>;
    }
    return <Badge className="bg-blue-100 text-blue-700 gap-1"><span className="w-2 h-2 rounded-full bg-blue-500 inline-block" /> Configured</Badge>;
  };

  const maskKey = (key?: string) => {
    if (!key) return "—";
    if (key.length <= 8) return "••••••••";
    return key.substring(0, Math.min(12, key.length - 8)) + "••••••••";
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="animate-spin text-muted-foreground" size={24} />
      </div>
    );
  }

  return (
    <div className="p-6 overflow-y-auto">
      <div className="mb-6">
        <h1 className="text-xl font-bold text-foreground">AI Configuration</h1>
        <p className="text-sm text-muted-foreground">Global AI provider, model and key settings applied to every hospital</p>
      </div>
      <div className="max-w-[960px] space-y-8">

        {/* ── SECTION 0: AI USAGE STATS ── */}
        <section>
          <h2 className="text-lg font-bold text-foreground mb-1">AI Usage — Last 7 Days</h2>
          <p className="text-sm text-muted-foreground mb-4">Live usage across all AI features, all hospitals</p>
          {usageLogs.length === 0 ? (
            <p className="text-sm text-muted-foreground py-4">No AI calls recorded in the last 7 days</p>
          ) : (
            <div className="rounded-lg border overflow-hidden">
              <table className="w-full text-sm">
                <thead className="bg-muted/50">
                  <tr>
                    <th className="px-4 py-2.5 text-left font-medium text-xs text-muted-foreground">Feature</th>
                    <th className="px-4 py-2.5 text-center font-medium text-xs text-muted-foreground">Calls</th>
                    <th className="px-4 py-2.5 text-center font-medium text-xs text-muted-foreground">Tokens</th>
                    <th className="px-4 py-2.5 text-center font-medium text-xs text-muted-foreground">Errors</th>
                    <th className="px-4 py-2.5 text-left font-medium text-xs text-muted-foreground">Last Used</th>
                  </tr>
                </thead>
                <tbody>
                  {usageLogs.map(row => (
                    <tr key={row.feature_key} className="border-t border-border">
                      <td className="px-4 py-2.5 font-medium">{FEATURE_LABELS[row.feature_key] || row.feature_key}</td>
                      <td className="px-4 py-2.5 text-center">{row.calls}</td>
                      <td className="px-4 py-2.5 text-center">{row.tokens.toLocaleString("en-IN")}</td>
                      <td className="px-4 py-2.5 text-center">
                        {row.errors > 0
                          ? <Badge variant="destructive" className="text-xs">{row.errors}</Badge>
                          : <span className="text-muted-foreground">—</span>}
                      </td>
                      <td className="px-4 py-2.5 text-muted-foreground text-xs">
                        {row.last_used ? new Date(row.last_used).toLocaleString("en-IN", { dateStyle: "medium", timeStyle: "short" }) : "—"}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>

        <Separator />

        {/* ── SECTION 1: AI PROVIDERS ── */}
        <section>
          <h2 className="text-lg font-bold text-foreground mb-1">AI Provider Configuration</h2>
          <p className="text-sm text-muted-foreground mb-5">Choose which AI model powers each HMS feature</p>

          {/* Global Default */}
          <div className="bg-primary/5 border-2 border-primary rounded-xl p-5 mb-5">
            <div className="flex items-center gap-2 mb-3">
              <span className="text-lg">🌐</span>
              <span className="font-bold text-sm text-foreground">Global Default</span>
              <span className="text-xs text-muted-foreground">— Used for all features unless overridden below</span>
            </div>
            <div className="grid grid-cols-5 gap-3 items-end">
              <div>
                <Label className="text-xs">Provider</Label>
                <Select
                  value={globalConfig?.provider || "claude"}
                  onValueChange={v => {
                    const models = getMergedModels(v);
                    const serviceKey = PROVIDER_TO_SERVICE_KEY[v] || null;
                    updateAIConfig("global_default", { provider: v, model_name: models?.[0]?.value || "", api_key_ref: serviceKey });
                  }}
                >
                  <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {PROVIDERS.map(p => <SelectItem key={p.value} value={p.value}>{p.label}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label className="text-xs">Model{globalConfig?.provider === "azure_openai" ? " / Deployment" : ""}</Label>
                {globalConfig?.provider === "azure_openai" ? (
                  <div>
                    <Input
                      className="mt-1 text-xs"
                      value={globalConfig?.model_name || ""}
                      onChange={e => updateAIConfig("global_default", { model_name: e.target.value })}
                      placeholder="Deployment name (e.g. gpt-4o)"
                    />
                    <p className="text-[10px] text-muted-foreground mt-0.5">Must match deployment name in Azure AI Foundry</p>
                  </div>
                ) : (
                  <Select
                    value={globalConfig?.model_name || ""}
                    onValueChange={v => updateAIConfig("global_default", { model_name: v })}
                  >
                    <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {getMergedModels(globalConfig?.provider || "claude").map(m => (
                        <SelectItem key={m.value} value={m.value}>{m.label}{m.isCustom ? " ★" : ""}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                )}
              </div>
              <div>
                <Label className="text-xs">API Key Source</Label>
                <Select
                  value={globalConfig?.api_key_ref || "env"}
                  onValueChange={v => updateAIConfig("global_default", { api_key_ref: v === "env" ? null : v })}
                >
                  <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="env">Environment Variable</SelectItem>
                    {KNOWN_SERVICES.filter(s => ["anthropic", "openai", "azure_openai", "gemini", "perplexity", "openrouter"].includes(s.service_key)).map(s => (
                      <SelectItem key={s.service_key} value={s.service_key}>{s.emoji} {s.service_name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label className="text-xs">Temperature</Label>
                <Input
                  type="number"
                  step="0.1"
                  min="0"
                  max="2"
                  className="mt-1"
                  value={globalConfig?.temperature ?? 0.3}
                  onChange={e => updateAIConfig("global_default", { temperature: parseFloat(e.target.value) || 0.3 })}
                />
              </div>
              <Button
                size="sm"
                variant="outline"
                className="gap-1"
                disabled={saving === "global_default"}
                onClick={() => updateAIConfig("global_default", {})}
              >
                {saving === "global_default" ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />}
                Save
              </Button>
            </div>
          </div>

          {/* Feature overrides table */}
          <div className="border border-border rounded-lg overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-muted/50 text-left">
                  <th className="px-4 py-2.5 font-medium text-muted-foreground">Feature</th>
                  <th className="px-4 py-2.5 font-medium text-muted-foreground">Provider</th>
                  <th className="px-4 py-2.5 font-medium text-muted-foreground">Model</th>
                  <th className="px-4 py-2.5 font-medium text-muted-foreground">
                    <div className="flex items-center gap-2">
                      <span>Override</span>
                      <div className="flex items-center gap-1">
                        <Button
                          variant="outline"
                          size="sm"
                          className="h-6 px-2 text-[11px] font-normal"
                          disabled={bulkSaving}
                          onClick={() => bulkSetOverride(false)}
                          title="Set every feature back to the Global Default"
                        >
                          {bulkSaving ? <Loader2 size={11} className="animate-spin" /> : "All Default"}
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          className="h-6 px-2 text-[11px] font-normal"
                          disabled={bulkSaving}
                          onClick={() => bulkSetOverride(true)}
                          title="Give every feature its own custom provider/model"
                        >
                          {bulkSaving ? <Loader2 size={11} className="animate-spin" /> : "All Custom"}
                        </Button>
                      </div>
                    </div>
                  </th>
                  <th className="px-4 py-2.5 font-medium text-muted-foreground">Actions</th>
                </tr>
              </thead>
              <tbody>
                {Object.entries(FEATURE_LABELS).filter(([k]) => k !== "global_default").map(([key, label]) => {
                  const config = featureConfigs.find(c => c.feature_key === key);
                  const isOverride = !!config?.is_active;
                  // An inactive row resolves to global_default at call time — show that, not its stale saved values.
                  const effProvider = (isOverride ? config?.provider : globalConfig?.provider) || "claude";
                  const effModel = (isOverride ? config?.model_name : globalConfig?.model_name) || "";
                  return (
                    <tr key={key} className="border-t border-border">
                      <td className="px-4 py-2.5 font-medium text-foreground">{label}</td>
                      <td className="px-4 py-2.5">
                        <Select
                          value={effProvider}
                          onValueChange={v => {
                            const models = getMergedModels(v);
                            const serviceKey = PROVIDER_TO_SERVICE_KEY[v] || null;
                            updateAIConfig(key, { provider: v, model_name: models?.[0]?.value || "", is_active: true, api_key_ref: serviceKey });
                          }}
                        >
                          <SelectTrigger className="h-8 text-xs w-[160px]"><SelectValue /></SelectTrigger>
                          <SelectContent>
                            {PROVIDERS.map(p => <SelectItem key={p.value} value={p.value}>{p.label}</SelectItem>)}
                          </SelectContent>
                        </Select>
                      </td>
                      <td className="px-4 py-2.5">
                        {effProvider === "azure_openai" ? (
                          <Input
                            className="h-8 text-xs w-[200px]"
                            value={effModel}
                            onChange={e => updateAIConfig(key, { model_name: e.target.value, is_active: true })}
                            placeholder="Deployment name"
                          />
                        ) : (
                          <Select
                            value={effModel}
                            onValueChange={v => updateAIConfig(key, { model_name: v, is_active: true })}
                          >
                            <SelectTrigger className="h-8 text-xs w-[200px]"><SelectValue /></SelectTrigger>
                            <SelectContent>
                              {getMergedModels(effProvider).map(m => (
                                <SelectItem key={m.value} value={m.value}>{m.label}{m.isCustom ? " ★" : ""}</SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        )}
                      </td>
                      <td className="px-4 py-2.5">
                        <div className="flex items-center gap-2">
                          <Switch
                            checked={isOverride}
                            disabled={bulkSaving || saving === key}
                            onCheckedChange={checked => setOverride(key, checked)}
                          />
                          <span className="text-xs text-muted-foreground">{isOverride ? "Custom" : "Default"}</span>
                        </div>
                      </td>
                      <td className="px-4 py-2.5">
                        <Button
                          variant="ghost"
                          size="sm"
                          className="gap-1 text-xs"
                          disabled={testing === key}
                          onClick={() => {
                            setPlayFeature(key);
                            setPlayPrompt("Hello, this is a test message. Respond with: Test successful.");
                            pendingAutoRun.current = true;
                            setTimeout(() => {
                              playgroundRef.current?.scrollIntoView({ behavior: "smooth", block: "center" });
                            }, 100);
                          }}
                        >
                          <FlaskConical size={12} /> Test
                        </Button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </section>

        <Separator />

        {/* ── SECTION 1.5: VOICE ASR ENGINE ── */}
        <section>
          <h2 className="text-lg font-bold text-foreground mb-1">Voice ASR Engine</h2>
          <p className="text-sm text-muted-foreground mb-5">
            Choose which speech-to-text engine powers Voice Scribe for Indian languages
          </p>

          <div className="grid grid-cols-3 gap-4">
            {[
              {
                key: "sarvam",
                name: "Sarvam Saaras",
                emoji: "🎙️",
                desc: "Best medical vocabulary accuracy. 8 Indian languages. Paid API.",
                languages: "Hindi, Telugu, Tamil, Kannada, Malayalam, Marathi, Bengali, Gujarati",
                requiresKey: true,
                badge: "Recommended",
                badgeColor: "bg-blue-100 text-blue-700",
              },
              {
                key: "bhashini",
                name: "Bhashini (MeitY)",
                emoji: "🇮🇳",
                desc: "Government of India free ASR. 22 scheduled languages. ULCA pipeline.",
                languages: "All 22 scheduled languages including Odia, Punjabi, Assamese, Urdu, Sanskrit",
                requiresKey: true,
                badge: "Free",
                badgeColor: "bg-emerald-100 text-emerald-700",
              },
              {
                key: "web_speech",
                name: "Web Speech API",
                emoji: "🌐",
                desc: "Browser built-in. English only. No API key needed. Works offline.",
                languages: "English (en-IN)",
                requiresKey: false,
                badge: "Built-in",
                badgeColor: "bg-muted text-muted-foreground",
              },
            ].map((engine) => {
              const isSelected = (voiceEngine || "sarvam") === engine.key;
              const hasKey = engine.key === "web_speech" || !!getApiKeyForService(engine.key);
              return (
                <div
                  key={engine.key}
                  role="button"
                  tabIndex={0}
                  onClick={() => {
                    if (engine.requiresKey && !hasKey) {
                      toast({ title: `Configure ${engine.name} API key first`, description: "Add the key in External API Keys below", variant: "destructive" });
                      return;
                    }
                    saveVoiceEngine(engine.key);
                  }}
                  onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") e.currentTarget.click(); }}
                  className={cn(
                    "relative border-2 rounded-xl p-5 cursor-pointer transition-all hover:shadow-md",
                    isSelected ? "border-primary bg-primary/5" : "border-border hover:border-primary/40"
                  )}
                >
                  {isSelected && (
                    <div className="absolute top-3 right-3">
                      <div className="bg-primary text-primary-foreground rounded-full p-0.5">
                        <Check size={12} />
                      </div>
                    </div>
                  )}
                  <div className="flex items-center gap-2 mb-2">
                    <span className="text-lg">{engine.emoji}</span>
                    <span className="font-bold text-sm text-foreground">{engine.name}</span>
                    <Badge className={cn("text-[10px]", engine.badgeColor)}>{engine.badge}</Badge>
                  </div>
                  <p className="text-xs text-muted-foreground mb-2">{engine.desc}</p>
                  <p className="text-[10px] text-muted-foreground">
                    <span className="font-medium">Languages:</span> {engine.languages}
                  </p>
                  {engine.requiresKey && !hasKey && (
                    <p className="text-[10px] text-amber-600 mt-2">⚠ API key required — configure below</p>
                  )}
                </div>
              );
            })}
          </div>

          {/* Pre-translate toggle — saves 60-80% LLM tokens for Indian language dictations */}
          <div className="mt-6 border border-border rounded-xl p-5 bg-muted/30">
            <div className="flex items-start justify-between gap-4">
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-base">🌐→🇬🇧</span>
                  <h3 className="font-bold text-sm text-foreground">Pre-translate to English before AI structuring</h3>
                  <Badge className="text-[10px] bg-amber-100 text-amber-700">Token Saver</Badge>
                </div>
                <p className="text-xs text-muted-foreground mb-2">
                  Translates Indian language transcripts to English using Sarvam/Bhashini <strong>before</strong> sending
                  to the LLM. Reduces LLM token usage by 60–80% for non-English dictations.
                </p>
                <p className="text-[10px] text-amber-600">
                  ⚠ Medical terminology accuracy may vary — validate with your clinical team before enabling in production.
                </p>
              </div>
              <Switch
                checked={preTranslateEnabled}
                onCheckedChange={async (checked) => {
                  setPreTranslateEnabled(checked);
                  const existing = apiKeys.find(k => k.service_key === "voice_pre_translate");
                  const payload = {
                    service_name: "Voice Pre-Translate",
                    service_key: "voice_pre_translate",
                    config: { enabled: checked, provider: preTranslateProvider },
                    is_active: true,
                  };
                  if (existing) {
                    await supabase.from("platform_ai_keys").update(payload).eq("id", existing.id);
                  } else {
                    await supabase.from("platform_ai_keys").insert(payload);
                  }
                  toast({ title: checked ? "✓ Pre-translation enabled — LLM token savings active" : "✓ Pre-translation disabled — LLM handles translation directly" });
                  await loadData();
                }}
              />
            </div>

            {preTranslateEnabled && (
              <div className="mt-3 pt-3 border-t border-border/50">
                <Label className="text-xs text-muted-foreground mb-1.5 block">Translation Engine</Label>
                <div className="flex gap-2">
                  {[
                    { key: "auto", label: "Auto (match ASR engine)" },
                    { key: "sarvam", label: "Sarvam (mayura:v1)" },
                    { key: "bhashini", label: "Bhashini (MeitY NMT)" },
                  ].map((opt) => (
                    <button
                      key={opt.key}
                      onClick={async () => {
                        setPreTranslateProvider(opt.key);
                        const existing = apiKeys.find(k => k.service_key === "voice_pre_translate");
                        const payload = {
                          service_name: "Voice Pre-Translate",
                          service_key: "voice_pre_translate",
                          config: { enabled: true, provider: opt.key },
                          is_active: true,
                        };
                        if (existing) {
                          await supabase.from("platform_ai_keys").update(payload).eq("id", existing.id);
                        } else {
                          await supabase.from("platform_ai_keys").insert(payload);
                        }
                        toast({ title: `✓ Translation engine set to ${opt.label}` });
                        await loadData();
                      }}
                      className={cn(
                        "text-xs px-3 py-1.5 rounded-lg border transition-all",
                        preTranslateProvider === opt.key
                          ? "border-primary bg-primary/10 text-primary font-medium"
                          : "border-border hover:border-primary/40 text-muted-foreground"
                      )}
                    >
                      {opt.label}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </section>

        <Separator />

        <section>
          <h2 className="text-lg font-bold text-foreground mb-1">External API Keys</h2>
          <p className="text-sm text-muted-foreground mb-5">All third-party integrations managed in one place</p>

          <div className="border border-border rounded-lg overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-muted/50 text-left">
                  <th className="px-4 py-2.5 font-medium text-muted-foreground">Service</th>
                  <th className="px-4 py-2.5 font-medium text-muted-foreground">Status</th>
                  <th className="px-4 py-2.5 font-medium text-muted-foreground">Key</th>
                  <th className="px-4 py-2.5 font-medium text-muted-foreground">Endpoint</th>
                  <th className="px-4 py-2.5 font-medium text-muted-foreground">Actions</th>
                </tr>
              </thead>
              <tbody>
                {KNOWN_SERVICES.filter(svc => AI_VOICE_SERVICE_KEYS.includes(svc.service_key)).map(svc => {
                  const existing = getApiKeyForService(svc.service_key);
                  return (
                    <tr key={svc.service_key} className="border-t border-border">
                      <td className="px-4 py-2.5 font-medium text-foreground">
                        <span className="mr-1.5">{svc.emoji}</span>{svc.service_name}
                      </td>
                      <td className="px-4 py-2.5">{getStatusBadge(svc)}</td>
                      <td className="px-4 py-2.5 font-mono text-xs text-muted-foreground">
                        {maskKey((existing?.config as Record<string, string>)?.api_key)}
                      </td>
                      <td className="px-4 py-2.5 text-xs text-muted-foreground">{svc.endpoint}</td>
                      <td className="px-4 py-2.5 flex gap-1">
                        {existing && (
                          <Button
                            variant="ghost"
                            size="sm"
                            className="gap-1 text-xs"
                            disabled={testing === svc.service_key}
                            onClick={() => testApiKey(svc.service_key)}
                          >
                            {testing === svc.service_key ? <Loader2 size={12} className="animate-spin" /> : <FlaskConical size={12} />}
                            Test
                          </Button>
                        )}
                        <Button
                          variant="ghost"
                          size="sm"
                          className="gap-1 text-xs"
                          onClick={() => {
                            setEditingKey(svc);
                            const ex = getApiKeyForService(svc.service_key);
                            const cfg = (ex?.config as Record<string, string>) || {};
                            setKeyForm({
                              api_key: cfg.api_key || "",
                              endpoint: cfg.endpoint || svc.endpoint,
                              mode: cfg.mode || "production",
                              deployment: cfg.deployment || "",
                              api_version: cfg.api_version || "",
                              // Default GPT-5 / o-series to the Responses API (their only surface)
                              // when no explicit style was saved.
                              api_style: cfg.api_style || (isAzureReasoningModel(cfg.deployment || "") ? "responses" : "chat_completions"),
                              azure_surface: cfg.azure_surface || "auto",
                            });
                            setShowSecret(false);
                            setAzureModels([]);
                            setAzureModelsError(null);
                          }}
                        >
                          {existing ? "Edit" : <><Plus size={12} /> Add</>}
                        </Button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </section>

        <Separator />

        {/* ── SECTION 4: DEVELOPER TOOLS ── */}
        <section ref={playgroundRef}>
          <h2 className="text-sm font-bold text-foreground mb-3">Developer Tools — AI Playground</h2>
          <div className="grid grid-cols-2 gap-3 mb-3">
            <div>
              <Label className="text-xs">Feature Key</Label>
              <Select value={playFeature} onValueChange={setPlayFeature}>
                <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {Object.entries(FEATURE_LABELS).map(([k, v]) => (
                    <SelectItem key={k} value={k}>{v}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs">Resolved Provider</Label>
              <Input
                className="mt-1"
                readOnly
                value={(() => {
                  const fc = aiConfigs.find(c => c.feature_key === playFeature);
                  return fc ? `${getProviderLabel(fc.provider)} / ${fc.model_name}` : "Using global default";
                })()}
              />
            </div>
          </div>
          <div>
            <Label className="text-xs">Prompt</Label>
            <Textarea
              className="mt-1 font-mono text-xs min-h-[100px]"
              value={playPrompt}
              onChange={e => setPlayPrompt(e.target.value)}
            />
          </div>
          <Button
            size="sm"
            className="mt-3 gap-1.5"
            disabled={playRunning}
            onClick={runPlayground}
          >
            {playRunning ? <Loader2 size={14} className="animate-spin" /> : <Play size={14} />}
            Run
          </Button>

          {playResult && (
            <div className="mt-3 bg-slate-900 text-white rounded-lg p-4 font-mono text-xs">
              <pre className="whitespace-pre-wrap mb-3">{playResult.text}</pre>
              <Separator className="bg-slate-700 my-2" />
              <p className="text-slate-400 text-[11px]">
                Provider: {playResult.provider} · Model: {playResult.model}
                {playResult.tokens ? ` · Tokens: ${playResult.tokens}` : ""}
                {playResult.ms ? ` · ${playResult.ms}ms` : ""}
              </p>
            </div>
          )}
        </section>
      </div>

      {/* ── API KEY DRAWER ── */}
      <Sheet open={!!editingKey} onOpenChange={() => setEditingKey(null)}>
        <SheetContent className="w-[400px] flex flex-col">
          <SheetHeader>
            <SheetTitle className="flex items-center gap-2">
              {editingKey && <span>{editingKey.emoji}</span>}
              {editingKey?.service_name}
            </SheetTitle>
          </SheetHeader>
          <div className="space-y-4 mt-6 flex-1 overflow-y-auto pr-2 -mr-2 min-h-0">
            <div>
              <Label>API Key</Label>
              <div className="relative mt-1">
                <Input
                  type={showSecret ? "text" : "password"}
                  value={keyForm.api_key}
                  onChange={e => setKeyForm(p => ({ ...p, api_key: e.target.value }))}
                  placeholder="Enter API key..."
                  className="pr-10"
                />
                <button
                  type="button"
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground"
                  onClick={() => setShowSecret(!showSecret)}
                >
                  {showSecret ? <EyeOff size={14} /> : <Eye size={14} />}
                </button>
              </div>
            </div>
            <div>
              <Label>Endpoint URL</Label>
              <Input
                className="mt-1"
                value={keyForm.endpoint}
                onChange={e => setKeyForm(p => ({ ...p, endpoint: e.target.value }))}
                placeholder={editingKey?.service_key === "azure_openai" ? "https://YOUR-RESOURCE.services.ai.azure.com/" : ""}
              />
              {editingKey?.service_key === "azure_openai" && (
                <p className="text-[11px] text-muted-foreground mt-1">
                  Use the <b>resource root only</b> — e.g. <code>https://YOUR-RESOURCE.services.ai.azure.com/</code>. Do <b>not</b> paste the Foundry <b>project</b> endpoint (<code>…/api/projects/NAME</code>) — that's the Agents/SDK URL, not the inference one. Any extra path is stripped automatically on save.
                </p>
              )}
            </div>

            {editingKey?.service_key === "azure_openai" && (
              <>
                <div>
                  <Label>Model surface</Label>
                  <select
                    className="mt-1 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                    value={keyForm.azure_surface}
                    onChange={e => setKeyForm(p => ({ ...p, azure_surface: e.target.value }))}
                  >
                    {AZURE_SURFACES.map(s => <option key={s.value} value={s.value}>{s.label}</option>)}
                  </select>
                  <p className="text-[11px] text-muted-foreground mt-1">
                    How this deployment is served on Foundry. <b>Auto</b> routes Claude deployments to the Anthropic Messages API and everything else to the OpenAI-compatible surface. Pick <b>Anthropic</b> for Claude, or <b>Foundry Models</b> for serverless (/models) deployments.
                  </p>
                </div>
                <div>
                  <Label>Deployment Name</Label>
                  <div className="flex gap-2 mt-1">
                    <Input
                      className="flex-1"
                      list="azure-deployment-models"
                      value={keyForm.deployment}
                      onChange={e => {
                        const v = e.target.value;
                        setKeyForm(p => {
                          // Auto-pick Responses API for GPT-5 / o-series (chat completions 404s
                          // for them) when the surface is auto/openai-compatible.
                          const openaiSurface = p.azure_surface === "auto" || p.azure_surface === "openai" || !p.azure_surface;
                          const forceResponses = openaiSurface && isAzureReasoningModel(v) && !p.api_version;
                          return { ...p, deployment: v, ...(forceResponses ? { api_style: "responses" } : {}) };
                        });
                      }}
                      placeholder="e.g. gpt-4o, gpt-5.1, Llama-3.3-70B-Instruct, Mistral-Large-2411"
                    />
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      className="gap-1 shrink-0"
                      disabled={!keyForm.api_key || !keyForm.endpoint || fetchingAzureModels}
                      onClick={fetchAzureModels}
                    >
                      {fetchingAzureModels ? <Loader2 size={14} className="animate-spin" /> : <RefreshCw size={14} />}
                      Fetch
                    </Button>
                  </div>
                  <datalist id="azure-deployment-models">
                    {azureModels.map(id => <option key={id} value={id} />)}
                  </datalist>
                  {azureModelsError && (
                    <p className="text-[11px] text-amber-600 mt-1">{azureModelsError}</p>
                  )}
                  <p className="text-[11px] text-muted-foreground mt-1">
                    The deployment name you created in Azure AI Foundry / Azure OpenAI Studio. Works with any model in the catalog (GPT, Llama, Mistral, DeepSeek, Cohere, etc.) — click Fetch to list deployments at this endpoint, or type the name directly.
                  </p>
                </div>
                <div>
                  <Label>API Version <span className="text-muted-foreground font-normal">(optional)</span></Label>
                  <Input
                    className="mt-1"
                    list="azure-api-versions"
                    value={keyForm.api_version}
                    onChange={e => setKeyForm(p => ({ ...p, api_version: e.target.value, ...(e.target.value ? { api_style: "chat_completions" } : {}) }))}
                    placeholder="Leave blank to use the latest /openai/v1 API"
                  />
                  <datalist id="azure-api-versions">
                    <option value="2024-02-01" />
                    <option value="2024-05-01-preview" />
                    <option value="2024-08-01-preview" />
                    <option value="2024-10-01-preview" />
                    <option value="2025-01-01-preview" />
                    <option value="2025-03-01-preview" />
                    <option value="2025-04-01-preview" />
                  </datalist>
                  <p className="text-[11px] text-muted-foreground mt-1">
                    Leave blank to call the new /openai/v1 surface (no version pinning needed). Set a version only if you need the classic dated GA/preview API.
                  </p>
                </div>
                {resolveAzureSurfaceUI(keyForm.azure_surface, keyForm.deployment) === "openai" && (
                <div>
                  <Label>API Style <span className="text-muted-foreground font-normal">(advanced)</span></Label>
                  <div className="flex gap-3 mt-1">
                    {[{ v: "chat_completions", l: "Chat Completions (default)" }, { v: "responses", l: "Responses API" }].map(o => (
                      <label key={o.v} className={cn("flex items-center gap-1.5 text-sm", o.v === "responses" && !!keyForm.api_version ? "opacity-40 cursor-not-allowed" : "cursor-pointer")}>
                        <input
                          type="radio"
                          name="api_style"
                          checked={keyForm.api_style === o.v}
                          disabled={o.v === "responses" && !!keyForm.api_version}
                          onChange={() => setKeyForm(p => ({ ...p, api_style: o.v }))}
                          className="accent-primary"
                        />
                        {o.l}
                      </label>
                    ))}
                  </div>
                  <p className="text-[11px] text-muted-foreground mt-1">
                    Chat Completions works with every model in the catalog (GPT, Llama, Mistral, DeepSeek, Cohere). Responses API is OpenAI-only (GPT/o-series) and requires API Version to be blank.
                  </p>
                </div>
                )}
              </>
            )}
            <div>
              <Label>Mode</Label>
              <div className="flex gap-3 mt-1">
                {["sandbox", "production"].map(m => (
                  <label key={m} className="flex items-center gap-1.5 text-sm cursor-pointer">
                    <input
                      type="radio"
                      name="mode"
                      checked={keyForm.mode === m}
                      onChange={() => setKeyForm(p => ({ ...p, mode: m }))}
                      className="accent-primary"
                    />
                    {m === "sandbox" ? "Sandbox / Test" : "Production / Live"}
                  </label>
                ))}
              </div>
            </div>

            {editingKey?.service_key === "razorpay" && (
              <div>
                <Label>Key Secret</Label>
                <Input className="mt-1" type="password" placeholder="Razorpay key secret..." />
              </div>
            )}
            {editingKey?.service_key === "wati" && (
              <div>
                <Label>Phone Number</Label>
                <Input className="mt-1" placeholder="+91..." />
              </div>
            )}
            {editingKey?.service_key === "bhashini" && (
              <div className="space-y-3">
                <div>
                  <Label>User ID (from bhashini.gov.in)</Label>
                  <Input
                    className="mt-1"
                    placeholder="Bhashini User ID"
                    value={(keyForm as Record<string, string>).user_id || ""}
                    onChange={e => setKeyForm(p => ({ ...p, user_id: e.target.value }))}
                  />
                </div>
                <p className="text-[10px] text-muted-foreground">
                  Get free credentials at{" "}
                  <a href="https://bhashini.gov.in" target="_blank" rel="noopener noreferrer" className="underline text-primary">
                    bhashini.gov.in
                  </a>
                </p>
              </div>
            )}
            {editingKey?.service_key === "nic_irp" && (
              <>
                <div><Label>Username</Label><Input className="mt-1" placeholder="NIC IRP username" /></div>
                <div><Label>Password</Label><Input className="mt-1" type="password" placeholder="NIC IRP password" /></div>
              </>
            )}

            {/* Custom Model Management — only for LLM providers */}
            {editingKey && ["anthropic", "openai", "gemini", "perplexity", "openrouter"].includes(editingKey.service_key) && (() => {
              const providerKey = Object.entries(PROVIDER_TO_SERVICE_KEY).find(([, sk]) => sk === editingKey.service_key)?.[0] || editingKey.service_key;
              const allModels = getMergedModels(providerKey);
              const customModels = getCustomModels(providerKey);
              return (
                <div className="space-y-2">
                  <Separator />
                  <Label className="text-xs font-bold uppercase text-muted-foreground">Models</Label>
                  <div className="space-y-1 max-h-[180px] overflow-y-auto">
                    {allModels.map(m => (
                      <div key={m.value} className="flex items-center justify-between bg-muted/50 rounded px-2.5 py-1.5 text-xs">
                        <div className="flex items-center gap-2 min-w-0">
                          <code className="font-mono text-foreground truncate">{m.value}</code>
                          {m.isCustom && <Badge variant="outline" className="text-[9px] px-1 py-0">Custom</Badge>}
                        </div>
                        {m.isCustom && (
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-6 w-6 p-0 text-destructive hover:text-destructive"
                            onClick={() => {
                              const updated = customModels.filter(cm => cm.value !== m.value);
                              saveCustomModels(providerKey, updated);
                              setModelRefreshKey(k => k + 1);
                              toast({ title: `Removed model: ${m.value}` });
                            }}
                          >
                            <Trash2 size={12} />
                          </Button>
                        )}
                      </div>
                    ))}
                  </div>
                  <div className="flex gap-2">
                    <Input
                      className="text-xs font-mono h-8 flex-1"
                      placeholder="e.g. gemini-3-flash-preview"
                      value={customModelInput}
                      onChange={e => setCustomModelInput(e.target.value)}
                      onKeyDown={e => {
                        if (e.key === "Enter" && customModelInput.trim()) {
                          const val = customModelInput.trim();
                          if (allModels.some(m => m.value === val)) {
                            toast({ title: "Model already exists", variant: "destructive" });
                            return;
                          }
                          saveCustomModels(providerKey, [...customModels, { label: val, value: val }]);
                          setCustomModelInput("");
                          setModelRefreshKey(k => k + 1);
                          toast({ title: `Added model: ${val}` });
                        }
                      }}
                    />
                    <Button
                      size="sm"
                      variant="outline"
                      className="h-8 gap-1 text-xs"
                      disabled={!customModelInput.trim()}
                      onClick={() => {
                        const val = customModelInput.trim();
                        if (!val) return;
                        if (allModels.some(m => m.value === val)) {
                          toast({ title: "Model already exists", variant: "destructive" });
                          return;
                        }
                        saveCustomModels(providerKey, [...customModels, { label: val, value: val }]);
                        setCustomModelInput("");
                        setModelRefreshKey(k => k + 1);
                        toast({ title: `Added model: ${val}` });
                      }}
                    >
                      <Plus size={12} /> Add
                    </Button>
                  </div>
                  <p className="text-[10px] text-muted-foreground">Add custom model codes. They'll appear in model dropdowns marked with ★</p>
                </div>
              );
            })()}
          </div>
          <div className="flex gap-2 pt-3 border-t shrink-0">
            <Button
              variant="outline"
              className="gap-1"
              disabled={!keyForm.api_key || testing === editingKey?.service_key}
              onClick={() => editingKey && testApiKey(editingKey.service_key, keyForm)}
            >
              {testing === editingKey?.service_key ? <Loader2 size={14} className="animate-spin" /> : <FlaskConical size={14} />}
              Test Connection
            </Button>
            <Button
              className="gap-1 flex-1"
              disabled={!keyForm.api_key || saving === editingKey?.service_key}
              onClick={saveApiKey}
            >
              {saving === editingKey?.service_key ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />}
              Save
            </Button>
          </div>
        </SheetContent>
      </Sheet>
    </div>
  );
};

export default PlatformAIConfigPage;

import React, { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { usePatientPortal } from "@/hooks/usePatientPortal";
import { ChevronDown, ChevronUp, Download, X, Pill } from "lucide-react";

type Tab = "lab" | "radiology" | "prescriptions";

/* ── Shared ──────────────────────────────────────────────────────────────── */
const SkeletonList: React.FC = () => (
  <div className="space-y-2.5">
    {[1, 2, 3].map((i) => (
      <div key={i} className="bg-white rounded-xl p-4 animate-pulse" style={{ border: "1px solid #E2E8F0" }}>
        <div className="h-3 w-20 rounded" style={{ background: "#E2E8F0" }} />
        <div className="h-4 w-36 rounded mt-2" style={{ background: "#E2E8F0" }} />
        <div className="h-3 w-24 rounded mt-1.5" style={{ background: "#E2E8F0" }} />
      </div>
    ))}
  </div>
);

const EmptyState: React.FC<{ emoji: string; title: string; sub: string }> = ({ emoji, title, sub }) => (
  <div className="bg-white rounded-xl p-10 text-center" style={{ border: "1px solid #E2E8F0" }}>
    <span className="text-[32px]">{emoji}</span>
    <p className="text-sm font-semibold mt-2" style={{ color: "#374151" }}>{title}</p>
    <p className="text-[13px] mt-1" style={{ color: "#94A3B8" }}>{sub}</p>
  </div>
);

const StatusBadge: React.FC<{ label: string; color: string; bg: string }> = ({ label, color, bg }) => (
  <span className="text-[10px] font-bold uppercase px-2 py-0.5 rounded-full" style={{ color, background: bg }}>
    {label}
  </span>
);

/* ── Lab Tab ─────────────────────────────────────────────────────────────── */
const LabTab: React.FC<{ patientId: string; hospitalId: string; patientName: string; uhid: string; hospitalName: string }> = ({
  patientId, hospitalId, patientName, uhid, hospitalName,
}) => {
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState<string | null>(null);
  const [items, setItems] = useState<Record<string, any[]>>({});

  useEffect(() => {
    (async () => {
      const { data } = await (supabase as any)
        .from("lab_orders")
        .select("id, order_date, status, ordered_by")
        .eq("patient_id", patientId)
        .eq("hospital_id", hospitalId)
        .in("status", ["completed", "reported", "validated"])
        .order("order_date", { ascending: false })
        .limit(30);

      const enriched = await Promise.all(
        (data || []).map(async (o: any) => {
          const { data: orderItems } = await supabase
            .from("lab_order_items")
            .select("id, status")
            .eq("lab_order_id", o.id)
            .eq("hospital_id", hospitalId);

          const total = orderItems?.length || 0;
          const done = orderItems?.filter(
            (i) => i.status === "reported" || i.status === "validated"
          ).length || 0;

          let doctorName = "";
          if (o.ordered_by) {
            const { data: doc } = await supabase
              .from("users")
              .select("full_name")
              .eq("id", o.ordered_by)
              .maybeSingle();
            doctorName = doc?.full_name || "";
          }

          return { ...o, total, done, doctorName };
        })
      );

      setOrders(enriched);
      setLoading(false);
    })();
  }, [patientId, hospitalId]);

  useEffect(() => {
    if (!expanded || items[expanded]) return;
    (async () => {
      const { data } = await supabase
        .from("lab_order_items")
        .select("id, test_id, status, result_value, result_unit, result_flag, reference_range")
        .eq("lab_order_id", expanded)
        .eq("hospital_id", hospitalId);

      const enriched = await Promise.all(
        (data || []).map(async (item) => {
          const { data: test } = await (supabase as any)
            .from("lab_test_master")
            .select("test_name")
            .eq("id", item.test_id)
            .maybeSingle();
          return { ...item, testName: test?.test_name || "Test" };
        })
      );
      setItems((prev) => ({ ...prev, [expanded]: enriched }));
    })();
  }, [expanded, hospitalId]);

  const labBadge = (status: string) => {
    if (["completed", "validated", "reported"].includes(status))
      return { label: "✓ Ready", color: "#15803D", bg: "#DCFCE7" };
    return { label: "Processing", color: "#D97706", bg: "#FEF3C7" };
  };

  const handlePrint = (orderId: string) => {
    const orderItems = items[orderId];
    if (!orderItems) return;
    const order = orders.find((o) => o.id === orderId);
    const win = window.open("", "_blank");
    if (!win) return;
    win.document.write(`<html><head><title>Lab Report</title>
      <style>
        body{font-family:sans-serif;padding:32px;max-width:700px;margin:0 auto}
        h1{font-size:18px;color:#0E7B7B;margin-bottom:4px}
        .info{font-size:12px;color:#64748B;margin-bottom:16px}
        table{width:100%;border-collapse:collapse;margin-top:16px}
        th{background:#F1F5F9;text-align:left;padding:8px;font-size:11px;text-transform:uppercase;color:#64748B;border:1px solid #E2E8F0}
        td{padding:8px;font-size:13px;border:1px solid #E2E8F0}
        .abnormal{color:#EF4444;font-weight:bold}
        .footer{margin-top:24px;font-size:11px;color:#94A3B8;border-top:1px solid #E2E8F0;padding-top:12px}
      </style></head><body>
      <h1>🔬 LAB REPORT</h1>
      <p class="info">
        Patient: ${patientName} · UHID: ${uhid}<br/>
        Date: ${new Date(order?.order_date).toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"})}
        ${order?.doctorName ? ` · Dr. ${order.doctorName}` : ""}
      </p>
      <table>
        <tr><th>Test</th><th>Result</th><th>Unit</th><th>Ref. Range</th><th>Flag</th></tr>
        ${orderItems.map((i: any) => {
          const abn = i.result_flag && ["high","low","critical_high","critical_low"].includes(i.result_flag);
          return `<tr>
            <td>${i.testName}</td>
            <td class="${abn ? "abnormal" : ""}">${i.result_value || "—"}</td>
            <td>${i.result_unit || ""}</td>
            <td>${i.reference_range || ""}</td>
            <td class="${abn ? "abnormal" : ""}">${i.result_flag ? i.result_flag.replace("_"," ").toUpperCase() : "Normal"}</td>
          </tr>`;
        }).join("")}
      </table>
      <div class="footer">This report is for reference only. Please discuss results with your doctor.<br/>${hospitalName}</div>
      <script>window.onload=()=>window.print()</script>
    </body></html>`);
    win.document.close();
  };

  return (
    <div className="py-4">
      {loading ? (
        <SkeletonList />
      ) : orders.length === 0 ? (
        <EmptyState emoji="🔬" title="No lab reports yet" sub="Your test results will appear here once ready" />
      ) : (
        <div className="space-y-2.5">
          {orders.map((o) => {
            const badge = labBadge(o.status);
            const isExp = expanded === o.id;
            return (
              <div key={o.id} className="bg-white rounded-xl overflow-hidden" style={{ border: "1px solid #E2E8F0" }}>
                <button onClick={() => setExpanded(isExp ? null : o.id)} className="w-full p-3.5 text-left">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-xs" style={{ color: "#64748B" }}>
                      {new Date(o.order_date).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" })}
                    </span>
                    <StatusBadge {...badge} />
                  </div>
                  <p className="text-[13px] font-bold" style={{ color: "#0F172A" }}>
                    {o.done} of {o.total} tests complete
                  </p>
                  {o.doctorName && (
                    <p className="text-[11px] mt-0.5" style={{ color: "#94A3B8" }}>Ordered by Dr. {o.doctorName}</p>
                  )}
                  <div className="flex justify-end mt-0.5">
                    {isExp ? <ChevronUp size={14} color="#94A3B8" /> : <ChevronDown size={14} color="#94A3B8" />}
                  </div>
                </button>

                {isExp && (
                  <div className="px-3.5 pb-3.5" style={{ borderTop: "1px solid #F1F5F9" }}>
                    {!items[o.id] ? (
                      <p className="text-xs py-3 text-center" style={{ color: "#94A3B8" }}>Loading…</p>
                    ) : items[o.id].length === 0 ? (
                      <p className="text-xs py-3" style={{ color: "#94A3B8" }}>No results recorded yet</p>
                    ) : (
                      <>
                        <div className="space-y-1 py-2">
                          {items[o.id].map((item: any) => {
                            const isAbn = item.result_flag && ["high","low","critical_high","critical_low"].includes(item.result_flag);
                            return (
                              <div key={item.id} className="flex items-center justify-between py-1.5">
                                <span className="text-xs font-medium" style={{ color: "#0F172A" }}>{item.testName}</span>
                                <div className="text-right">
                                  <span className="text-xs font-bold" style={{ color: isAbn ? "#EF4444" : "#0F172A" }}>
                                    {item.result_value || "—"}{item.result_unit ? ` ${item.result_unit}` : ""}
                                  </span>
                                  {item.reference_range && (
                                    <p className="text-[10px]" style={{ color: "#94A3B8" }}>Ref: {item.reference_range}</p>
                                  )}
                                </div>
                              </div>
                            );
                          })}
                        </div>
                        <button
                          onClick={() => handlePrint(o.id)}
                          className="w-full mt-2 rounded-lg flex items-center justify-center gap-2 text-sm font-bold py-2.5"
                          style={{ background: "#0E7B7B", color: "#FFFFFF" }}
                        >
                          <Download size={14} /> Download Report PDF
                        </button>
                      </>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

/* ── Radiology Tab ───────────────────────────────────────────────────────── */
const MODALITY_COLORS: Record<string, string> = {
  "X-Ray": "#3B82F6", "CT": "#8B5CF6", "MRI": "#EC4899",
  "USG": "#0E7B7B", "Ultrasound": "#0E7B7B", "PET": "#F59E0B",
};

const RadiologyTab: React.FC<{ patientId: string; hospitalId: string }> = ({ patientId, hospitalId }) => {
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState<string | null>(null);

  useEffect(() => {
    (async () => {
      const { data } = await supabase
        .from("radiology_orders")
        .select("id, study_name, modality_type, order_date, status, ordered_by, body_part")
        .eq("patient_id", patientId)
        .eq("hospital_id", hospitalId)
        .order("order_date", { ascending: false })
        .limit(30);

      const enriched = await Promise.all(
        (data || []).map(async (o) => {
          let doctorName = "";
          if (o.ordered_by) {
            const { data: doc } = await supabase.from("users").select("full_name").eq("id", o.ordered_by).maybeSingle();
            doctorName = doc?.full_name || "";
          }
          const { data: rep } = await supabase
            .from("radiology_reports")
            .select("impression, findings, recommendations, critical_finding, is_critical, is_signed")
            .eq("order_id", o.id)
            .eq("is_signed", true)
            .maybeSingle();
          return { ...o, doctorName, report: rep || null };
        })
      );

      setOrders(enriched);
      setLoading(false);
    })();
  }, [patientId, hospitalId]);

  const radiologyBadge = (status: string, hasReport: boolean) => {
    if (hasReport || status === "validated" || status === "reported")
      return { label: "✓ Ready", color: "#15803D", bg: "#DCFCE7" };
    if (["in_progress", "scheduled", "scan_done"].includes(status))
      return { label: "Processing", color: "#D97706", bg: "#FEF3C7" };
    return { label: "Pending", color: "#64748B", bg: "#F1F5F9" };
  };

  return (
    <div className="py-4">
      {loading ? (
        <SkeletonList />
      ) : orders.length === 0 ? (
        <EmptyState emoji="🩻" title="No radiology reports yet" sub="Your imaging results will appear here once signed off" />
      ) : (
        <div className="space-y-2.5">
          {orders.map((o) => {
            const badge = radiologyBadge(o.status, !!o.report);
            const isExp = expanded === o.id;
            const modalColor = MODALITY_COLORS[o.modality_type] || "#64748B";
            return (
              <div key={o.id} className="bg-white rounded-xl overflow-hidden" style={{ border: "1px solid #E2E8F0" }}>
                <button
                  onClick={() => o.report && setExpanded(isExp ? null : o.id)}
                  className="w-full p-3.5 text-left"
                  style={{ cursor: o.report ? "pointer" : "default" }}
                >
                  <div className="flex items-center justify-between mb-1">
                    <span
                      className="text-[10px] font-bold uppercase px-2 py-0.5 rounded-full"
                      style={{ color: modalColor, background: `${modalColor}20` }}
                    >
                      {o.modality_type || "Imaging"}
                    </span>
                    <StatusBadge {...badge} />
                  </div>
                  <p className="text-[13px] font-bold mt-1" style={{ color: "#0F172A" }}>
                    {o.study_name}{o.body_part ? ` — ${o.body_part}` : ""}
                  </p>
                  <p className="text-xs mt-0.5" style={{ color: "#64748B" }}>
                    {new Date(o.order_date).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" })}
                    {o.doctorName ? ` · Dr. ${o.doctorName}` : ""}
                  </p>
                  {o.report && (
                    <div className="flex justify-end mt-0.5">
                      {isExp ? <ChevronUp size={14} color="#94A3B8" /> : <ChevronDown size={14} color="#94A3B8" />}
                    </div>
                  )}
                </button>

                {isExp && o.report && (
                  <div className="px-3.5 pb-3.5 space-y-3" style={{ borderTop: "1px solid #F1F5F9" }}>
                    {o.report.is_critical && o.report.critical_finding && (
                      <div className="rounded-lg p-2.5" style={{ background: "#FEF2F2", border: "1px solid #FECACA" }}>
                        <span className="text-[10px] font-bold uppercase" style={{ color: "#DC2626" }}>Critical Finding</span>
                        <p className="text-xs mt-0.5" style={{ color: "#7F1D1D" }}>{o.report.critical_finding}</p>
                      </div>
                    )}
                    {o.report.impression && (
                      <div>
                        <span className="text-[10px] font-bold uppercase" style={{ color: "#94A3B8" }}>Impression</span>
                        <p className="text-xs mt-0.5 whitespace-pre-wrap" style={{ color: "#374151" }}>{o.report.impression}</p>
                      </div>
                    )}
                    {o.report.findings && (
                      <div>
                        <span className="text-[10px] font-bold uppercase" style={{ color: "#94A3B8" }}>Findings</span>
                        <p className="text-xs mt-0.5 whitespace-pre-wrap" style={{ color: "#374151" }}>{o.report.findings}</p>
                      </div>
                    )}
                    {o.report.recommendations && (
                      <div>
                        <span className="text-[10px] font-bold uppercase" style={{ color: "#94A3B8" }}>Recommendations</span>
                        <p className="text-xs mt-0.5" style={{ color: "#374151" }}>{o.report.recommendations}</p>
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

/* ── Prescriptions Tab ───────────────────────────────────────────────────── */
interface DrugEntry {
  name?: string;
  drug_name?: string;
  dose?: string;
  dosage?: string;
  frequency?: string;
  route?: string;
  duration?: string;
  instructions?: string;
}

interface RxRecord {
  id: string;
  prescription_date: string | null;
  doctor_id: string | null;
  drugs: unknown;
  is_signed: boolean | null;
  advice_notes: string | null;
  review_date: string | null;
  doctorName: string;
  drugList: DrugEntry[];
}

const PrescriptionsTab: React.FC<{
  patientId: string;
  hospitalId: string;
  patientName: string;
  uhid: string;
  hospitalName: string;
}> = ({ patientId, hospitalId, patientName, uhid, hospitalName }) => {
  const [prescriptions, setPrescriptions] = useState<RxRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewRx, setViewRx] = useState<RxRecord | null>(null);

  useEffect(() => {
    (async () => {
      const { data } = await (supabase as any)
        .from("prescriptions")
        .select("id, prescription_date, doctor_id, drugs, is_signed, advice_notes, review_date")
        .eq("patient_id", patientId)
        .eq("hospital_id", hospitalId)
        .order("prescription_date", { ascending: false })
        .limit(30);

      const enriched = await Promise.all(
        (data || []).map(async (rx: any) => {
          let doctorName = "";
          if (rx.doctor_id) {
            const { data: doc } = await supabase
              .from("users")
              .select("full_name")
              .eq("id", rx.doctor_id)
              .maybeSingle();
            doctorName = doc?.full_name || "";
          }
          let drugList: DrugEntry[] = [];
          if (Array.isArray(rx.drugs)) {
            drugList = rx.drugs as DrugEntry[];
          } else if (rx.drugs && typeof rx.drugs === "object") {
            drugList = [rx.drugs as DrugEntry];
          }
          return { ...rx, doctorName, drugList };
        })
      );

      setPrescriptions(enriched);
      setLoading(false);
    })();
  }, [patientId, hospitalId]);

  const keyDrugs = (drugList: DrugEntry[], max = 3) =>
    drugList
      .slice(0, max)
      .map((d) => d.name || d.drug_name || "Drug")
      .join(", ");

  const handlePrintRx = (rx: RxRecord) => {
    const win = window.open("", "_blank");
    if (!win) return;
    win.document.write(`<html><head><title>Prescription</title>
      <style>
        body{font-family:sans-serif;padding:32px;max-width:700px;margin:0 auto}
        h1{font-size:18px;color:#0E7B7B;margin-bottom:4px}
        .info{font-size:12px;color:#64748B;margin-bottom:16px}
        .drug{margin-bottom:10px;padding:10px;border:1px solid #E2E8F0;border-radius:6px}
        .dname{font-size:14px;font-weight:700;color:#0F172A}
        .dmeta{font-size:11px;color:#64748B;margin-top:2px}
        .section{margin-top:14px}
        .section-title{font-size:11px;font-weight:700;text-transform:uppercase;color:#94A3B8;margin-bottom:4px}
        .footer{margin-top:24px;font-size:11px;color:#94A3B8;border-top:1px solid #E2E8F0;padding-top:12px}
      </style></head><body>
      <h1>💊 PRESCRIPTION</h1>
      <p class="info">
        Patient: ${patientName} · UHID: ${uhid}<br/>
        Date: ${rx.prescription_date ? new Date(rx.prescription_date).toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"}) : "—"}
        ${rx.doctorName ? ` · Dr. ${rx.doctorName}` : ""}
        ${rx.is_signed ? " · ✓ Signed" : ""}
      </p>
      <div class="section">
        <div class="section-title">Medications</div>
        ${rx.drugList.map((d) => `<div class="drug">
          <div class="dname">${d.name || d.drug_name || "—"}</div>
          <div class="dmeta">
            ${[d.dose || d.dosage, d.route, d.frequency, d.duration ? `for ${d.duration}` : ""].filter(Boolean).join(" · ")}
          </div>
          ${d.instructions ? `<div class="dmeta" style="margin-top:4px;font-style:italic">${d.instructions}</div>` : ""}
        </div>`).join("")}
      </div>
      ${rx.advice_notes ? `<div class="section"><div class="section-title">Advice</div><p style="font-size:13px;color:#374151">${rx.advice_notes}</p></div>` : ""}
      ${rx.review_date ? `<div class="section"><div class="section-title">Review Date</div><p style="font-size:13px;color:#374151">${new Date(rx.review_date).toLocaleDateString("en-IN",{day:"numeric",month:"long",year:"numeric"})}</p></div>` : ""}
      <div class="footer">This prescription is for reference only.<br/>${hospitalName}</div>
      <script>window.onload=()=>window.print()</script>
    </body></html>`);
    win.document.close();
  };

  return (
    <>
      <div className="py-4">
        {loading ? (
          <SkeletonList />
        ) : prescriptions.length === 0 ? (
          <EmptyState emoji="💊" title="No prescriptions yet" sub="Prescriptions from your visits will appear here" />
        ) : (
          <div className="space-y-2.5">
            {prescriptions.map((rx) => (
              <div key={rx.id} className="bg-white rounded-xl p-3.5" style={{ border: "1px solid #E2E8F0" }}>
                <div className="flex items-start justify-between gap-2">
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-1.5 flex-wrap">
                      <span className="text-xs" style={{ color: "#64748B" }}>
                        {rx.prescription_date
                          ? new Date(rx.prescription_date).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" })
                          : "—"}
                      </span>
                      {rx.is_signed && (
                        <span className="text-[10px] font-bold uppercase px-1.5 py-0.5 rounded-full" style={{ color: "#15803D", background: "#DCFCE7" }}>
                          ✓ Signed
                        </span>
                      )}
                    </div>
                    {rx.doctorName && (
                      <p className="text-[13px] font-bold mt-0.5" style={{ color: "#0F172A" }}>
                        Dr. {rx.doctorName}
                      </p>
                    )}
                    {rx.drugList.length > 0 && (
                      <p className="text-xs mt-1 flex items-center gap-1" style={{ color: "#64748B" }}>
                        <Pill size={11} />
                        {keyDrugs(rx.drugList)}
                        {rx.drugList.length > 3 && ` +${rx.drugList.length - 3} more`}
                      </p>
                    )}
                  </div>
                  <button
                    onClick={() => setViewRx(rx)}
                    className="flex-shrink-0 text-xs font-bold px-3 py-1.5 rounded-lg"
                    style={{ background: "#F0FAFA", color: "#0E7B7B", border: "1px solid #B2DFDF" }}
                  >
                    View
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Full Rx Modal */}
      {viewRx && (
        <div
          className="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4"
          style={{ background: "rgba(0,0,0,0.45)" }}
          onClick={(e) => e.target === e.currentTarget && setViewRx(null)}
        >
          <div
