// Phase 6C — Health Coach Bot (Patient Portal)
// Post-discharge chronic disease coaching for patients: DM, HTN, cardiac, COPD, etc.
// Uses callAI (GPT-4o) with discharge summary, medications, and vitals as context.
//
// SaMD Class B — coaching content must not substitute physician advice.
// Dr. Nalini sign-off required before production rollout of symptom-specific coaching.

import React, { useState, useEffect, useRef, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { callAI } from "@/lib/aiProvider";
import { usePatientPortal } from "@/hooks/usePatientPortal";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Send, Heart, User, Bot, Loader2, ChevronDown, ChevronUp } from "lucide-react";
import { format, differenceInDays } from "date-fns";

interface CoachMessage {
  id: string;
  role: "user" | "assistant";
  content: string;
  created_at: string;
}

interface DischargeContext {
  diagnosis: string;
  discharge_date: string;
  discharge_instructions: string;
  medications: string;
  recent_vitals: string;
  days_since_discharge: number;
}

const TEAL = "#0E7B7B";
const TEAL_LIGHT = "#E6F4F4";

// Coaching tip cards for chronic conditions
const CONDITION_TIPS: Record<string, string[]> = {
  diabetes: [
    "Check your blood sugar at the same time every day",
    "Eat smaller portions and avoid sugary drinks",
    "A 20-minute walk after meals helps control blood sugar",
    "Never skip your insulin or diabetes medications",
  ],
  hypertension: [
    "Reduce salt: aim for less than 5g per day",
    "Check your BP at home twice daily and record it",
    "Avoid stress — try deep breathing for 5 minutes daily",
    "Take your BP medications at the same time every day",
  ],
  cardiac: [
    "Weigh yourself daily — gain of >1 kg in a day needs a doctor call",
    "No lifting heavy objects for 4–6 weeks post-discharge",
    "Take all heart medications as prescribed — don't stop without consulting your doctor",
    "Rest if you feel chest pain, shortness of breath, or palpitations",
  ],
  copd: [
    "Use your inhaler exactly as prescribed — correct technique matters",
    "Avoid smoky environments and strong chemical odours",
    "Practise pursed-lip breathing when you feel breathless",
    "Get your flu and pneumonia vaccines every year",
  ],
};

const detectCondition = (diagnosis: string): string | null => {
  const d = diagnosis.toLowerCase();
  if (d.includes("diabet") || d.includes("dm ") || d.includes("type 2") || d.includes("type 1")) return "diabetes";
  if (d.includes("hypertens") || d.includes("htn") || d.includes("blood pressure")) return "hypertension";
  if (d.includes("cardiac") || d.includes("heart") || d.includes("mi ") || d.includes("chf") || d.includes("coronary")) return "cardiac";
  if (d.includes("copd") || d.includes("asthma") || d.includes("pulmon")) return "copd";
  return null;
};

const PortalHealthCoachPage: React.FC = () => {
  const { patientId, hospitalId, patient, hospital } = usePatientPortal();
  const [messages, setMessages] = useState<CoachMessage[]>([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [contextLoading, setContextLoading] = useState(true);
  const [dischargeCtx, setDischargeCtx] = useState<DischargeContext | null>(null);
  const [tipsExpanded, setTipsExpanded] = useState(true);
  const bottomRef = useRef<HTMLDivElement>(null);


  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const loadContext = useCallback(async () => {
    setContextLoading(true);
    try {
      // Get most recent completed admission (discharge)
      const { data: admission } = await (supabase as any)
        .from("admissions")
        .select("id, diagnosis, discharge_date, discharge_notes, discharge_instructions")
        .eq("patient_id", patientId)
        .eq("status", "discharged")
        .order("discharge_date", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (!admission) { setContextLoading(false); return; }

      // Get current medications
      const { data: meds } = await (supabase as any)
        .from("prescriptions")
        .select("drug_name, dosage, frequency, route, duration_days")
        .eq("patient_id", patientId)
        .order("prescribed_date", { ascending: false })
        .limit(8);

      const medList = (meds || [])
        .map((m: any) => `${m.drug_name} ${m.dosage} ${m.route} — ${m.frequency}`)
        .join("; ") || "None recorded";

      // Get recent vitals
      const { data: vitals } = await (supabase as any)
        .from("patient_vitals")
        .select("recorded_at, systolic_bp, diastolic_bp, pulse_rate, temperature, spo2, blood_glucose")
        .eq("patient_id", patientId)
        .order("recorded_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      const vitalStr = vitals
        ? [
            vitals.systolic_bp ? `BP: ${vitals.systolic_bp}/${vitals.diastolic_bp} mmHg` : null,
            vitals.pulse_rate ? `Pulse: ${vitals.pulse_rate} bpm` : null,
            vitals.spo2 ? `SpO2: ${vitals.spo2}%` : null,
            vitals.temperature ? `Temp: ${vitals.temperature}°C` : null,
            vitals.blood_glucose ? `Glucose: ${vitals.blood_glucose} mg/dL` : null,
          ].filter(Boolean).join(", ")
        : "Not recorded";

      const dischargeDate = admission.discharge_date || admission.discharge_notes?.substring(0, 10) || "";
      const daysSince = dischargeDate ? differenceInDays(new Date(), new Date(dischargeDate)) : 0;

      setDischargeCtx({
        diagnosis: admission.diagnosis || "General",
        discharge_date: dischargeDate ? format(new Date(dischargeDate), "dd/MM/yyyy") : "N/A",
        discharge_instructions: admission.discharge_instructions || admission.discharge_notes || "Refer to your discharge summary.",
        medications: medList,
        recent_vitals: vitalStr,
        days_since_discharge: daysSince,
      });
    } finally {
      setContextLoading(false);
    }
  }, [patientId, hospitalId]);

  const loadMessages = useCallback(async () => {
    const { data } = await supabase
      .from("health_coach_sessions")
      .select("id, role, content, created_at")
      .eq("patient_id", patientId!)
      .eq("hospital_id", hospitalId!)
      .order("created_at", { ascending: true })
      .limit(50);
    if (data) setMessages(data as CoachMessage[]);
  }, [patientId, hospitalId]);

  useEffect(() => {
    if (!patientId || !hospitalId) return;
    loadContext();
    loadMessages();
  }, [patientId, hospitalId, loadContext, loadMessages]);

  const saveMessage = async (role: "user" | "assistant", content: string) => {
    if (!patientId || !hospitalId) return;
    const { data } = await supabase
      .from("health_coach_sessions")
      .insert({ patient_id: patientId, hospital_id: hospitalId, role, content })
      .select("id, role, content, created_at")
      .maybeSingle();
    if (data) setMessages((prev) => [...prev, data as CoachMessage]);
  };

  const sendMessage = async () => {
    const text = input.trim();
    if (!text || loading || !patientId || !hospitalId || !dischargeCtx) return;

    setInput("");
    setLoading(true);

    const tempId = `tmp-${Date.now()}`;
    setMessages((prev) => [...prev, { id: tempId, role: "user", content: text, created_at: new Date().toISOString() }]);

    try {
      const { data: promptRow } = await supabase
        .from("prompt_registry")
        .select("system_prompt")
        .eq("feature_key", "health_coach_bot")
        .order("version", { ascending: false })
        .limit(1)
        .maybeSingle();

      const age = patient?.dob
        ? differenceInDays(new Date(), new Date(patient.dob)) / 365 | 0
        : "Unknown";

      const systemPrompt = (promptRow?.system_prompt || "")
        .replace("{{hospital_name}}", hospital?.name || "the hospital")
        .replace("{{patient_name}}", patient?.fullName || "Patient")
        .replace("{{age}}", String(age))
        .replace("{{gender}}", patient?.gender || "N/A")
        .replace("{{diagnosis}}", dischargeCtx.diagnosis)
        .replace("{{discharge_date}}", dischargeCtx.discharge_date)
        .replace("{{discharge_instructions}}", dischargeCtx.discharge_instructions)
        .replace("{{medications}}", dischargeCtx.medications)
        .replace("{{recent_vitals}}", dischargeCtx.recent_vitals)
        .replace("{{days_since_discharge}}", String(dischargeCtx.days_since_discharge));

      const historyText = messages
        .slice(-6)
        .map((m) => `${m.role === "user" ? "Patient" : "Coach"}: ${m.content}`)
        .join("\n");

      const fullPrompt = [systemPrompt, historyText, `Patient: ${text}`].filter(Boolean).join("\n\n");

      const response = await callAI({
        featureKey: "health_coach_bot",
        hospitalId,
        prompt: fullPrompt,
        maxTokens: 350,
      });

      const reply = response.text || "I'm here for you. Please try asking again or contact your care team.";

      setMessages((prev) => prev.filter((m) => m.id !== tempId));
      await saveMessage("user", text);
      await saveMessage("assistant", reply);
    } catch {
      setMessages((prev) => prev.filter((m) => m.id !== tempId));
      await saveMessage("user", text);
      setMessages((prev) => [
        ...prev,
        {
          id: `err-${Date.now()}`,
          role: "assistant",
          content: "I couldn't respond right now. Please try again or contact your hospital care team directly.",
          created_at: new Date().toISOString(),
        },
      ]);
    } finally {
      setLoading(false);
    }
  };

  const conditionKey = dischargeCtx ? detectCondition(dischargeCtx.diagnosis) : null;
  const tips = conditionKey ? CONDITION_TIPS[conditionKey] : null;

  if (contextLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 size={24} className="animate-spin" style={{ color: TEAL }} />
      </div>
    );
  }

  if (!dischargeCtx) {
    return (
      <div className="flex flex-col items-center gap-3 py-16 px-6 text-center">
        <div className="w-14 h-14 rounded-full flex items-center justify-center" style={{ background: TEAL_LIGHT }}>
          <Heart size={24} style={{ color: TEAL }} />
        </div>
        <p className="text-sm font-semibold text-slate-700">Health Coach</p>
        <p className="text-xs text-slate-500 max-w-xs">
          Your personalised health coaching will appear here after your discharge from the hospital. Please check back after your next admission.
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full" style={{ minHeight: "calc(100vh - 56px)" }}>
      {/* Header */}
      <div
        className="flex items-center gap-2 px-4 py-3 shrink-0"
        style={{ borderBottom: "1px solid #E2E8F0", background: "#fff" }}
      >
        <div className="w-8 h-8 rounded-full flex items-center justify-center" style={{ background: TEAL }}>
          <Heart size={16} className="text-white" />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-semibold text-slate-800">Health Coach</p>
          <p className="text-[10px] text-slate-500 truncate">
            {dischargeCtx.diagnosis} · {dischargeCtx.days_since_discharge} days since discharge
          </p>
        </div>
        <Badge
          className="text-[9px] px-1.5 py-0 shrink-0"
          style={{ background: "#FEF3C7", color: "#92400E", border: "none" }}
        >
          Class B · Not a doctor
        </Badge>
      </div>

      {/* Condition tips card */}
      {tips && (
        <div
          className="mx-4 mt-3 mb-1 rounded-xl overflow-hidden shrink-0"
          style={{ border: "1px solid #D1FAE5" }}
        >
          <button
            onClick={() => setTipsExpanded((p) => !p)}
            className="w-full flex items-center justify-between px-3 py-2 text-xs font-semibold"
            style={{ background: "#ECFDF5", color: "#065F46" }}
          >
            <span>💡 {conditionKey ? conditionKey.charAt(0).toUpperCase() + conditionKey.slice(1) : ""} Self-Care Tips</span>
            {tipsExpanded ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
          </button>
          {tipsExpanded && (
            <ul className="px-3 py-2 space-y-1.5" style={{ background: "#F0FDF4" }}>
              {tips.map((tip, i) => (
                <li key={i} className="text-xs text-slate-700 flex gap-2">
                  <span className="text-green-500 shrink-0">✓</span>
                  {tip}
                </li>
              ))}
            </ul>
          )}
        </div>
      )}

      {/* Chat */}
      <ScrollArea className="flex-1 px-4 py-3">
        {messages.length === 0 && (
          <div className="flex flex-col items-center gap-3 py-8 text-center">
            <p className="text-xs text-slate-500 max-w-xs">
              Hi {patient?.fullName?.split(" ")[0]}! I'm your recovery coach for <strong>{dischargeCtx.diagnosis}</strong>.
              Ask me about your medications, diet, exercises, or any symptoms you're experiencing.
            </p>
            <div className="flex flex-wrap gap-2 justify-center mt-2">
              {[
                "How should I manage my diet?",
                "When should I take my medications?",
                "What warning signs should I watch for?",
                "When is my follow-up appointment?",
              ].map((q) => (
                <button
                  key={q}
                  onClick={() => setInput(q)}
                  className="text-xs px-3 py-1.5 rounded-full border border-slate-200 text-slate-600 hover:border-teal-300 hover:text-teal-700 transition-colors bg-white"
                >
                  {q}
                </button>
              ))}
            </div>
          </div>
        )}

        <div className="space-y-3">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex gap-2 ${msg.role === "user" ? "flex-row-reverse" : "flex-row"}`}>
              <div
                className="w-7 h-7 rounded-full flex items-center justify-center shrink-0 mt-0.5"
                style={{ background: msg.role === "user" ? "#1A2F5A" : TEAL }}
              >
                {msg.role === "user"
                  ? <User size={13} className="text-white" />
                  : <Heart size={13} className="text-white" />}
              </div>
              <div
                className={`max-w-[78%] rounded-2xl px-3.5 py-2.5 text-sm leading-relaxed ${
                  msg.role === "user" ? "rounded-tr-sm text-white" : "rounded-tl-sm text-slate-800 border border-slate-100"
                }`}
                style={{ background: msg.role === "user" ? "#1A2F5A" : "#F8FAFC" }}
              >
                <p className="whitespace-pre-wrap">{msg.content}</p>
                <p className={`text-[9px] mt-1 ${msg.role === "user" ? "text-slate-300" : "text-slate-400"}`}>
                  {format(new Date(msg.created_at), "HH:mm")}
                </p>
              </div>
            </div>
          ))}

          {loading && (
            <div className="flex gap-2">
              <div className="w-7 h-7 rounded-full flex items-center justify-center shrink-0" style={{ background: TEAL }}>
                <Heart size={13} className="text-white" />
              </div>
              <div className="rounded-2xl rounded-tl-sm px-4 py-3 border border-slate-100" style={{ background: "#F8FAFC" }}>
                <div className="flex gap-1">
                  {[0, 1, 2].map((i) => (
                    <span key={i} className="w-1.5 h-1.5 rounded-full animate-bounce" style={{ background: TEAL, animationDelay: `${i * 150}ms` }} />
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
        <div ref={bottomRef} />
      </ScrollArea>

      {/* Input */}
      <div className="shrink-0 px-4 py-3" style={{ borderTop: "1px solid #E2E8F0", background: "#fff" }}>
        <p className="text-[9px] text-slate-400 mb-2 text-center">
          This coaching is based on your discharge records — not a substitute for your doctor's advice.
        </p>
        <div className="flex gap-2 items-end">
          <Textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendMessage(); } }}
            placeholder="Ask your health coach…"
            className="flex-1 resize-none text-sm"
            rows={2}
          />
          <Button
            onClick={sendMessage}
            disabled={loading || !input.trim()}
            size="sm"
            className="h-[52px] w-10 p-0 shrink-0"
            style={{ background: TEAL }}
          >
            {loading ? <Loader2 size={16} className="animate-spin" /> : <Send size={16} />}
          </Button>
        </div>
      </div>
    </div>
  );
};

export default PortalHealthCoachPage;

// Phase 6C — PHR Longitudinal AI (Patient Portal)
// Generates a patient-friendly "Your Health Story" narrative from the patient's full
// health records: admissions, diagnoses, procedures, labs, and medications.
// ABDM HIU-ready: if ABDM is configured, FHIR records are included in the context.
//
// SaMD Class A — narrative summary only; no diagnosis or treatment recommendation.

import React, { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { callAI } from "@/lib/aiProvider";
import { usePatientPortal } from "@/hooks/usePatientPortal";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Loader2, BookOpen, RefreshCw, Calendar, Pill, FlaskConical, Activity } from "lucide-react";
import { format, differenceInYears } from "date-fns";

const TEAL = "#0E7B7B";
const TEAL_LIGHT = "#E6F4F4";
const NAVY = "#1A2F5A";

interface HealthRecord {
  admissions: any[];
  diagnoses: string[];
  procedures: any[];
  recentLabs: any[];
  currentMeds: any[];
  conditions: string[];
}

const PortalHealthStoryPage: React.FC = () => {
  const { patientId, hospitalId, patient, hospital } = usePatientPortal();
  const [story, setStory] = useState<string>("");
  const [healthRecord, setHealthRecord] = useState<HealthRecord | null>(null);
  const [loading, setLoading] = useState(false);
  const [recordsLoading, setRecordsLoading] = useState(true);
  const [generatedAt, setGeneratedAt] = useState<Date | null>(null);


  const fetchRecords = useCallback(async () => {
    setRecordsLoading(true);
    try {
      const [admRes, rxRes, labRes, procRes] = await Promise.all([
        // Admissions history
        (supabase as any)
          .from("admissions")
          .select("admission_date, discharge_date, diagnosis, bed_number, status, ward_name")
          .eq("patient_id", patientId)
          .order("admission_date", { ascending: false })
          .limit(10),

        // Current medications
        (supabase as any)
          .from("prescriptions")
          .select("prescribed_date, drug_name, dosage, frequency, route")
          .eq("patient_id", patientId)
          .order("prescribed_date", { ascending: false })
          .limit(10),

        // Recent lab results
        (supabase as any)
          .from("lab_orders")
          .select("ordered_at, test_name, result_value, result_unit, flag, reference_range, status")
          .eq("patient_id", patientId)
          .eq("status", "resulted")
          .order("ordered_at", { ascending: false })
          .limit(12),

        // Procedures
        (supabase as any)
          .from("ot_cases")
          .select("surgery_date, procedure_name, surgeon_name, status")
          .eq("patient_id", patientId)
          .order("surgery_date", { ascending: false })
          .limit(5),
      ]);

      const admissions = admRes.data || [];
      const diagnoses: string[] = [];
      const conditions = new Set<string>();

      for (const adm of admissions) {
        if (adm.diagnosis) {
          diagnoses.push(adm.diagnosis);
          // Detect chronic conditions
          const d = adm.diagnosis.toLowerCase();
          if (d.includes("diabet")) conditions.add("Diabetes");
          if (d.includes("hypertens") || d.includes("htn")) conditions.add("Hypertension");
          if (d.includes("cardiac") || d.includes("heart failure") || d.includes("chf")) conditions.add("Cardiac Disease");
          if (d.includes("copd") || d.includes("asthma")) conditions.add("Respiratory Condition");
          if (d.includes("ckd") || d.includes("kidney")) conditions.add("Kidney Disease");
          if (d.includes("thyroid")) conditions.add("Thyroid Disorder");
        }
      }

      setHealthRecord({
        admissions,
        diagnoses,
        procedures: procRes.data || [],
        recentLabs: labRes.data || [],
        currentMeds: rxRes.data || [],
        conditions: [...conditions],
      });
    } finally {
      setRecordsLoading(false);
    }
  }, [patientId]);

  useEffect(() => {
    if (!patientId || !hospitalId) return;
    fetchRecords();
  }, [fetchRecords]);

  const buildRecordsSummary = (record: HealthRecord): string => {
    const parts: string[] = [];

    if (record.admissions.length > 0) {
      parts.push("HOSPITALISATIONS:");
      record.admissions.forEach((a: any) => {
        const admitted = a.admission_date ? format(new Date(a.admission_date), "dd/MM/yyyy") : "?";
        const discharged = a.discharge_date ? format(new Date(a.discharge_date), "dd/MM/yyyy") : (a.status === "active" ? "current" : "?");
        parts.push(`• ${admitted} → ${discharged}: ${a.diagnosis || "Not recorded"}${a.ward_name ? ` (${a.ward_name})` : ""}`);
      });
    }

    if (record.conditions.length > 0) {
      parts.push("\nCHRONIC CONDITIONS:");
      record.conditions.forEach((c) => parts.push(`• ${c}`));
    }

    if (record.procedures.length > 0) {
      parts.push("\nPROCEDURES / SURGERIES:");
      record.procedures.forEach((p: any) => {
        parts.push(`• ${p.procedure_name || "Procedure"} on ${p.surgery_date ? format(new Date(p.surgery_date), "dd/MM/yyyy") : "?"}${p.surgeon_name ? ` — ${p.surgeon_name}` : ""}`);
      });
    }

    if (record.currentMeds.length > 0) {
      parts.push("\nCURRENT MEDICATIONS:");
      record.currentMeds.forEach((m: any) => {
        parts.push(`• ${m.drug_name} ${m.dosage} — ${m.frequency} (${m.route})`);
      });
    }

    if (record.recentLabs.length > 0) {
      const abnormal = record.recentLabs.filter((l: any) => l.flag && l.flag !== "normal");
      if (abnormal.length > 0) {
        parts.push("\nABNORMAL LAB VALUES (recent):");
        abnormal.forEach((l: any) => {
          parts.push(`• ${l.test_name}: ${l.result_value} ${l.result_unit || ""} [${l.flag.toUpperCase()}] — ref: ${l.reference_range || "N/A"}`);
        });
      }
      const normal = record.recentLabs.filter((l: any) => !l.flag || l.flag === "normal").slice(0, 5);
      if (normal.length > 0) {
        parts.push("\nNORMAL LAB VALUES (recent):");
        normal.forEach((l: any) => {
          parts.push(`• ${l.test_name}: ${l.result_value} ${l.result_unit || ""} (normal)`);
        });
      }
    }

    return parts.join("\n") || "No significant health records available yet.";
  };

  const generateStory = async () => {
    if (!patientId || !hospitalId || !healthRecord) return;
    setLoading(true);

    try {
      const { data: promptRow } = await supabase
        .from("prompt_registry")
        .select("system_prompt")
        .eq("feature_key", "phr_health_story")
        .order("version", { ascending: false })
        .limit(1)
        .maybeSingle();

      const age = patient?.dob ? differenceInYears(new Date(), new Date(patient.dob)) : "Unknown";
      const recordsSummary = buildRecordsSummary(healthRecord);

      const prompt = (promptRow?.system_prompt || "")
        .replace("{{hospital_name}}", hospital?.name || "the hospital")
        .replace("{{patient_name}}", patient?.fullName || "the patient")
        .replace("{{age}}", String(age))
        .replace("{{gender}}", patient?.gender || "N/A")
        .replace("{{blood_group}}", patient?.bloodGroup || "Not recorded")
        .replace("{{health_records}}", recordsSummary);

      const response = await callAI({
        featureKey: "phr_health_story",
        hospitalId,
        prompt,
        maxTokens: 600,
      });

      setStory(response.text || "Unable to generate your health story right now. Please try again.");
      setGeneratedAt(new Date());
    } catch {
      setStory("Unable to generate your health story right now. Please try again later.");
    } finally {
      setLoading(false);
    }
  };

  const age = patient?.dob ? differenceInYears(new Date(), new Date(patient.dob)) : null;

  return (
    <div className="px-4 py-4 max-w-2xl mx-auto">
      {/* Hero header */}
      <div
        className="rounded-2xl p-4 mb-4 flex items-center gap-3"
        style={{ background: NAVY, color: "#fff" }}
      >
        <div className="w-12 h-12 rounded-xl flex items-center justify-center shrink-0" style={{ background: TEAL }}>
          <BookOpen size={22} className="text-white" />
        </div>
        <div>
          <h1 className="text-base font-bold">Your Health Story</h1>
          <p className="text-xs opacity-75 mt-0.5">
            A personalised summary of your health journey at {hospital?.name}
          </p>
        </div>
      </div>

      {/* Patient identity card */}
      <Card className="p-4 mb-4">
        <div className="flex items-center gap-4">
          <div
            className="w-12 h-12 rounded-full flex items-center justify-center text-white text-lg font-bold shrink-0"
            style={{ background: TEAL }}
          >
            {patient?.fullName?.split(" ").map((w) => w[0]).join("").slice(0, 2).toUpperCase()}
          </div>
          <div className="flex-1 min-w-0">
            <p className="font-semibold text-slate-800">{patient?.fullName}</p>
            <p className="text-xs text-slate-500">
              UHID: {patient?.uhid}
              {age ? ` · ${age} years` : ""}
              {patient?.gender ? ` · ${patient.gender}` : ""}
              {patient?.bloodGroup ? ` · ${patient.bloodGroup}` : ""}
            </p>
          </div>
        </div>

        {/* Chronic conditions */}
        {healthRecord && healthRecord.conditions.length > 0 && (
          <div className="mt-3 flex flex-wrap gap-1.5">
            {healthRecord.conditions.map((c) => (
              <Badge
                key={c}
                className="text-[10px]"
                style={{ background: TEAL_LIGHT, color: TEAL, border: "none" }}
              >
                {c}
              </Badge>
            ))}
          </div>
        )}
      </Card>

      {/* Records snapshot */}
      {!recordsLoading && healthRecord && (
        <div className="grid grid-cols-2 gap-3 mb-4">
          {[
            { icon: Calendar, label: "Hospitalisations", value: healthRecord.admissions.length, color: "#3B82F6" },
            { icon: Activity, label: "Procedures", value: healthRecord.procedures.length, color: "#8B5CF6" },
            { icon: FlaskConical, label: "Lab Results", value: healthRecord.recentLabs.length, color: "#0E7B7B" },
            { icon: Pill, label: "Medications", value: healthRecord.currentMeds.length, color: "#F59E0B" },
          ].map((stat) => (
            <Card key={stat.label} className="p-3 flex items-center gap-2.5">
              <div
                className="w-8 h-8 rounded-lg flex items-center justify-center shrink-0"
                style={{ background: `${stat.color}18` }}
              >
                <stat.icon size={16} style={{ color: stat.color }} />
              </div>
              <div>
                <p className="text-lg font-bold text-slate-800">{stat.value}</p>
                <p className="text-[10px] text-slate-500 leading-none">{stat.label}</p>
              </div>
            </Card>
          ))}
        </div>
      )}

      {recordsLoading && (
        <div className="flex justify-center py-6">
          <Loader2 size={20} className="animate-spin" style={{ color: TEAL }} />
        </div>
      )}

      {/* Generate / regenerate button */}
      {!recordsLoading && (
        <Button
          onClick={generateStory}
          disabled={loading}
          className="w-full mb-4"
          style={{ background: TEAL }}
        >
          {loading ? (
            <>
              <Loader2 size={16} className="mr-2 animate-spin" />
              Generating your health story…
            </>
          ) : story ? (
            <>
              <RefreshCw size={16} className="mr-2" />
              Regenerate Health Story
            </>
          ) : (
            <>
              <BookOpen size={16} className="mr-2" />
              Generate My Health Story
            </>
          )}
        </Button>
      )}

      {/* Generated narrative */}
      {story && (
        <Card className="p-4 mb-4">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-sm font-semibold text-slate-800">Your Health Narrative</h2>
            {generatedAt && (
              <span className="text-[10px] text-slate-400">
                Generated {format(generatedAt, "dd/MM/yyyy HH:mm")}
              </span>
            )}
          </div>
          <ScrollArea className="max-h-[400px]">
            <div className="space-y-3">
              {story.split("\n\n").filter(Boolean).map((para, i) => (
                <p key={i} className="text-sm text-slate-700 leading-relaxed">{para}</p>
              ))}
            </div>
          </ScrollArea>
          <div
            className="mt-4 rounded-lg px-3 py-2 text-[10px]"
            style={{ background: "#FEF3C7", color: "#92400E" }}
          >
            ⚠️ This narrative is generated from your records for informational purposes only. It is not a medical opinion and does not replace advice from your doctor.
          </div>
        </Card>
      )}

      {/* Recent history timeline */}
      {!recordsLoading && healthRecord && healthRecord.admissions.length > 0 && (
        <Card className="p-4">
          <h2 className="text-sm font-semibold text-slate-800 mb-3">Admission History</h2>
          <div className="space-y-3">
            {healthRecord.admissions.map((adm: any, i: number) => (
              <div key={i} className="flex gap-3">
                <div className="flex flex-col items-center shrink-0">
                  <div className="w-2 h-2 rounded-full mt-1.5" style={{ background: TEAL }} />
                  {i < healthRecord.admissions.length - 1 && (
                    <div className="flex-1 w-px mt-1" style={{ background: "#E2E8F0", minHeight: 20 }} />
                  )}
                </div>
                <div className="flex-1 pb-2">
                  <p className="text-xs font-semibold text-slate-700">{adm.diagnosis || "Not recorded"}</p>
                  <p className="text-[10px] text-slate-400 mt-0.5">
                    {adm.admission_date ? format(new Date(adm.admission_date), "dd/MM/yyyy") : "?"}{" "}
                    {adm.discharge_date ? `→ ${format(new Date(adm.discharge_date), "dd/MM/yyyy")}` : adm.status === "active" ? "(current)" : ""}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </Card>
      )}

      {!recordsLoading && healthRecord && healthRecord.admissions.length === 0 && !story && (
        <div className="text-center py-8">
          <BookOpen size={32} className="mx-auto mb-2 text-slate-300" />
          <p className="text-sm text-slate-500">No admission records found yet.</p>
          <p className="text-xs text-slate-400 mt-1">Your health story will grow with each visit to {hospital?.name}.</p>
        </div>
      )}
    </div>
  );
};

export default PortalHealthStoryPage;

import React, { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import type { PortalSession } from "./PortalLogin";
import { ChevronDown, ChevronUp, Download } from "lucide-react";

const PortalReports: React.FC<{ session: PortalSession }> = ({ session }) => {
  const [tab, setTab] = useState<"lab" | "radiology">("lab");

  return (
    <div className="px-4 py-0">
      <div className="flex" style={{ height: 44, borderBottom: "1px solid #E2E8F0" }}>
        {[
          { key: "lab" as const, label: "🔬 Lab Reports" },
          { key: "radiology" as const, label: "🩻 Radiology" },
        ].map((t) => (
          <button
            key={t.key}
            onClick={() => setTab(t.key)}
            className="flex-1 text-sm font-medium transition-colors"
            style={{
              color: tab === t.key ? "#0E7B7B" : "#94A3B8",
              borderBottom: tab === t.key ? "2px solid #0E7B7B" : "2px solid transparent",
            }}
          >
            {t.label}
          </button>
        ))}
      </div>

      {tab === "lab" ? <LabTab session={session} /> : <RadiologyTab session={session} />}
    </div>
  );
};

/* ═══════════════ LAB TAB ═══════════════ */
const LabTab: React.FC<{ session: PortalSession }> = ({ session }) => {
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState<string | null>(null);
  const [items, setItems] = useState<Record<string, any[]>>({});

  useEffect(() => {
    (async () => {
      const { data } = await supabase
        .from("lab_orders")
        .select("id, order_date, status, priority, clinical_notes, ordered_by")
        .eq("patient_id", session.patientId)
        .eq("hospital_id", session.hospitalId)
        .order("order_date", { ascending: false })
        .limit(30);

      // Get item counts + doctor name
      const enriched = await Promise.all(
        (data || []).map(async (o) => {
          const { data: orderItems } = await supabase
            .from("lab_order_items")
            .select("id, status")
            .eq("lab_order_id", o.id)
            .eq("hospital_id", session.hospitalId);

          const total = orderItems?.length || 0;
          const done = orderItems?.filter((i) => i.status === "reported" || i.status === "validated").length || 0;

          let doctorName = "";
          if (o.ordered_by) {
            const { data: doc } = await supabase.from("users").select("full_name").eq("id", o.ordered_by).maybeSingle();
            doctorName = doc?.full_name || "";
          }

          return { ...o, total, done, doctorName };
        })
      );

      setOrders(enriched);
      setLoading(false);
    })();
  }, [session]);

  // Load items on expand
  useEffect(() => {
    if (!expanded || items[expanded]) return;
    (async () => {
      const { data } = await supabase
        .from("lab_order_items")
        .select("id, test_id, status, result_value, result_unit, result_flag, reference_range")
        .eq("lab_order_id", expanded)
        .eq("hospital_id", session.hospitalId);

      const enriched = await Promise.all(
        (data || []).map(async (item) => {
          const { data: test } = await supabase
            .from("lab_test_master")
            .select("test_name")
            .eq("id", item.test_id)
            .maybeSingle();
          return { ...item, testName: test?.test_name || "Test" };
        })
      );
      setItems((prev) => ({ ...prev, [expanded]: enriched }));
    })();
  }, [expanded]);

  const getStatusBadge = (status: string) => {
    if (status === "completed" || status === "validated" || status === "reported")
      return { label: "✓ Ready", color: "#15803D", bg: "#DCFCE7" };
    if (status === "in_progress" || status === "sample_collected")
      return { label: "Processing", color: "#D97706", bg: "#FEF3C7" };
    return { label: "Pending", color: "#64748B", bg: "#F1F5F9" };
  };

  const handlePrintReport = (orderId: string) => {
    const orderItems = items[orderId];
    if (!orderItems) return;
    const order = orders.find((o) => o.id === orderId);

    const printWindow = window.open("", "_blank");
    if (!printWindow) return;

    printWindow.document.write(`
      <html><head><title>Lab Report</title>
      <style>
        body { font-family: Inter, sans-serif; padding: 32px; max-width: 700px; margin: 0 auto; }
        h1 { font-size: 18px; color: #0E7B7B; margin-bottom: 4px; }
        .info { font-size: 12px; color: #64748B; margin-bottom: 16px; }
        table { width: 100%; border-collapse: collapse; margin-top: 16px; }
        th { background: #F1F5F9; text-align: left; padding: 8px; font-size: 11px; text-transform: uppercase; color: #64748B; border: 1px solid #E2E8F0; }
        td { padding: 8px; font-size: 13px; border: 1px solid #E2E8F0; }
        .flag-high { color: #EF4444; font-weight: bold; }
        .flag-low { color: #F59E0B; font-weight: bold; }
        .footer { margin-top: 24px; font-size: 11px; color: #94A3B8; border-top: 1px solid #E2E8F0; padding-top: 12px; }
      </style></head><body>
        <h1>🔬 LAB REPORT</h1>
        <p class="info">
          Patient: ${session.fullName} · UHID: ${session.uhid}<br/>
          Date: ${new Date(order?.order_date).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" })}
          ${order?.doctorName ? ` · Dr. ${order.doctorName}` : ""}
        </p>
        <table>
          <tr><th>Test</th><th>Result</th><th>Unit</th><th>Ref. Range</th><th>Flag</th></tr>
          ${orderItems.map((i: any) => `
            <tr>
              <td>${i.testName}</td>
              <td>${i.result_value || "—"}</td>
              <td>${i.result_unit || ""}</td>
              <td>${i.reference_range || ""}</td>
              <td class="${i.result_flag === 'high' || i.result_flag === 'critical_high' ? 'flag-high' : i.result_flag === 'low' || i.result_flag === 'critical_low' ? 'flag-low' : ''}">${i.result_flag ? i.result_flag.toUpperCase() : "Normal"}</td>
            </tr>
          `).join("")}
        </table>
        <div class="footer">
          This report is for reference. Please discuss results with your doctor.<br/>
          ${session.hospitalName}
        </div>
        <script>window.onload=()=>window.print()</script>
      </body></html>
    `);
    printWindow.document.close();
  };

  return (
    <div className="py-4">
      {loading ? (
        <SkeletonList />
      ) : orders.length === 0 ? (
        <div className="bg-white rounded-xl p-10 text-center" style={{ border: "1px solid #E2E8F0" }}>
          <span className="text-[32px]">🔬</span>
          <p className="text-sm font-semibold mt-2" style={{ color: "#374151" }}>No lab reports yet</p>
          <p className="text-[13px] mt-1" style={{ color: "#94A3B8" }}>Your test results will appear here once ready</p>
        </div>
      ) : (
        <div className="space-y-2.5">
          {orders.map((o) => {
            const badge = getStatusBadge(o.status);
            const isExp = expanded === o.id;
            return (
              <div key={o.id} className="bg-white rounded-xl overflow-hidden" style={{ border: "1px solid #E2E8F0" }}>
                <button onClick={() => setExpanded(isExp ? null : o.id)} className="w-full p-3.5 text-left">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-xs" style={{ color: "#64748B" }}>
                      {new Date(o.order_date).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" })}
                    </span>
                    <span
                      className="text-[10px] font-bold uppercase px-2 py-0.5 rounded-full"
                      style={{ color: badge.color, background: badge.bg }}
                    >
                      {badge.label}
                    </span>
                  </div>
                  <p className="text-[13px] font-bold" style={{ color: "#0F172A" }}>
                    {o.done} of {o.total} tests complete
                  </p>
                  {o.doctorName && (
                    <p className="text-[11px] mt-0.5" style={{ color: "#94A3B8" }}>Ordered by Dr. {o.doctorName}</p>
                  )}
                  <div className="flex justify-end mt-0.5">
                    {isExp ? <ChevronUp size={14} color="#94A3B8" /> : <ChevronDown size={14} color="#94A3B8" />}
                  </div>
                </button>

                {isExp && (
                  <div className="px-3.5 pb-3.5" style={{ borderTop: "1px solid #F1F5F9" }}>
                    {!items[o.id] ? (
                      <p className="text-xs py-3 text-center" style={{ color: "#94A3B8" }}>Loading…</p>
                    ) : items[o.id].length === 0 ? (
                      <p className="text-xs py-3" style={{ color: "#94A3B8" }}>No test results yet</p>
                    ) : (
                      <>
                        <div className="space-y-1 py-2">
                          {items[o.id].map((item: any) => {
                            const isAbnormal = item.result_flag === "high" || item.result_flag === "low" ||
                              item.result_flag === "critical_high" || item.result_flag === "critical_low";
                            return (
                              <div key={item.id} className="flex items-center justify-between py-1.5">
                                <span className="text-xs font-medium" style={{ color: "#0F172A" }}>{item.testName}</span>
                                <div className="text-right">
                                  <span
                                    className="text-xs font-bold"
                                    style={{ color: isAbnormal ? "#EF4444" : "#0F172A" }}
                                  >
                                    {item.result_value || "—"} {item.result_unit || ""}
                                  </span>
                                  {item.reference_range && (
                                    <p className="text-[10px]" style={{ color: "#94A3B8" }}>Ref: {item.reference_range}</p>
                                  )}
                                </div>
                              </div>
                            );
                          })}
                        </div>
                        <button
                          onClick={() => handlePrintReport(o.id)}
                          className="w-full mt-2 rounded-lg flex items-center justify-center gap-2 text-sm font-bold py-2.5"
                          style={{ background: "#0E7B7B", color: "#FFFFFF" }}
                        >
                          <Download size={14} /> Download Report PDF
                        </button>
                      </>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

/* ═══════════════ RADIOLOGY TAB ═══════════════ */
const RadiologyTab: React.FC<{ session: PortalSession }> = ({ session }) => {
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState<string | null>(null);

  useEffect(() => {
    (async () => {
      const { data } = await supabase
        .from("radiology_orders")
        .select("id, study_name, modality_type, order_date, status, ordered_by")
        .eq("patient_id", session.patientId)
        .eq("hospital_id", session.hospitalId)
        .order("order_date", { ascending: false })
        .limit(30);

      const enriched = await Promise.all(
        (data || []).map(async (o) => {
          let doctorName = "";
          if (o.ordered_by) {
            const { data: doc } = await supabase.from("users").select("full_name").eq("id", o.ordered_by).maybeSingle();
            doctorName = doc?.full_name || "";
          }
          // Get report if exists
          let report: any = null;
          const { data: rep } = await supabase
            .from("radiology_reports")
            .select("impression, findings, recommendations, validated_at")
            .eq("order_id", o.id)
            .maybeSingle();
          if (rep) report = rep;

          return { ...o, doctorName, report };
        })
      );

      setOrders(enriched);
      setLoading(false);
    })();
  }, [session]);

  const getStatusBadge = (status: string, hasReport: boolean) => {
    if (hasReport || status === "validated" || status === "reported")
      return { label: "✓ Ready", color: "#15803D", bg: "#DCFCE7" };
    if (status === "in_progress" || status === "scheduled")
      return { label: "Processing", color: "#D97706", bg: "#FEF3C7" };
    return { label: "Pending", color: "#64748B", bg: "#F1F5F9" };
  };

  const MODALITY_COLORS: Record<string, string> = {
    "X-Ray": "#3B82F6", "CT": "#8B5CF6", "MRI": "#EC4899", "USG": "#0E7B7B",
    "Ultrasound": "#0E7B7B",
  };

  return (
    <div className="py-4">
      {loading ? (
        <SkeletonList />
      ) : orders.length === 0 ? (
        <div className="bg-white rounded-xl p-10 text-center" style={{ border: "1px solid #E2E8F0" }}>
          <span className="text-[32px]">🩻</span>
          <p className="text-sm font-semibold mt-2" style={{ color: "#374151" }}>No radiology reports yet</p>
          <p className="text-[13px] mt-1" style={{ color: "#94A3B8" }}>Your imaging results will appear here once ready</p>
        </div>
      ) : (
        <div className="space-y-2.5">
          {orders.map((o) => {
            const badge = getStatusBadge(o.status, !!o.report);
            const isExp = expanded === o.id;
            const modalityColor = MODALITY_COLORS[o.modality_type] || "#64748B";
            return (
              <div key={o.id} className="bg-white rounded-xl overflow-hidden" style={{ border: "1px solid #E2E8F0" }}>
                <button onClick={() => setExpanded(isExp ? null : o.id)} className="w-full p-3.5 text-left">
                  <div className="flex items-center justify-between mb-1">
                    <span
                      className="text-[10px] font-bold uppercase px-2 py-0.5 rounded-full"
                      style={{ color: modalityColor, background: `${modalityColor}15` }}
                    >
                      {o.modality_type}
                    </span>
                    <span
                      className="text-[10px] font-bold uppercase px-2 py-0.5 rounded-full"
                      style={{ color: badge.color, background: badge.bg }}
                    >
                      {badge.label}
                    </span>
                  </div>
                  <p className="text-[13px] font-bold mt-1" style={{ color: "#0F172A" }}>{o.study_name}</p>
                  <p className="text-xs mt-0.5" style={{ color: "#64748B" }}>
                    {new Date(o.order_date).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" })}
                    {o.doctorName && ` · Dr. ${o.doctorName}`}
                  </p>
                  {o.report && (
                    <div className="flex justify-end mt-0.5">
                      {isExp ? <ChevronUp size={14} color="#94A3B8" /> : <ChevronDown size={14} color="#94A3B8" />}
                    </div>
                  )}
                </button>

                {isExp && o.report && (
                  <div className="px-3.5 pb-3.5 space-y-2" style={{ borderTop: "1px solid #F1F5F9" }}>
                    {o.report.impression && (
                      <div>
                        <span className="text-[10px] font-bold uppercase" style={{ color: "#94A3B8" }}>Impression</span>
                        <p className="text-xs" style={{ color: "#374151" }}>{o.report.impression}</p>
                      </div>
                    )}
                    {o.report.findings && (
                      <div>
                        <span className="text-[10px] font-bold uppercase" style={{ color: "#94A3B8" }}>Findings</span>
                        <p className="text-xs" style={{ color: "#374151" }}>{o.report.findings}</p>
                      </div>
                    )}
                    {o.report.recommendations && (
                      <div>
                        <span className="text-[10px] font-bold uppercase" style={{ color: "#94A3B8" }}>Recommendations</span>
                        <p className="text-xs" style={{ color: "#374151" }}>{o.report.recommendations}</p>
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

